1	"use client";
2	
3	import { useEffect, useMemo, useState } from "react";
4	import { CardModal } from "@/components/CardModal";
5	import { MicButton } from "@/components/MicButton";
6	import { Board, Card, CardPatch, CardPriority, CardType, Column, parseLabels } from "@/lib/types";
7	
8	const PHASE_LABEL: Record<string, string> = {
9	  A: "Phase A · Blockers",
10	  B: "Phase B · Finish the MVP",
11	  C: "Phase C · Operate & grow",
12	  D: "Phase D · Backend & moat",
13	};
14	
15	const TYPE_COLOR: Record<CardType, string> = {
16	  IDEA: "var(--phase-d)",
17	  FEATURE: "var(--accent)",
18	  BUG: "var(--phase-a)",
19	  CHORE: "var(--faint)",
20	};
21	
22	const PRIORITY_DOT: Record<CardPriority, string> = {
23	  LOW: "var(--faint)",
24	  NORMAL: "var(--ink-2)",
25	  HIGH: "var(--phase-b)",
26	  URGENT: "var(--phase-a)",
27	};
28	
29	function PhaseBadge({ phase }: { phase: Card["phase"] }) {
30	  if (!phase) return null;
31	  return (
32	    <span
33	      className="inline-flex items-center rounded-full px-2 py-0.5 font-mono text-[10px] font-medium uppercase tracking-wide"
34	      style={{
35	        color: `var(--phase-${phase.toLowerCase()})`,
36	        background: `color-mix(in srgb, var(--phase-${phase.toLowerCase()}) 12%, transparent)`,
37	      }}
38	      title={PHASE_LABEL[phase]}
39	    >
40	      {phase}
41	    </span>
42	  );
43	}
44	
45	export default function BoardPage() {
46	  const [boards, setBoards] = useState<Board[]>([]);
47	  const [boardId, setBoardId] = useState<string | null>(null);
48	  const [columns, setColumns] = useState<Column[]>([]);
49	  const [cards, setCards] = useState<Card[]>([]);
50	  const [newCardText, setNewCardText] = useState<Record<string, string>>({});
51	  const [newColumnName, setNewColumnName] = useState("");
52	  const [dragging, setDragging] = useState<string | null>(null);
53	  const [loading, setLoading] = useState(true);
54	  const [showArchived, setShowArchived] = useState(false);
55	  const [openCardId, setOpenCardId] = useState<string | null>(null);
56	  const [addingBoard, setAddingBoard] = useState(false);
57	  const [newBoardName, setNewBoardName] = useState("");
58	
59	  useEffect(() => {
60	    fetch("/api/boards")
61	      .then((r) => r.json())
62	      .then((d) => {
63	        setBoards(d.boards ?? []);
64	        setBoardId((prev) => prev ?? d.boards?.[0]?.id ?? null);
65	      });
66	  }, []);
67	
68	  useEffect(() => {
69	    if (boardId === null && boards.length === 0) return;
70	    setLoading(true);
71	    const url = boardId ? `/api/board?boardId=${boardId}` : "/api/board";
72	    fetch(url)
73	      .then((r) => r.json())
74	      .then((d) => {
75	        setColumns(d.columns ?? []);
76	        setCards(d.cards ?? []);
77	        setLoading(false);
78	      });
79	  }, [boardId, boards.length]);
80	
81	  const openCard = useMemo(() => cards.find((c) => c.id === openCardId) ?? null, [cards, openCardId]);
82	
83	  async function addCard(columnId: string) {
84	    const title = (newCardText[columnId] ?? "").trim();
85	    if (!title) return;
86	    setNewCardText((s) => ({ ...s, [columnId]: "" }));
87	    const res = await fetch("/api/board", {
88	      method: "POST",
89	      headers: { "Content-Type": "application/json" },
90	      body: JSON.stringify({ columnId, title }),
91	    });
92	    const { card } = await res.json();
93	    if (card) setCards((c) => [...c, { ...card, attachmentCount: 0, commentCount: 0 }]);
94	  }
95	
96	  async function deleteCard(id: string) {
97	    setCards((c) => c.filter((x) => x.id !== id));
98	    if (openCardId === id) setOpenCardId(null);
99	    await fetch(`/api/cards/${id}`, { method: "DELETE" });
100	  }
101	
102	  async function moveCard(cardId: string, columnId: string) {
103	    const position = cards.filter((c) => c.columnId === columnId).length;
104	    setCards((c) => c.map((x) => (x.id === cardId ? { ...x, columnId, position } : x)));
105	    await fetch(`/api/cards/${cardId}`, {
106	      method: "PATCH",
107	      headers: { "Content-Type": "application/json" },
108	      body: JSON.stringify({ columnId, position }),
109	    });
110	  }
111	
112	  async function updateCard(patch: CardPatch) {
113	    const { id, ...rest } = patch;
114	    setCards((c) =>
115	      c.map((x) => {
116	        if (x.id !== id) return x;
117	        const next = { ...x };
118	        if (rest.title !== undefined) next.title = rest.title;
119	        if (rest.description !== undefined) next.description = rest.description;
120	        if (rest.type !== undefined) next.type = rest.type;
121	        if (rest.priority !== undefined) next.priority = rest.priority;
122	        if (rest.labels !== undefined) next.labels = JSON.stringify(rest.labels);
123	        if (rest.assignee !== undefined) next.assignee = rest.assignee;
124	        if (rest.archived !== undefined) next.archivedAt = rest.archived ? new Date().toISOString() : null;
125	        return next;
126	      }),
127	    );
128	    await fetch(`/api/cards/${id}`, {
129	      method: "PATCH",
130	      headers: { "Content-Type": "application/json" },
131	      body: JSON.stringify(rest),
132	    });
133	  }
134	
135	  async function addColumn() {
136	    const name = newColumnName.trim();
137	    if (!name || !boardId) return;
138	    setNewColumnName("");
139	    const res = await fetch("/api/columns", {
140	      method: "POST",
141	      headers: { "Content-Type": "application/json" },
