1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { marked } from "marked";
5	import { MicButton } from "@/components/MicButton";
6	import {
7	  Attachment,
8	  CARD_PRIORITIES,
9	  CARD_TYPES,
10	  Card,
11	  CardPatch,
12	  Comment,
13	  CardPriority,
14	  CardType,
15	  parseLabels,
16	} from "@/lib/types";
17	
18	const TYPE_COLOR: Record<CardType, string> = {
19	  IDEA: "var(--phase-d)",
20	  FEATURE: "var(--accent)",
21	  BUG: "var(--phase-a)",
22	  CHORE: "var(--faint)",
23	};
24	
25	const PRIORITY_COLOR: Record<CardPriority, string> = {
26	  LOW: "var(--faint)",
27	  NORMAL: "var(--ink-2)",
28	  HIGH: "var(--phase-b)",
29	  URGENT: "var(--phase-a)",
30	};
31	
32	function fmtSize(bytes: number) {
33	  if (bytes < 1024) return `${bytes} B`;
34	  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
35	  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
36	}
37	
38	function fileToBase64(file: File): Promise<string> {
39	  return new Promise((resolve, reject) => {
40	    const reader = new FileReader();
41	    reader.onload = () => resolve((reader.result as string).split(",")[1] ?? "");
42	    reader.onerror = reject;
43	    reader.readAsDataURL(file);
44	  });
45	}
46	
47	export function CardModal({
48	  card,
49	  onClose,
50	  onUpdate,
51	  onDelete,
52	}: {
53	  card: Card;
54	  onClose: () => void;
55	  onUpdate: (patch: CardPatch) => void;
56	  onDelete: (id: string) => void;
57	}) {
58	  const [title, setTitle] = useState(card.title);
59	  const [description, setDescription] = useState(card.description);
60	  const [editingDescription, setEditingDescription] = useState(!card.description);
61	  const [labelInput, setLabelInput] = useState("");
62	  const [labels, setLabels] = useState<string[]>(parseLabels(card.labels));
63	  const [assignee, setAssignee] = useState(card.assignee ?? "");
64	  const [attachments, setAttachments] = useState<Attachment[]>([]);
65	  const [comments, setComments] = useState<Comment[]>([]);
66	  const [newComment, setNewComment] = useState("");
67	  const [uploading, setUploading] = useState(false);
68	  const dropRef = useRef<HTMLDivElement>(null);
69	  const fileInputRef = useRef<HTMLInputElement>(null);
70	
71	  useEffect(() => {
72	    fetch(`/api/cards/${card.id}/attachments`)
73	      .then((r) => r.json())
74	      .then((d) => setAttachments(d.attachments ?? []));
75	    fetch(`/api/cards/${card.id}/comments`)
76	      .then((r) => r.json())
77	      .then((d) => setComments(d.comments ?? []));
78	  }, [card.id]);
79	
80	  function saveTitle() {
81	    const t = title.trim();
82	    if (t && t !== card.title) onUpdate({ id: card.id, title: t });
83	  }
84	
85	  function saveDescription() {
86	    if (description !== card.description) onUpdate({ id: card.id, description });
87	    setEditingDescription(false);
88	  }
89	
90	  function commitLabels(next: string[]) {
91	    setLabels(next);
92	    onUpdate({ id: card.id, labels: next });
93	  }
94	
95	  function addLabel() {
96	    const l = labelInput.trim();
97	    if (!l || labels.includes(l)) {
98	      setLabelInput("");
99	      return;
100	    }
101	    commitLabels([...labels, l]);
102	    setLabelInput("");
103	  }
104	
105	  function removeLabel(l: string) {
106	    commitLabels(labels.filter((x) => x !== l));
107	  }
108	
109	  async function uploadFiles(files: FileList | File[]) {
110	    setUploading(true);
111	    try {
112	      for (const file of Array.from(files)) {
113	        const dataBase64 = await fileToBase64(file);
114	        const res = await fetch(`/api/cards/${card.id}/attachments`, {
115	          method: "POST",
116	          headers: { "Content-Type": "application/json" },
117	          body: JSON.stringify({ filename: file.name, mime: file.type, dataBase64 }),
118	        });
119	        const { attachment } = await res.json();
120	        if (attachment) setAttachments((a) => [...a, attachment]);
121	      }
122	    } finally {
123	      setUploading(false);
124	    }
125	  }
126	
127	  async function deleteAttachment(id: string) {
128	    setAttachments((a) => a.filter((x) => x.id !== id));
129	    await fetch(`/api/attachments/${id}`, { method: "DELETE" });
130	  }
131	
132	  async function postComment() {
133	    const body = newComment.trim();
134	    if (!body) return;
135	    setNewComment("");
136	    const res = await fetch(`/api/cards/${card.id}/comments`, {
137	      method: "POST",
138	      headers: { "Content-Type": "application/json" },
139	      body: JSON.stringify({ body }),
140	    });
141	    const { comment } = await res.json();
142	    if (comment) setComments((c) => [...c, comment]);
143	  }
144	
145	  async function deleteComment(id: string) {
146	    setComments((c) => c.filter((x) => x.id !== id));
147	    await fetch(`/api/comments/${id}`, { method: "DELETE" });
148	  }
149	
150	  const onPaste = useCallback(
151	    (e: ClipboardEvent) => {
152	      const items = e.clipboardData?.items;
153	      if (!items) return;
154	      const files: File[] = [];
155	      for (const item of Array.from(items)) {
156	        if (item.kind === "file") {
157	          const f = item.getAsFile();
158	          if (f) files.push(f);
159	        }
160	      }
161	      if (files.length) {
162	        e.preventDefault();
163	        uploadFiles(files);
164	      }
165	    },
166	    [card.id],
167	  );
168	
169	  useEffect(() => {
170	    document.addEventListener("paste", onPaste);
171	    return () => document.removeEventListener("paste", onPaste);
172	  }, [onPaste]);
173	
174	  const html = editingDescription ? "" : (marked.parse(description || "*No description yet.*") as string);
175	
176	  return (
177	    <div
178	      className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto p-4 py-10 sm:p-8"
179	      style={{ background: "color-mix(in srgb, #000 55%, transparent)" }}
180	      onClick={onClose}
181	    >
182	      <div
183	        onClick={(e) => e.stopPropagation()}
184	        className="w-full max-w-2xl rounded-2xl border p-6"
185	        style={{ borderColor: "var(--line)", background: "var(--panel)", boxShadow: "var(--sh-s)" }}
186	      >
187	        <div className="flex items-start justify-between gap-3">
188	          <div className="flex flex-1 items-center gap-2">
189	            <input
190	              value={title}
191	              onChange={(e) => setTitle(e.target.value)}
192	              onBlur={saveTitle}
193	              onKeyDown={(e) => {
194	                if (e.key === "Enter") (e.target as HTMLInputElement).blur();
195	              }}
196	              className="w-full rounded-lg bg-transparent px-1 py-1 text-lg font-semibold outline-none"
197	            />
198	            <MicButton value={title} onChange={setTitle} />
199	          </div>
200	          <button
201	            onClick={onClose}
202	            aria-label="Close"
203	            className="shrink-0 rounded-md p-1 text-[var(--faint)] hover:text-[var(--foreground)]"
204	          >
205	            ✕
206	          </button>
207	        </div>
208	
209	        <div className="mt-4 flex flex-wrap items-center gap-2">
210	          <select
211	            value={card.type}
212	            onChange={(e) => onUpdate({ id: card.id, type: e.target.value as CardType })}
213	            className="rounded-md border bg-transparent px-2 py-1 text-xs font-medium outline-none"
214	            style={{ borderColor: "var(--line)", color: TYPE_COLOR[card.type] }}
215	          >
216	            {CARD_TYPES.map((t) => (
217	              <option key={t} value={t}>
218	                {t}
219	              </option>
220	            ))}
221	          </select>
222	          <select
223	            value={card.priority}
224	            onChange={(e) => onUpdate({ id: card.id, priority: e.target.value as CardPriority })}
225	            className="rounded-md border bg-transparent px-2 py-1 text-xs font-medium outline-none"
226	            style={{ borderColor: "var(--line)", color: PRIORITY_COLOR[card.priority] }}
227	          >
228	            {CARD_PRIORITIES.map((p) => (
229	              <option key={p} value={p}>
230	                {p}
231	              </option>
232	            ))}
233	          </select>
234	          <input
235	            value={assignee}
236	            onChange={(e) => setAssignee(e.target.value)}
237	            onBlur={() => onUpdate({ id: card.id, assignee: assignee || null })}
238	            placeholder="Unassigned"
239	            className="w-32 rounded-md border bg-transparent px-2 py-1 text-xs outline-none placeholder:text-[var(--faint)]"
240	            style={{ borderColor: "var(--line)" }}
241	          />
242	          <button
