"use client";

import { useEffect, useRef, useState } from "react";

type SpeechRecognitionLike = {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start: () => void;
  stop: () => void;
  onresult: ((e: any) => void) | null;
  onend: (() => void) | null;
  onerror: ((e: any) => void) | null;
};

function getSpeechRecognition(): (new () => SpeechRecognitionLike) | null {
  if (typeof window === "undefined") return null;
  return (window as any).SpeechRecognition ?? (window as any).webkitSpeechRecognition ?? null;
}

const ERROR_MESSAGES: Record<string, string> = {
  "not-allowed": "Microphone access was denied — allow it in your browser's site settings.",
  "service-not-allowed": "Microphone access was denied — allow it in your browser's site settings.",
  "audio-capture": "No microphone found.",
  "no-speech": "Didn't catch any speech — try again.",
  network: "Speech recognition needs a network connection.",
  aborted: "",
};

export function useVoiceInput(value: string, onChange: (next: string) => void) {
