"use client";

import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragOverlay,
  DragStartEvent,
  PointerSensor,
  useDroppable,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { SortableContext, useSortable, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { CardModal } from "@/components/CardModal";
import { MicButton } from "@/components/MicButton";
import { ThemeToggle } from "@/components/ThemeToggle";
import { Board, Card, CardPatch, CardPriority, CardType, Column, parseLabels } from "@/lib/types";

const PHASE_LABEL: Record<string, string> = {
  A: "Phase A · Blockers",
  B: "Phase B · Finish the MVP",
  C: "Phase C · Operate & grow",
  D: "Phase D · Backend & moat",
};

const TYPE_COLOR: Record<CardType, string> = {
  IDEA: "var(--phase-d)",
  FEATURE: "var(--accent)",
  BUG: "var(--phase-a)",
  CHORE: "var(--faint)",
};

const PRIORITY_DOT: Record<CardPriority, string> = {
  LOW: "var(--faint)",
  NORMAL: "var(--ink-2)",
  HIGH: "var(--phase-b)",
  URGENT: "var(--phase-a)",
};

const TRASH_ID = "__trash__";

function PhaseBadge({ phase }: { phase: Card["phase"] }) {
  if (!phase) return null;
  return (
    <span
      className="inline-flex items-center rounded-full px-2 py-0.5 font-mono text-[10px] font-medium uppercase tracking-wide"
      style={{
        color: `var(--phase-${phase.toLowerCase()})`,
        background: `color-mix(in srgb, var(--phase-${phase.toLowerCase()}) 12%, transparent)`,
      }}
      title={PHASE_LABEL[phase]}
    >
      {phase}
    </span>
  );
}

function matchesSearch(card: Card, query: string) {
  if (!query) return true;
  const q = query.toLowerCase();
  return (
    card.title.toLowerCase().includes(q) ||
    card.description.toLowerCase().includes(q) ||
    parseLabels(card.labels).some((l) => l.toLowerCase().includes(q)) ||
    (card.assignee ?? "").toLowerCase().includes(q)
  );
}

function CardTile({
  card,
  onOpen,
  onDelete,
  dragOverlay = false,
}: {
  card: Card;
  onOpen?: () => void;
  onDelete?: () => void;
  dragOverlay?: boolean;
}) {
  const sortable = useSortable({ id: card.id, disabled: dragOverlay, data: { columnId: card.columnId } });
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = dragOverlay
    ? ({} as ReturnType<typeof useSortable>)
    : sortable;

  const labels = parseLabels(card.labels);
  const style = dragOverlay
    ? undefined
    : {
        transform: CSS.Transform.toString(transform ?? null),
        transition: transition ?? undefined,
        opacity: isDragging ? 0.4 : 1,
      };

  return (
    <div
      ref={dragOverlay ? undefined : setNodeRef}
      style={{ ...style, borderColor: "var(--line)", background: "var(--background)" }}
      {...(dragOverlay ? {} : attributes)}
      {...(dragOverlay ? {} : listeners)}
      onClick={onOpen}
      className={`group rounded-xl border p-3 ${dragOverlay ? "rotate-2 cursor-grabbing shadow-[var(--sh-s)]" : "cursor-grab touch-none active:cursor-grabbing"}`}
    >
      <div className="flex items-start justify-between gap-2">
        <p className="text-sm font-medium leading-snug">{card.title}</p>
        {onDelete && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onDelete();
            }}
            className="shrink-0 text-[var(--faint)] opacity-0 transition-opacity hover:text-[var(--accent)] group-hover:opacity-100"
            aria-label="Delete card"
          >
            ×
          </button>
        )}
      </div>
      {card.description && (
        <p className="mt-1.5 line-clamp-2 text-xs leading-relaxed text-[var(--ink-2)]">{card.description}</p>
      )}
      <div className="mt-2 flex flex-wrap items-center gap-1.5">
        <PhaseBadge phase={card.phase} />
        <span
          className="inline-flex items-center rounded-full px-2 py-0.5 font-mono text-[10px] font-medium"
          style={{ color: TYPE_COLOR[card.type], background: `color-mix(in srgb, ${TYPE_COLOR[card.type]} 12%, transparent)` }}
        >
          {card.type}
        </span>
        <span className="inline-block h-1.5 w-1.5 rounded-full" style={{ background: PRIORITY_DOT[card.priority] }} title={card.priority} />
        {labels.map((l) => (
          <span key={l} className="rounded-full bg-[var(--line-2)] px-2 py-0.5 text-[10px] text-[var(--ink-2)]">
            {l}
          </span>
        ))}
        {card.assignee && <span className="text-[10px] text-[var(--faint)]">@{card.assignee}</span>}
        {card.attachmentCount > 0 && <span className="text-[10px] text-[var(--faint)]">📎 {card.attachmentCount}</span>}
        {card.commentCount > 0 && <span className="text-[10px] text-[var(--faint)]">💬 {card.commentCount}</span>}
      </div>
    </div>
  );
}

function ColumnView({
  column,
  cards,
  showArchived,
  newCardText,
  onNewCardTextChange,
  onAddCard,
  onRenameColumn,
  onDeleteColumn,
  onOpenCard,
  onDeleteCard,
}: {
  column: Column;
  cards: Card[];
  showArchived: boolean;
  newCardText: string;
  onNewCardTextChange: (v: string) => void;
  onAddCard: () => void;
  onRenameColumn: (name: string) => void;
  onDeleteColumn: () => void;
  onOpenCard: (id: string) => void;
  onDeleteCard: (id: string) => void;
}) {
  const { setNodeRef, isOver } = useDroppable({ id: column.id, data: { columnId: column.id } });

  return (
    <div
      ref={setNodeRef}
      className="flex h-full min-w-[190px] max-w-[320px] flex-1 flex-col rounded-2xl border p-2.5 transition-colors"
      style={{
        borderColor: isOver ? "var(--accent)" : "var(--line)",
        background: "var(--panel)",
        boxShadow: "var(--sh-s)",
      }}
    >
      <div className="flex items-center justify-between gap-2 px-1 pb-2.5">
        <input
          value={column.name}
          onChange={(e) => onRenameColumn(e.target.value)}
          className="w-full truncate bg-transparent text-sm font-semibold outline-none"
        />
        <span className="shrink-0 font-mono text-xs text-[var(--faint)]">{cards.length}</span>
        <button
          onClick={onDeleteColumn}
          aria-label={`Delete column ${column.name}`}
          className="shrink-0 text-[var(--faint)] hover:text-[var(--phase-a)]"
        >
          ×
        </button>
      </div>

      <div className="thin-scroll flex min-h-[40px] flex-1 flex-col gap-2 overflow-y-auto px-0.5">
        <SortableContext items={cards.map((c) => c.id)} strategy={verticalListSortingStrategy}>
          {cards.map((card) => (
            <CardTile key={card.id} card={card} onOpen={() => onOpenCard(card.id)} onDelete={() => onDeleteCard(card.id)} />
          ))}
        </SortableContext>
      </div>

      {!showArchived && (
        <div className="mt-2 flex items-center gap-1.5 px-0.5 pt-1">
          <input
            value={newCardText}
            onChange={(e) => onNewCardTextChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") onAddCard();
            }}
            placeholder="Add a card…"
            className="w-full rounded-lg border bg-transparent px-2.5 py-1.5 text-xs outline-none placeholder:text-[var(--faint)]"
            style={{ borderColor: "var(--line)" }}
          />
          <MicButton value={newCardText} onChange={onNewCardTextChange} />
        </div>
      )}
    </div>
  );
}

function TrashZone({ active }: { active: boolean }) {
  const { setNodeRef, isOver } = useDroppable({ id: TRASH_ID });
  if (!active) return null;
  return (
    <div
      ref={setNodeRef}
      className="pointer-events-auto fixed bottom-6 left-1/2 z-50 flex -translate-x-1/2 items-center gap-2 rounded-full border px-5 py-3 text-sm font-medium shadow-[var(--sh-s)] transition-colors"
      style={{
        borderColor: isOver ? "var(--phase-a)" : "var(--line)",
        background: isOver ? "color-mix(in srgb, var(--phase-a) 16%, var(--panel))" : "var(--panel)",
        color: isOver ? "var(--phase-a)" : "var(--ink-2)",
      }}
    >
      🗑 {isOver ? "Release to delete" : "Drag here to delete"}
    </div>
  );
}

export default function BoardPage() {
  const [boards, setBoards] = useState<Board[]>([]);
  const [boardId, setBoardId] = useState<string | null>(null);
  const [columns, setColumns] = useState<Column[]>([]);
  const [cards, setCards] = useState<Card[]>([]);
  const [newCardText, setNewCardText] = useState<Record<string, string>>({});
  const [newColumnName, setNewColumnName] = useState("");
  const [activeId, setActiveId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [showArchived, setShowArchived] = useState(false);
  const [openCardId, setOpenCardId] = useState<string | null>(null);
  const [addingBoard, setAddingBoard] = useState(false);
  const [newBoardName, setNewBoardName] = useState("");
  const [search, setSearch] = useState("");

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }));

  useEffect(() => {
    fetch("/api/boards")
      .then((r) => r.json())
      .then((d) => {
        setBoards(d.boards ?? []);
        setBoardId((prev) => prev ?? d.boards?.[0]?.id ?? null);
      });
  }, []);

  useEffect(() => {
    if (boardId === null && boards.length === 0) return;
    setLoading(true);
    const url = boardId ? `/api/board?boardId=${boardId}` : "/api/board";
    fetch(url)
      .then((r) => r.json())
      .then((d) => {
        setColumns(d.columns ?? []);
        setCards(d.cards ?? []);
        setLoading(false);
      });
  }, [boardId, boards.length]);

  const openCard = useMemo(() => cards.find((c) => c.id === openCardId) ?? null, [cards, openCardId]);
  const activeCard = useMemo(() => cards.find((c) => c.id === activeId) ?? null, [cards, activeId]);

  const visibleCards = useMemo(
    () => cards.filter((c) => !!c.archivedAt === showArchived && matchesSearch(c, search)),
    [cards, showArchived, search],
  );

  async function addCard(columnId: string) {
    const title = (newCardText[columnId] ?? "").trim();
    if (!title) return;
    setNewCardText((s) => ({ ...s, [columnId]: "" }));
    const res = await fetch("/api/board", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ columnId, title }),
    });
    const { card } = await res.json();
    if (card) setCards((c) => [...c, { ...card, attachmentCount: 0, commentCount: 0 }]);
  }

  async function deleteCard(id: string) {
    setCards((c) => c.filter((x) => x.id !== id));
    if (openCardId === id) setOpenCardId(null);
    await fetch(`/api/cards/${id}`, { method: "DELETE" });
  }

  async function updateCard(patch: CardPatch) {
    const { id, ...rest } = patch;
    setCards((c) =>
      c.map((x) => {
        if (x.id !== id) return x;
        const next = { ...x };
        if (rest.title !== undefined) next.title = rest.title;
        if (rest.description !== undefined) next.description = rest.description;
        if (rest.type !== undefined) next.type = rest.type;
        if (rest.priority !== undefined) next.priority = rest.priority;
        if (rest.labels !== undefined) next.labels = JSON.stringify(rest.labels);
        if (rest.assignee !== undefined) next.assignee = rest.assignee;
        if (rest.archived !== undefined) next.archivedAt = rest.archived ? new Date().toISOString() : null;
        return next;
      }),
    );
    await fetch(`/api/cards/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(rest),
    });
  }

  async function addColumn() {
    const name = newColumnName.trim();
    if (!name || !boardId) return;
    setNewColumnName("");
    const res = await fetch("/api/columns", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ boardId, name }),
    });
    const { column } = await res.json();
    if (column) setColumns((c) => [...c, column]);
  }

  async function renameColumn(id: string, name: string) {
    setColumns((c) => c.map((x) => (x.id === id ? { ...x, name } : x)));
    await fetch(`/api/columns/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
  }

  async function deleteColumn(id: string) {
    if (!confirm("Delete this column and all its cards?")) return;
    setColumns((c) => c.filter((x) => x.id !== id));
    setCards((c) => c.filter((x) => x.columnId !== id));
    await fetch(`/api/columns/${id}`, { method: "DELETE" });
  }

  async function createBoard() {
    const name = newBoardName.trim();
    if (!name) return;
    setNewBoardName("");
    setAddingBoard(false);
    const res = await fetch("/api/boards", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    const { board } = await res.json();
    if (board) {
      setBoards((b) => [...b, board]);
      setBoardId(board.id);
    }
  }

  function resolveColumnId(overId: string | null): string | null {
    if (!overId) return null;
    const overCard = cards.find((c) => c.id === overId);
    if (overCard) return overCard.columnId;
    if (columns.some((col) => col.id === overId)) return overId;
    return null;
  }

  function handleDragStart(e: DragStartEvent) {
    setActiveId(String(e.active.id));
  }

  // Live cross-column preview while dragging, so the card visibly moves as
  // you drag it over another column instead of only snapping on drop.
  function handleDragOver(e: DragOverEvent) {
    const { active, over } = e;
    if (!over || over.id === TRASH_ID) return;
    const activeCardNow = cards.find((c) => c.id === active.id);
    if (!activeCardNow) return;
    const destColumnId = resolveColumnId(String(over.id));
    if (!destColumnId || destColumnId === activeCardNow.columnId) return;

    setCards((prev) => {
      const destCount = prev.filter((c) => c.columnId === destColumnId).length;
      return prev.map((c) => (c.id === active.id ? { ...c, columnId: destColumnId, position: destCount } : c));
    });
  }

  async function handleDragEnd(e: DragEndEvent) {
    const { active, over } = e;
    setActiveId(null);
    if (!over) return;

    const draggedId = String(active.id);
    const dragged = cards.find((c) => c.id === draggedId);
    if (!dragged) return;

    if (over.id === TRASH_ID) {
      deleteCard(draggedId);
      return;
    }

    const destColumnId = resolveColumnId(String(over.id)) ?? dragged.columnId;
    const overCard = cards.find((c) => c.id === over.id);

    // Recompute final order within the destination column, inserting the
    // dragged card next to whatever it was dropped on (or at the end).
    const destSiblings = cards
      .filter((c) => c.columnId === destColumnId && c.id !== draggedId)
      .sort((a, b) => a.position - b.position);

    let insertAt = destSiblings.length;
    if (overCard && overCard.id !== draggedId) {
      insertAt = destSiblings.findIndex((c) => c.id === overCard.id);
      if (insertAt === -1) insertAt = destSiblings.length;
    }

    const reordered = [...destSiblings.slice(0, insertAt), dragged, ...destSiblings.slice(insertAt)].map((c, i) => ({
      ...c,
      columnId: destColumnId,
      position: i,
    }));

    const changed = reordered.filter((c) => {
      const before = cards.find((x) => x.id === c.id);
      return !before || before.columnId !== c.columnId || before.position !== c.position;
    });

    setCards((prev) => {
      const byId = new Map(reordered.map((c) => [c.id, c]));
      return prev.map((c) => byId.get(c.id) ?? c);
    });

    for (const c of changed) {
      await fetch(`/api/cards/${c.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ columnId: c.columnId, position: c.position }),
      });
    }
  }

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center text-sm text-[var(--faint)]">Loading board…</div>
    );
  }

  return (
    <DndContext sensors={sensors} onDragStart={handleDragStart} onDragOver={handleDragOver} onDragEnd={handleDragEnd}>
      <div className="flex h-screen flex-col overflow-hidden px-6 py-5 sm:px-8">
        <header className="mb-4 flex shrink-0 flex-wrap items-start justify-between gap-3">
          <div>
            <p className="font-mono text-xs font-medium uppercase tracking-[0.14em] text-[var(--faint)]">
              Personal build board
            </p>
            <h1 className="mt-1 text-2xl font-semibold tracking-tight">
              <span className="brand-gradient-text">kodely</span> board
            </h1>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search cards…"
              className="w-44 rounded-lg border bg-transparent px-3 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
              style={{ borderColor: "var(--line)" }}
            />
            <select
              value={boardId ?? ""}
              onChange={(e) => setBoardId(e.target.value)}
              className="rounded-lg border bg-transparent px-3 py-1.5 text-sm outline-none"
              style={{ borderColor: "var(--line)" }}
            >
              {boards.map((b) => (
                <option key={b.id} value={b.id}>
                  {b.name}
                </option>
              ))}
            </select>
            {addingBoard ? (
              <input
                autoFocus
                value={newBoardName}
                onChange={(e) => setNewBoardName(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && createBoard()}
                onBlur={() => (newBoardName.trim() ? createBoard() : setAddingBoard(false))}
                placeholder="Board name…"
                className="w-36 rounded-lg border bg-transparent px-2.5 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
                style={{ borderColor: "var(--line)" }}
              />
            ) : (
              <button
                onClick={() => setAddingBoard(true)}
                className="rounded-lg border px-3 py-1.5 text-sm text-[var(--ink-2)] hover:text-[var(--accent)]"
                style={{ borderColor: "var(--line)" }}
              >
                + Board
              </button>
            )}
            <button
              onClick={() => setShowArchived((s) => !s)}
              className="rounded-lg border px-3 py-1.5 text-sm"
              style={{
                borderColor: "var(--line)",
                color: showArchived ? "var(--accent)" : "var(--ink-2)",
                background: showArchived ? "color-mix(in srgb, var(--accent) 10%, transparent)" : "transparent",
              }}
            >
              {showArchived ? "Showing archived" : "Show archived"}
            </button>
            <ThemeToggle />
          </div>
        </header>

        <div className="flex min-h-0 flex-1 gap-3 overflow-x-auto pb-1">
          {columns.map((col) => {
            const colCards = visibleCards.filter((c) => c.columnId === col.id).sort((a, b) => a.position - b.position);
            return (
              <ColumnView
                key={col.id}
                column={col}
                cards={colCards}
                showArchived={showArchived}
                newCardText={newCardText[col.id] ?? ""}
                onNewCardTextChange={(v) => setNewCardText((s) => ({ ...s, [col.id]: v }))}
                onAddCard={() => addCard(col.id)}
                onRenameColumn={(name) => renameColumn(col.id, name)}
                onDeleteColumn={() => deleteColumn(col.id)}
                onOpenCard={setOpenCardId}
                onDeleteCard={deleteCard}
              />
            );
          })}

          <div
            className="flex w-48 shrink-0 flex-col gap-1.5 rounded-2xl border border-dashed p-2.5"
            style={{ borderColor: "var(--line)" }}
          >
            <input
              value={newColumnName}
              onChange={(e) => setNewColumnName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addColumn()}
              placeholder="+ Add column…"
              className="w-full rounded-lg bg-transparent px-2 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
            />
          </div>
        </div>

        {openCard && (
          <CardModal card={openCard} onClose={() => setOpenCardId(null)} onUpdate={updateCard} onDelete={deleteCard} />
        )}
      </div>

      <TrashZone active={activeId !== null} />
      <DragOverlay>{activeCard ? <CardTile card={activeCard} dragOverlay /> : null}</DragOverlay>
    </DndContext>
  );
}

toolUseResult.content:
"use client";

import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragOverlay,
  DragStartEvent,
  PointerSensor,
  useDroppable,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { SortableContext, useSortable, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { CardModal } from "@/components/CardModal";
import { MicButton } from "@/components/MicButton";
import { ThemeToggle } from "@/components/ThemeToggle";
import { Board, Card, CardPatch, CardPriority, CardType, Column, parseLabels } from "@/lib/types";

const PHASE_LABEL: Record<string, string> = {
  A: "Phase A · Blockers",
  B: "Phase B · Finish the MVP",
  C: "Phase C · Operate & grow",
  D: "Phase D · Backend & moat",
};

const TYPE_COLOR: Record<CardType, string> = {
  IDEA: "var(--phase-d)",
  FEATURE: "var(--accent)",
  BUG: "var(--phase-a)",
  CHORE: "var(--faint)",
};

const PRIORITY_DOT: Record<CardPriority, string> = {
  LOW: "var(--faint)",
  NORMAL: "var(--ink-2)",
  HIGH: "var(--phase-b)",
  URGENT: "var(--phase-a)",
};

const TRASH_ID = "__trash__";

function PhaseBadge({ phase }: { phase: Card["phase"] }) {
  if (!phase) return null;
  return (
    <span
      className="inline-flex items-center rounded-full px-2 py-0.5 font-mono text-[10px] font-medium uppercase tracking-wide"
      style={{
        color: `var(--phase-${phase.toLowerCase()})`,
        background: `color-mix(in srgb, var(--phase-${phase.toLowerCase()}) 12%, transparent)`,
      }}
      title={PHASE_LABEL[phase]}
    >
      {phase}
    </span>
  );
}

function matchesSearch(card: Card, query: string) {
  if (!query) return true;
  const q = query.toLowerCase();
  return (
    card.title.toLowerCase().includes(q) ||
    card.description.toLowerCase().includes(q) ||
    parseLabels(card.labels).some((l) => l.toLowerCase().includes(q)) ||
    (card.assignee ?? "").toLowerCase().includes(q)
  );
}

function CardTile({
  card,
  onOpen,
  onDelete,
  dragOverlay = false,
}: {
  card: Card;
  onOpen?: () => void;
  onDelete?: () => void;
  dragOverlay?: boolean;
}) {
  const sortable = useSortable({ id: card.id, disabled: dragOverlay, data: { columnId: card.columnId } });
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = dragOverlay
    ? ({} as ReturnType<typeof useSortable>)
    : sortable;

  const labels = parseLabels(card.labels);
  const style = dragOverlay
    ? undefined
    : {
        transform: CSS.Transform.toString(transform ?? null),
        transition: transition ?? undefined,
        opacity: isDragging ? 0.4 : 1,
      };

  return (
    <div
      ref={dragOverlay ? undefined : setNodeRef}
      style={{ ...style, borderColor: "var(--line)", background: "var(--background)" }}
      {...(dragOverlay ? {} : attributes)}
      {...(dragOverlay ? {} : listeners)}
      onClick={onOpen}
      className={`group rounded-xl border p-3 ${dragOverlay ? "rotate-2 cursor-grabbing shadow-[var(--sh-s)]" : "cursor-grab touch-none active:cursor-grabbing"}`}
    >
      <div className="flex items-start justify-between gap-2">
        <p className="text-sm font-medium leading-snug">{card.title}</p>
        {onDelete && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onDelete();
            }}
            className="shrink-0 text-[var(--faint)] opacity-0 transition-opacity hover:text-[var(--accent)] group-hover:opacity-100"
            aria-label="Delete card"
          >
            ×
          </button>
        )}
      </div>
      {card.description && (
        <p className="mt-1.5 line-clamp-2 text-xs leading-relaxed text-[var(--ink-2)]">{card.description}</p>
      )}
      <div className="mt-2 flex flex-wrap items-center gap-1.5">
        <PhaseBadge phase={card.phase} />
        <span
          className="inline-flex items-center rounded-full px-2 py-0.5 font-mono text-[10px] font-medium"
          style={{ color: TYPE_COLOR[card.type], background: `color-mix(in srgb, ${TYPE_COLOR[card.type]} 12%, transparent)` }}
        >
          {card.type}
        </span>
        <span className="inline-block h-1.5 w-1.5 rounded-full" style={{ background: PRIORITY_DOT[card.priority] }} title={card.priority} />
        {labels.map((l) => (
          <span key={l} className="rounded-full bg-[var(--line-2)] px-2 py-0.5 text-[10px] text-[var(--ink-2)]">
            {l}
          </span>
        ))}
        {card.assignee && <span className="text-[10px] text-[var(--faint)]">@{card.assignee}</span>}
        {card.attachmentCount > 0 && <span className="text-[10px] text-[var(--faint)]">📎 {card.attachmentCount}</span>}
        {card.commentCount > 0 && <span className="text-[10px] text-[var(--faint)]">💬 {card.commentCount}</span>}
      </div>
    </div>
  );
}

function ColumnView({
  column,
  cards,
  showArchived,
  newCardText,
  onNewCardTextChange,
  onAddCard,
  onRenameColumn,
  onDeleteColumn,
  onOpenCard,
  onDeleteCard,
}: {
  column: Column;
  cards: Card[];
  showArchived: boolean;
  newCardText: string;
  onNewCardTextChange: (v: string) => void;
  onAddCard: () => void;
  onRenameColumn: (name: string) => void;
  onDeleteColumn: () => void;
  onOpenCard: (id: string) => void;
  onDeleteCard: (id: string) => void;
}) {
  const { setNodeRef, isOver } = useDroppable({ id: column.id, data: { columnId: column.id } });

  return (
    <div
      ref={setNodeRef}
      className="flex h-full min-w-[190px] max-w-[320px] flex-1 flex-col rounded-2xl border p-2.5 transition-colors"
      style={{
        borderColor: isOver ? "var(--accent)" : "var(--line)",
        background: "var(--panel)",
        boxShadow: "var(--sh-s)",
      }}
    >
      <div className="flex items-center justify-between gap-2 px-1 pb-2.5">
        <input
          value={column.name}
          onChange={(e) => onRenameColumn(e.target.value)}
          className="w-full truncate bg-transparent text-sm font-semibold outline-none"
        />
        <span className="shrink-0 font-mono text-xs text-[var(--faint)]">{cards.length}</span>
        <button
          onClick={onDeleteColumn}
          aria-label={`Delete column ${column.name}`}
          className="shrink-0 text-[var(--faint)] hover:text-[var(--phase-a)]"
        >
          ×
        </button>
      </div>

      <div className="thin-scroll flex min-h-[40px] flex-1 flex-col gap-2 overflow-y-auto px-0.5">
        <SortableContext items={cards.map((c) => c.id)} strategy={verticalListSortingStrategy}>
          {cards.map((card) => (
            <CardTile key={card.id} card={card} onOpen={() => onOpenCard(card.id)} onDelete={() => onDeleteCard(card.id)} />
          ))}
        </SortableContext>
      </div>

      {!showArchived && (
        <div className="mt-2 flex items-center gap-1.5 px-0.5 pt-1">
          <input
            value={newCardText}
            onChange={(e) => onNewCardTextChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") onAddCard();
            }}
            placeholder="Add a card…"
            className="w-full rounded-lg border bg-transparent px-2.5 py-1.5 text-xs outline-none placeholder:text-[var(--faint)]"
            style={{ borderColor: "var(--line)" }}
          />
          <MicButton value={newCardText} onChange={onNewCardTextChange} />
        </div>
      )}
    </div>
  );
}

function TrashZone({ active }: { active: boolean }) {
  const { setNodeRef, isOver } = useDroppable({ id: TRASH_ID });
  if (!active) return null;
  return (
    <div
      ref={setNodeRef}
      className="pointer-events-auto fixed bottom-6 left-1/2 z-50 flex -translate-x-1/2 items-center gap-2 rounded-full border px-5 py-3 text-sm font-medium shadow-[var(--sh-s)] transition-colors"
      style={{
        borderColor: isOver ? "var(--phase-a)" : "var(--line)",
        background: isOver ? "color-mix(in srgb, var(--phase-a) 16%, var(--panel))" : "var(--panel)",
        color: isOver ? "var(--phase-a)" : "var(--ink-2)",
      }}
    >
      🗑 {isOver ? "Release to delete" : "Drag here to delete"}
    </div>
  );
}

export default function BoardPage() {
  const [boards, setBoards] = useState<Board[]>([]);
  const [boardId, setBoardId] = useState<string | null>(null);
  const [columns, setColumns] = useState<Column[]>([]);
  const [cards, setCards] = useState<Card[]>([]);
  const [newCardText, setNewCardText] = useState<Record<string, string>>({});
  const [newColumnName, setNewColumnName] = useState("");
  const [activeId, setActiveId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [showArchived, setShowArchived] = useState(false);
  const [openCardId, setOpenCardId] = useState<string | null>(null);
  const [addingBoard, setAddingBoard] = useState(false);
  const [newBoardName, setNewBoardName] = useState("");
  const [search, setSearch] = useState("");

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 6 } }));

  useEffect(() => {
    fetch("/api/boards")
      .then((r) => r.json())
      .then((d) => {
        setBoards(d.boards ?? []);
        setBoardId((prev) => prev ?? d.boards?.[0]?.id ?? null);
      });
  }, []);

  useEffect(() => {
    if (boardId === null && boards.length === 0) return;
    setLoading(true);
    const url = boardId ? `/api/board?boardId=${boardId}` : "/api/board";
    fetch(url)
      .then((r) => r.json())
      .then((d) => {
        setColumns(d.columns ?? []);
        setCards(d.cards ?? []);
        setLoading(false);
      });
  }, [boardId, boards.length]);

  const openCard = useMemo(() => cards.find((c) => c.id === openCardId) ?? null, [cards, openCardId]);
  const activeCard = useMemo(() => cards.find((c) => c.id === activeId) ?? null, [cards, activeId]);

  const visibleCards = useMemo(
    () => cards.filter((c) => !!c.archivedAt === showArchived && matchesSearch(c, search)),
    [cards, showArchived, search],
  );

  async function addCard(columnId: string) {
    const title = (newCardText[columnId] ?? "").trim();
    if (!title) return;
    setNewCardText((s) => ({ ...s, [columnId]: "" }));
    const res = await fetch("/api/board", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ columnId, title }),
    });
    const { card } = await res.json();
    if (card) setCards((c) => [...c, { ...card, attachmentCount: 0, commentCount: 0 }]);
  }

  async function deleteCard(id: string) {
    setCards((c) => c.filter((x) => x.id !== id));
    if (openCardId === id) setOpenCardId(null);
    await fetch(`/api/cards/${id}`, { method: "DELETE" });
  }

  async function updateCard(patch: CardPatch) {
    const { id, ...rest } = patch;
    setCards((c) =>
      c.map((x) => {
        if (x.id !== id) return x;
        const next = { ...x };
        if (rest.title !== undefined) next.title = rest.title;
        if (rest.description !== undefined) next.description = rest.description;
        if (rest.type !== undefined) next.type = rest.type;
        if (rest.priority !== undefined) next.priority = rest.priority;
        if (rest.labels !== undefined) next.labels = JSON.stringify(rest.labels);
        if (rest.assignee !== undefined) next.assignee = rest.assignee;
        if (rest.archived !== undefined) next.archivedAt = rest.archived ? new Date().toISOString() : null;
        return next;
      }),
    );
    await fetch(`/api/cards/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(rest),
    });
  }

  async function addColumn() {
    const name = newColumnName.trim();
    if (!name || !boardId) return;
    setNewColumnName("");
    const res = await fetch("/api/columns", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ boardId, name }),
    });
    const { column } = await res.json();
    if (column) setColumns((c) => [...c, column]);
  }

  async function renameColumn(id: string, name: string) {
    setColumns((c) => c.map((x) => (x.id === id ? { ...x, name } : x)));
    await fetch(`/api/columns/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
  }

  async function deleteColumn(id: string) {
    if (!confirm("Delete this column and all its cards?")) return;
    setColumns((c) => c.filter((x) => x.id !== id));
    setCards((c) => c.filter((x) => x.columnId !== id));
    await fetch(`/api/columns/${id}`, { method: "DELETE" });
  }

  async function createBoard() {
    const name = newBoardName.trim();
    if (!name) return;
    setNewBoardName("");
    setAddingBoard(false);
    const res = await fetch("/api/boards", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    const { board } = await res.json();
    if (board) {
      setBoards((b) => [...b, board]);
      setBoardId(board.id);
    }
  }

  function resolveColumnId(overId: string | null): string | null {
    if (!overId) return null;
    const overCard = cards.find((c) => c.id === overId);
    if (overCard) return overCard.columnId;
    if (columns.some((col) => col.id === overId)) return overId;
    return null;
  }

  function handleDragStart(e: DragStartEvent) {
    setActiveId(String(e.active.id));
  }

  // Live cross-column preview while dragging, so the card visibly moves as
  // you drag it over another column instead of only snapping on drop.
  function handleDragOver(e: DragOverEvent) {
    const { active, over } = e;
    if (!over || over.id === TRASH_ID) return;
    const activeCardNow = cards.find((c) => c.id === active.id);
    if (!activeCardNow) return;
    const destColumnId = resolveColumnId(String(over.id));
    if (!destColumnId || destColumnId === activeCardNow.columnId) return;

    setCards((prev) => {
      const destCount = prev.filter((c) => c.columnId === destColumnId).length;
      return prev.map((c) => (c.id === active.id ? { ...c, columnId: destColumnId, position: destCount } : c));
    });
  }

  async function handleDragEnd(e: DragEndEvent) {
    const { active, over } = e;
    setActiveId(null);
    if (!over) return;

    const draggedId = String(active.id);
    const dragged = cards.find((c) => c.id === draggedId);
    if (!dragged) return;

    if (over.id === TRASH_ID) {
      deleteCard(draggedId);
      return;
    }

    const destColumnId = resolveColumnId(String(over.id)) ?? dragged.columnId;
    const overCard = cards.find((c) => c.id === over.id);

    // Recompute final order within the destination column, inserting the
    // dragged card next to whatever it was dropped on (or at the end).
    const destSiblings = cards
      .filter((c) => c.columnId === destColumnId && c.id !== draggedId)
      .sort((a, b) => a.position - b.position);

    let insertAt = destSiblings.length;
    if (overCard && overCard.id !== draggedId) {
      insertAt = destSiblings.findIndex((c) => c.id === overCard.id);
      if (insertAt === -1) insertAt = destSiblings.length;
    }

    const reordered = [...destSiblings.slice(0, insertAt), dragged, ...destSiblings.slice(insertAt)].map((c, i) => ({
      ...c,
      columnId: destColumnId,
      position: i,
    }));

    const changed = reordered.filter((c) => {
      const before = cards.find((x) => x.id === c.id);
      return !before || before.columnId !== c.columnId || before.position !== c.position;
    });

    setCards((prev) => {
      const byId = new Map(reordered.map((c) => [c.id, c]));
      return prev.map((c) => byId.get(c.id) ?? c);
    });

    for (const c of changed) {
      await fetch(`/api/cards/${c.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ columnId: c.columnId, position: c.position }),
      });
    }
  }

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center text-sm text-[var(--faint)]">Loading board…</div>
    );
  }

  return (
    <DndContext sensors={sensors} onDragStart={handleDragStart} onDragOver={handleDragOver} onDragEnd={handleDragEnd}>
      <div className="flex h-screen flex-col overflow-hidden px-6 py-5 sm:px-8">
        <header className="mb-4 flex shrink-0 flex-wrap items-start justify-between gap-3">
          <div>
            <p className="font-mono text-xs font-medium uppercase tracking-[0.14em] text-[var(--faint)]">
              Personal build board
            </p>
            <h1 className="mt-1 text-2xl font-semibold tracking-tight">
              <span className="brand-gradient-text">kodely</span> board
            </h1>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search cards…"
              className="w-44 rounded-lg border bg-transparent px-3 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
              style={{ borderColor: "var(--line)" }}
            />
            <select
              value={boardId ?? ""}
              onChange={(e) => setBoardId(e.target.value)}
              className="rounded-lg border bg-transparent px-3 py-1.5 text-sm outline-none"
              style={{ borderColor: "var(--line)" }}
            >
              {boards.map((b) => (
                <option key={b.id} value={b.id}>
                  {b.name}
                </option>
              ))}
            </select>
            {addingBoard ? (
              <input
                autoFocus
                value={newBoardName}
                onChange={(e) => setNewBoardName(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && createBoard()}
                onBlur={() => (newBoardName.trim() ? createBoard() : setAddingBoard(false))}
                placeholder="Board name…"
                className="w-36 rounded-lg border bg-transparent px-2.5 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
                style={{ borderColor: "var(--line)" }}
              />
            ) : (
              <button
                onClick={() => setAddingBoard(true)}
                className="rounded-lg border px-3 py-1.5 text-sm text-[var(--ink-2)] hover:text-[var(--accent)]"
                style={{ borderColor: "var(--line)" }}
              >
                + Board
              </button>
            )}
            <button
              onClick={() => setShowArchived((s) => !s)}
              className="rounded-lg border px-3 py-1.5 text-sm"
              style={{
                borderColor: "var(--line)",
                color: showArchived ? "var(--accent)" : "var(--ink-2)",
                background: showArchived ? "color-mix(in srgb, var(--accent) 10%, transparent)" : "transparent",
              }}
            >
              {showArchived ? "Showing archived" : "Show archived"}
            </button>
            <ThemeToggle />
          </div>
        </header>

        <div className="flex min-h-0 flex-1 gap-3 overflow-x-auto pb-1">
          {columns.map((col) => {
            const colCards = visibleCards.filter((c) => c.columnId === col.id).sort((a, b) => a.position - b.position);
            return (
              <ColumnView
                key={col.id}
                column={col}
                cards={colCards}
                showArchived={showArchived}
                newCardText={newCardText[col.id] ?? ""}
                onNewCardTextChange={(v) => setNewCardText((s) => ({ ...s, [col.id]: v }))}
                onAddCard={() => addCard(col.id)}
                onRenameColumn={(name) => renameColumn(col.id, name)}
                onDeleteColumn={() => deleteColumn(col.id)}
                onOpenCard={setOpenCardId}
                onDeleteCard={deleteCard}
              />
            );
          })}

          <div
            className="flex w-48 shrink-0 flex-col gap-1.5 rounded-2xl border border-dashed p-2.5"
            style={{ borderColor: "var(--line)" }}
          >
            <input
              value={newColumnName}
              onChange={(e) => setNewColumnName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addColumn()}
              placeholder="+ Add column…"
              className="w-full rounded-lg bg-transparent px-2 py-1.5 text-sm outline-none placeholder:text-[var(--faint)]"
            />
          </div>
        </div>

        {openCard && (
          <CardModal card={openCard} onClose={() => setOpenCardId(null)} onUpdate={updateCard} onDelete={deleteCard} />
        )}
      </div>

      <TrashZone active={activeId !== null} />
      <DragOverlay>{activeCard ? <CardTile card={activeCard} dragOverlay /> : null}</DragOverlay>
    </DndContext>
  );
}

