(function(){
  const cards = [...document.querySelectorAll('.group.cursor-grab')];
  const first = cards[0];
  const r1 = first.getBoundingClientRect();
  const colDivs = [...document.querySelectorAll('[class*="thin-scroll"]')];
  const targetCol = colDivs[1];
  const r2 = targetCol.getBoundingClientRect();
  const startX = r1.x + r1.width/2, startY = r1.y + 20;
  const endX = r2.x + r2.width/2, endY = r2.y + 30;

  function fire(el, type, x, y) {
    const ev = new PointerEvent(type, { bubbles: true, cancelable: true, pointerId: 1, pointerType: 'mouse', clientX: x, clientY: y, button: 0 });
    el.dispatchEvent(ev);
  }
  fire(first, 'pointerdown', startX, startY);
  fire(document, 'pointermove', startX + 10, startY + 5);
  fire(document, 'pointermove', (startX+endX)/2, (startY+endY)/2);
  fire(document, 'pointermove', endX, endY);
  fire(document, 'pointerup', endX, endY);
  return document.querySelectorAll('.group.cursor-grab').length;
})();

