(function(){
  const textarea = document.querySelector('textarea[placeholder*="Describe the site"]');
  const composer = textarea.closest('.relative.z-10');
  const composerStyle = getComputedStyle(composer);
  return JSON.stringify({
    composerBg: composerStyle.backgroundColor,
    composerZ: composerStyle.zIndex,
  });
})();

(function(){
  const glowLayers = [...document.querySelectorAll('[aria-hidden="true"]')].filter(el => getComputedStyle(el).background.includes('conic-gradient') || el.style.background.includes('conic-gradient'));
  return JSON.stringify({count: glowLayers.length, transforms: glowLayers.map(el => getComputedStyle(el).transform)});
})();

(function(){
  const glowLayers = [...document.querySelectorAll('[aria-hidden="true"]')].filter(el => el.style.background && el.style.background.includes('conic-gradient'));
  return JSON.stringify({count: glowLayers.length, transforms: glowLayers.map(el => getComputedStyle(el).transform)});
})();

(function(){
  const glowLayers = [...document.querySelectorAll('[aria-hidden="true"]')].filter(el => el.style.background && el.style.background.includes('conic-gradient'));
  return JSON.stringify({
    count: glowLayers.length,
    inlineStyles: glowLayers.map(el => el.getAttribute('style')),
    visibilityState: document.visibilityState,
    hidden: document.hidden,
  });
})();

