/* The prompt-box glow ring (PromptHero) — a Gemini-style "chasing light"
   ring. CRITICAL: the ring's own box never rotates. Earlier versions
   animated `transform: rotate()` on the ring element itself, which — since
   the composer is a wide rectangle, not a square — swings the corners way
   outside the box's footprint at 30-60deg (a wide rect rotated about its
   center sweeps a much larger diamond-shaped envelope), then back into
   alignment near 0/90/180/270deg. That's what read as "a giant blob that
   then disappears": it never disappeared, it was cycling through a much
   bigger silhouette than the box. The fix is to keep the ring's shape
   perfectly static and instead animate the *angle fed into the conic
   gradient* via a registered custom property (@property is required for
   the browser to animate it smoothly rather than snapping) — the ring
   never moves, only the color chases around inside it. */
@property --glow-angle-a {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
@property --glow-angle-b {
  syntax: "<angle>";
  inherits: false;
  initial-value: 180deg;
}
@keyframes glow-angle-spin-a {
  to {
    --glow-angle-a: 360deg;
  }
}
@keyframes glow-angle-spin-b {
  to {
    --glow-angle-b: -180deg;
  }
}

/* Entrance fade-in — plain CSS, not a framer-motion `whileInView`. That
   depends on IntersectionObserver + React state + framer's own scheduling,
   any one of which is a potential point of silent failure I can't fully
   rule out from this environment. This has none of that: it's guaranteed by
   the browser to run once on mount, no JS involved at all. `forwards` is
   load-bearing — without it, the element snaps back to its non-animated
   base style (invisible) the instant the animation's single iteration
   ends, which is exactly the "fades in, then permanently gone" bug being
   chased here. Runs as a second, independent `animation` alongside the
   infinite angle-spin below (a comma-separated animation list; both target
   different properties, so they don't conflict). */
@keyframes glow-fade-in-a {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes glow-fade-in-b {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
  to {
    opacity: 0.6;
    transform: scale(1);
  }
}
.glow-ring-a {
  animation:
    glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
    glow-angle-spin-a 6s linear infinite;
}
.glow-ring-b {
  animation:
    glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,
    glow-angle-spin-b 9s linear infinite;
}

