@import "tailwindcss";

/* Class-based dark mode (".dark" on <html>) so the manual theme toggle can
   override the OS preference — Tailwind's dark: classes elsewhere in the
   app are unaffected in shape, only in what triggers them. */
@custom-variant dark (&:where(.dark, .dark *));

:root {
  --background: #ffffff;
  --foreground: #171717;

  /* Kodely brand tokens — ported 1:1 from the approved reference mockup
     (scratchpad/kodely.html) so the shipped site and the approved design
     don't drift again. */
  --ink-2: #605b66;
  --faint: #a49fad;
  --line: rgba(11, 10, 13, 0.09);
  --line-2: rgba(11, 10, 13, 0.045);
  --panel: #ffffff;
  --accent: #e01b6e;
  --glow: rgba(247, 37, 112, 0.13);
  --glow-2: rgba(163, 61, 255, 0.12);
  --sh-s: 0 1px 2px rgba(11, 10, 13, 0.04), 0 6px 16px -8px rgba(11, 10, 13, 0.1);
  --sh: 0 40px 100px -50px rgba(120, 40, 160, 0.3), 0 18px 50px -30px rgba(11, 10, 13, 0.16);

  --brand-gradient: linear-gradient(100deg, #f72570 0%, #ff6b67 44%, #ff9868 66%, #a33dff 100%);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root:not(.light) {
    --background: #0a0a0a;
    --foreground: #ededed;
    --ink-2: #a8a1b0;
    --faint: #5f5869;
    --line: rgba(246, 243, 247, 0.1);
    --line-2: rgba(246, 243, 247, 0.05);
    --panel: #100e15;
