const fileInputRef = useRef<HTMLInputElement>(null);
const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
const baseValueRef = useRef("");

// Liquid-glass droplets that bead up along the bottom edge and fall while
// the user types. Each is removed on its own animationend, so there are no
// timers to leak and the list can never grow unbounded. Spawning is
// throttled — one droplet per keystroke would be a flood at typing speed.
const [drips, setDrips] = useState<{ id: number; left: number; drift: number }[]>([]);
const dripIdRef = useRef(0);
const lastDripAtRef = useRef(0);

function spawnDrip() {
  const now = performance.now();
  if (now - lastDripAtRef.current < 170) return;
  lastDripAtRef.current = now;
  const id = ++dripIdRef.current;
  setDrips((d) => [
    ...d,
    // left: keep clear of the rounded corners. drift: a little sideways
    // wander on the way down so they don't all fall dead straight.
    { id, left: 14 + Math.random() * 72, drift: (Math.random() - 0.5) * 14 },
  ]);
}

