(function(){
  const url = [...document.querySelectorAll('*')].find(el => el.textContent.trim() === 'new-project.kodely.site' || el.textContent.trim() === 'bloom-pilates.kodely.site');
  const mock = url ? url.closest('.mx-auto.w-full.max-w-2xl') : null;
  if (!mock) return "mock not found";
  const r = mock.getBoundingClientRect();
  const vh = window.innerHeight;
  const visible = Math.max(0, Math.min(r.bottom, vh) - Math.max(r.top, 0));
  return JSON.stringify({
    viewportHeight: vh,
    mockTop: Math.round(r.top),
    mockHeight: Math.round(r.height),
    fractionVisibleAtPageLoad: +(visible / r.height).toFixed(2),
    threshold: 0.3,
    firesOnLoad: (visible / r.height) >= 0.3,
    hasDripsLeft: document.querySelectorAll('.glass-drip').length,
  }, null, 1);
})();

