const typed = useTypewriter(PROMPT_TEXT, phase === "typing", 34);
const dots = useEllipsis(phase === "building");

// Scroll entrance driven by a plain IntersectionObserver + a CSS class,
// not framer-motion's `whileInView`. Framer applied its `initial` styles
// correctly here but the in-view trigger never fired in practice, and a
// raw observer has no dependency on framer's internal scheduling. It's
// also directly verifiable: the observer callback and the class swap are
// ordinary DOM work, unlike an animation that only exists mid-frame.
const frameRef = useRef<HTMLDivElement>(null);
const [entered, setEntered] = useState(false);

useEffect(() => {
  const el = frameRef.current;
  if (!el) return;
  // amount ~0.3: wait until a real portion of the frame is on screen, so
  // the entrance plays as you arrive at it rather than the instant its
  // top edge clears the fold (which finished before it was ever properly
  // in view).
  const observer = new IntersectionObserver(
    ([entry]) => {
      if (entry.isIntersecting) {
        setEntered(true);
        observer.disconnect();
      }
    },
    { threshold: 0.3 },
  );
  observer.observe(el);
  return () => observer.disconnect();
}, []);

