@supports (animation-timeline: view()) {
  .hero-mock-enter {
    /* Longhands, not the `animation` shorthand: the shorthand defaults
       animation-duration to 0s when it's omitted, which — combined with
       fill:both — snapped straight to the end state at every scroll
       position (i.e. no visible animation at all). Scroll-driven
       animations need `auto`, which maps progress onto animation-range.
       The shorthand also resets animation-timeline, so setting these
       individually keeps the two declarations from fighting. */
    animation-name: hero-mock-in;
    animation-duration: auto;
    animation-timing-function: linear;
    animation-fill-mode: both;
    animation-timeline: view();
    animation-range: entry 15% cover 38%;
  }
}

