(function(){
  const el = document.querySelector('.hero-mock-enter');
  const cs = getComputedStyle(el);
  const r = el.getBoundingClientRect();
  const docTop = Math.round(r.top + window.scrollY);
  const vh = window.innerHeight;
  return JSON.stringify({
    range: cs.animationRange || (cs.animationRangeStart+' / '+cs.animationRangeEnd),
    duration: cs.animationDuration,
    timeline: cs.animationTimeline,
    mockTopInDocument: docTop,
    mockHeight: Math.round(r.height),
    viewportHeight: vh,
    // entry phase spans from (top hits viewport bottom) to (fully in view)
    animationStartsAtScrollY: Math.round(docTop - vh + r.height*0.10),
    animationEndsAtScrollY: Math.round(docTop - vh + r.height*1.00),
  }, null, 1);
})();

