const ID = "720aa8c1-d259-4e49-b777-c58965efabd1";
const API = "http://localhost:3001";
const norm = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "");
const post = (u, b) =>
  fetch(API + u, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(b) });
const patch = (u, b) =>
  fetch(API + u, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(b) });

const SHIPPED_COMMENT = [
  "VERIFIED WITH A REAL GENERATION ON PROD.",
  "",
  'Generated "Ridgeline Coffee Roasters" (11 files, 90 credits) and published to ridgeline-coffee-roasters-013o7.kodely.site. The agent edited index.html unprompted and wrote a real, business-specific title and description within the length targets. The serve-time backstop left all of it untouched and only added canonical + og:url.',
  "",
  "Also fixed a bug found only by testing through the real Cloudflare edge: canonical was https but og:url was http. Cloudflare SSL is Flexible, so TLS terminates at the edge and nginx forwards x-forwarded-proto: http. Cloudflare Automatic HTTPS Rewrites silently repairs href= (canonical) but not content= (og:url), so only the OG tag stayed wrong, and only in production.",
  "",
  "NOT covered by this card: structured data (JSON-LD), OG images, and analytics. See the 'SEO, analytics & meta baked in' card in Ideas / Backlog.",
].join("\n");

const IDEA_COMMENT = [
  "PARTIALLY DONE (2026-08-21) - see 'Auto-SEO on generated sites (shipped)' in Shipped - Live in Prod.",
  "",
  "Done: per-site title, meta description, OG + Twitter tags, canonical, and generated robots.txt + sitemap.xml on every published site.",
  "Still open here: structured data / JSON-LD, per-site OG images, the privacy-friendly analytics drop-in, and the 'make this rank for X' prompt affordance.",
].join("\n");

const NEEDS = [
  [
    "Service-key rotation runbook",
    [
      "The runbook itself is DONE and live on prod: docs/security/key-rotation-runbook.md - a 9-secret inventory with blast radius and cadence, routine + emergency procedures, and a verification checklist.",
      "",
      "Moved to Needs Attention because THE ROTATION HAS NOT HAPPENED. Outstanding: the two keys pasted in plaintext into a board card, plus three plaintext credential files on the operator's Desktop (anthropic api key.txt, stripe_backup_code.txt, claude_code.pem). That Desktop sits inside OneDrive, so those are in cloud storage and version history too. Rotating them needs the owner - an assistant must not handle credentials.",
    ].join("\n"),
  ],
  [
    "Exact tiers: Free / Pro",
    [
      "BLOCKED ON A DECISION, NOT ENGINEERING. lib/stripe.ts is fully wired - server-side credit packs, checkout session creation, signature-verified webhook with idempotency guards - and returns a clean 503 everywhere until real keys are set. Nothing more can be built until names/prices/credits are chosen. Cheapest unblock on the board: it is a decision, and it releases the entire money path.",
      "",
      "Watch out: a wrong STRIPE_WEBHOOK_SECRET fails CLOSED - customers pay and silently get no credits, with no error surfaced. Verify with a real test event, never a health check.",
    ].join("\n"),
  ],
  [
    "Content policy + AUP moderation",
    [
      "Verified against live code (2026-08-21): the publish path runs ONLY scanForSecrets (lib/secret-scan.ts). There is no phishing / brand-clone / abuse check anywhere. Rate limits exist but are volume gates, not content checks - lib/rate-limit.ts says exactly that in its own comments.",
      "",
      "Highest-risk open item on the board, because Kodely HOSTS what it generates: a phishing site becomes Kodely's liability (IP blocklisting, upstream depeering). Flagged Needs Attention rather than Backlog because it needs a decision on approach - a real classifier is genuine work, and this codebase has already deliberately refused to fake it with a weak heuristic.",
    ].join("\n"),
  ],
];

const BUG_COMMENT = [
  "Diagnosed 2026-08-21.",
  "",
  "NOT a key problem: the deploy key (ed25519 ...H43Nd9) is still registered on santino1233/kodely with write access and matches ~/.ssh/kodely_github on the VM exactly.",
  "",
  "It is the SSH transport. From the VM:",
  "  ssh -T git@github.com             -> Connection closed by 20.205.243.166 port 22 (3/3 attempts)",
  "  ssh -T -p 443 git@ssh.github.com  -> Connection closed by 20.200.245.248 port 443",
  "HTTPS is fine: TCP 443 open, curl https://github.com returns 200, git ls-remote over HTTPS succeeds.",
  "",
  "SECOND, WORSE BUG: /home/kodely/deploy.sh runs 'git fetch -q origin main && git reset --hard origin/main'. When the fetch fails, origin/main is a stale remote-tracking ref, so the reset succeeds against old code and the script reports a healthy deploy of the WRONG commit. A deploy script that can silently ship stale code is worse than one that crashes.",
  "",
  "WORKAROUND USED: shipped 572a07a to both envs via a git bundle over the operator's existing SSH access, then npm ci + build + restart. Both verified on 572a07a with fresh BUILD_IDs.",
  "",
  "TO FIX (owner action):",
  "1. Find why GitHub closes SSH from 51.79.162.96 - likely OVH egress filtering or a GitHub abuse/rate-limit on the IP.",
  "2. OR switch the VM remote to HTTPS with a fine-grained PAT (contents: read). HTTPS git already works from the VM.",
  "3. Either way harden deploy.sh: fetch into the tracking ref (or reset to FETCH_HEAD) and FAIL LOUDLY if the fetch fails.",
].join("\n");

(async () => {
  const d = await (await fetch(`${API}/api/board?boardId=${ID}`)).json();
  const col = (n) => d.columns.find((c) => c.name === n);
  const find = (t) => d.cards.find((c) => norm(c.title).includes(norm(t)));
  const endOf = (id) => d.cards.filter((c) => c.columnId === id).length;

  const shippedCol = col("Shipped — Live in Prod") || col("Shipped - Live in Prod");
  const r = await post("/api/board", {
    columnId: shippedCol.id,
    title: "Auto-SEO on generated sites (shipped 2026-08-21)",
  });
  const { card } = await r.json();
  await patch(`/api/cards/${card.id}`, {
    type: "FEATURE",
    description:
      "Every published site shipped with a hardcoded <title>Kodely Site</title> - in the browser tab, in search results, and in every link preview. Root cause was the builder prompt itself, which listed index.html among files that are 'already correct, leave them alone', so the agent was explicitly forbidden from editing the one file holding the title. Fixed at three levels (prompt, foundation scaffold, serve-time backstop) plus generated robots.txt and sitemap.xml. Live on prod as 572a07a.",
  });
  await post(`/api/cards/${card.id}/comments`, { authorName: "Claude", body: SHIPPED_COMMENT });
  console.log("+ Shipped:", card.title);

  const idea = find("SEO, analytics & meta baked in");
  if (idea) {
    await post(`/api/cards/${idea.id}/comments`, { authorName: "Claude", body: IDEA_COMMENT });
    console.log("~ commented:", idea.title);
  }

  const needs = col("Needs Attention");
  for (const [t, body] of NEEDS) {
    const c = find(t);
    if (!c) {
      console.log("?? not found:", t);
      continue;
    }
    await patch(`/api/cards/${c.id}`, { columnId: needs.id, position: endOf(needs.id) });
    await post(`/api/cards/${c.id}/comments`, { authorName: "Claude", body });
    c.columnId = needs.id;
    console.log("-> Needs Attention:", c.title);
  }

  const r2 = await post("/api/board", {
    columnId: needs.id,
    title: "URGENT: VM cannot reach GitHub over SSH - deploys silently ship stale code",
  });
  const { card: bug } = await r2.json();
  await patch(`/api/cards/${bug.id}`, {
    type: "BUG",
    priority: "URGENT",
    description:
      "deploy.sh on VM 110 can no longer fetch from GitHub, and does not fail when the fetch fails - it resets to a STALE origin/main and reports a healthy deploy of the wrong commit. It did exactly that twice on 2026-08-21.",
  });
  await post(`/api/cards/${bug.id}/comments`, { authorName: "Claude", body: BUG_COMMENT });
  console.log("+ Needs Attention:", bug.title);
})();

