// Kodely — Phase 1 data model.
// Principles baked in here (see the Kodely board):
//  - every generation is a Build row with real token counts, so cost per build is never a guess
//  - credits are a ledger, never a mutable counter: the balance is derivable and auditable
//  - failed builds are recorded but NEVER charged

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id               String   @id @default(cuid())
  email            String   @unique
  // Nullable because a Google-only account never sets a local password.
  passwordHash     String?
  googleId         String?  @unique
  name             String?
  role             String   @default("CUSTOMER") // CUSTOMER | ADMIN
  stripeCustomerId String?
  createdAt        DateTime @default(now())

  // Self-imposed ceiling on credits spent per rolling 30 days. NULL = no cap.
  // This is the user's own guard against a runaway session, not a plan limit —
  // bill shock is the category's deepest trust wound (one competitor billed
  // $607 against a $25 plan in three days), and a cap the user sets themselves
  // is the cheapest honest answer to it.
  spendCapCredits Int?

  sessions Session[]
  projects Project[]
  ledger   CreditLedger[]
  events   Event[]
}

// First-party analytics. Self-hosted deliberately: cheaper, keeps the data
// ours, avoids another paid API on the critical path, and is privacy-clean.
//
// One wide table rather than a table per dashboard, because the activation
// funnel, retention cohorts, per-user journey, attribution and the overview
// tiles are all different queries over the same stream. Build it once, or
// every dashboard invents its own tracking.
model Event {
  id     String  @id @default(cuid())
  // Nullable so pre-signup events (landing view, prompt submitted) still land.
  userId String?
  /// Dotted, past-tense name — see EVENTS in lib/events.ts. Never free text.
  name   String
  /// Small, non-PII payload: ids, counts, enum-ish strings. Never prompt bodies.
  props  Json?

  createdAt DateTime @default(now())

  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)

  // Funnels scan by name over a window; journeys scan one user over a window.
  @@index([name, createdAt])
  @@index([userId, createdAt])
}

// Every processed Stripe webhook event, keyed by Stripe's own event id.
// This is the idempotency guard: a webhook retry (Stripe resends on any
// non-2xx or timeout) must never grant credits twice for the same payment.
model StripeEvent {
  id        String   @id
  type      String
  createdAt DateTime @default(now())
}

model Session {
  id        String   @id @default(cuid())
  userId    String
  tokenHash String   @unique
  expiresAt DateTime
  createdAt DateTime @default(now())

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId])
}

model Project {
  id        String   @id @default(cuid())
  userId    String
  name      String
  slug      String   @unique // becomes <slug>.kodely.site when published
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  publishedAt DateTime?

  user     User          @relation(fields: [userId], references: [id], onDelete: Cascade)
  files    ProjectFile[]
  messages Message[]
  builds   Build[]

  @@index([userId])
}

// The working tree of a generated project. `published` files are the live
// snapshot served on the public subdomain; draft files are what the preview shows.
// `kind` separates the two file universes that live in this one table:
// "source" is the real Vite+React+TS project the agent edits (never served
// directly — a browser can't run raw .tsx); "build" is the compiled static
// output (lib/build-site.ts) that preview/publish/site-serving actually read.
model ProjectFile {
  id        String   @id @default(cuid())
  projectId String
  path      String
  content   String
  published Boolean  @default(false)
  kind      String   @default("source") // "source" | "build"
  updatedAt DateTime @updatedAt

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)

  @@unique([projectId, path, published, kind])
  @@index([projectId])
}

model Message {
  id        String   @id @default(cuid())
  projectId String
  role      String // user | assistant
  content   String
  createdAt DateTime @default(now())

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)

  @@index([projectId])
}

model Build {
  id        String    @id @default(cuid())
  projectId String
  status    String    @default("RUNNING") // RUNNING | SUCCEEDED | FAILED
  model     String
  prompt    String
  error     String?
  createdAt DateTime  @default(now())
  endedAt   DateTime?

  inputTokens      Int @default(0)
  outputTokens     Int @default(0)
  cacheReadTokens  Int @default(0)
  cacheWriteTokens Int @default(0)
  filesWritten     Int @default(0)

  // How many times the build had to be repaired before it compiled. 0 means it
  // compiled first try. This is the instrument for "green-build-first-try",
  // which the roadmap names as a kill-criterion gating the jump to backend
  // work — and which, until now, nothing measured. Retries are also the
  // clearest early signal of prompt or model regressions.
  repairAttempts Int @default(0)

  // Full draft file tree AFTER this build finished, as {path: content}. Small
  // sites, so a JSON snapshot per successful build is cheap and makes rollback
  // a plain restore instead of needing per-file version history.
  filesSnapshot Json?

  // Real model spend in micro-dollars, and what we actually charged.
  costMicros     Int @default(0)
  creditsCharged Int @default(0)

  project Project        @relation(fields: [projectId], references: [id], onDelete: Cascade)
  ledger  CreditLedger[]

  @@index([projectId])
}

model CreditLedger {
  id          String   @id @default(cuid())
  userId      String
  delta       Int // negative = spend, positive = grant/refund
  reason      String
  buildId     String?
  balanceAfter Int
  createdAt   DateTime @default(now())

  user  User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  build Build? @relation(fields: [buildId], references: [id], onDelete: SetNull)

  @@index([userId])
}

// SEO content pages (comparisons, guides, use-cases, glossary, feature pages,
// personas — see the "SEO · *" board columns). bodyHtml is pre-rendered,
// hand-authored semantic HTML, not user input or markdown rendered at
// runtime — there's no templating/interpolation risk serving it directly.
model BlogPost {
  id              String   @id @default(cuid())
  slug            String   @unique
  title           String
  metaDescription String
  category        String // matches the board column, e.g. "Comparisons", "Guides"
  targetKeyword   String
  bodyHtml        String
  publishedAt     DateTime @default(now())
  updatedAt       DateTime @updatedAt

  @@index([category])
}

import { spawn } from "node:child_process";
import { mkdtemp, writeFile, mkdir, rm, readdir, readFile, stat, symlink } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import type { FileMap } from "./agent";

// Where the foundation's dependencies are installed ONCE (see
// scripts/install-foundation.mjs) — every build reuses this via a symlink
// instead of running `npm install` per generation. The agent never chooses
// or adds dependencies (see lib/foundation.ts), so this is always installing
// exactly the same known-safe package.json, never anything request-controlled.
const FOUNDATION_DIR = process.env.KODELY_FOUNDATION_DIR ?? "/home/kodely/kodely-foundation";

const BUILD_TIMEOUT_MS = 60_000;

export class BuildError extends Error {}

/**
 * Compiles a project's source files into static output via `vite build`,
 * in a throwaway directory, bounded by a timeout. Never runs `npm install`
 * — the node_modules symlink points at the one shared, pre-installed
 * foundation tree, so this only ever executes vite/esbuild against files
 * we already trust the shape of, never arbitrary installed code.
 */
export async function buildSite(sourceFiles: FileMap): Promise<FileMap> {
  const workDir = await mkdtemp(join(tmpdir(), "kodely-build-"));

  try {
    for (const [path, content] of Object.entries(sourceFiles)) {
      const fullPath = join(workDir, path);
      await mkdir(dirname(fullPath), { recursive: true });
      await writeFile(fullPath, content, "utf8");
    }

    // "junction" on Windows, "dir" elsewhere. A Windows directory symlink
    // needs SeCreateSymbolicLinkPrivilege (admin, or Developer Mode) and
    // otherwise fails with EPERM, which blocked every local build on a dev
    // machine. An NTFS junction is equivalent for this purpose and needs no
    // elevation; it only works for absolute local paths, which is what this
    // is. No behaviour change on Linux.
    await symlink(
      join(FOUNDATION_DIR, "node_modules"),
      join(workDir, "node_modules"),
      process.platform === "win32" ? "junction" : "dir",
    );

    // Invoke Vite's JS entrypoint with this process's own node binary rather
    // than the `.bin/vite` shim: the shim is extensionless on POSIX but a
    // .CMD on Windows, and Node refuses to spawn .cmd without a shell. Going
    // straight to the entrypoint is a single code path on both platforms and
    // avoids shell quoting entirely.
    await runBounded(
      process.execPath,
      [join("node_modules", "vite", "bin", "vite.js"), "build"],
      workDir,
    );

    return await readDistTree(join(workDir, "dist"));
  } finally {
    await rm(workDir, { recursive: true, force: true }).catch(() => {});
  }
}

function runBounded(command: string, args: string[], cwd: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd,
      timeout: BUILD_TIMEOUT_MS,
      env: { ...process.env, NODE_ENV: "production" },
    });

    let stderr = "";
    child.stderr?.on("data", (chunk) => {
      stderr += chunk.toString();
    });

    child.on("error", (err) => reject(new BuildError(`Build could not start: ${err.message}`)));

    child.on("close", (code, signal) => {
      if (signal === "SIGTERM") {
        reject(new BuildError("Build timed out."));
      } else if (code !== 0) {
        reject(new BuildError(`Build failed:\n${stderr.slice(-2000)}`));
      } else {
        resolve();
      }
    });
  });
}

const TEXT_EXTENSIONS = new Set([".html", ".js", ".css", ".json", ".svg", ".txt", ".map"]);

async function readDistTree(dir: string): Promise<FileMap> {
  const files: FileMap = {};

  async function walk(current: string, prefix: string) {
    const entries = await readdir(current, { withFileTypes: true });
    for (const entry of entries) {
      const full = join(current, entry.name);
      const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        await walk(full, rel);
      } else {
        const ext = entry.name.slice(entry.name.lastIndexOf("."));
        if (!TEXT_EXTENSIONS.has(ext)) continue; // no binary assets — matches the inline-SVG/data-URI-only contract
        const size = (await stat(full)).size;
        if (size > 2_000_000) continue; // guard against something huge slipping through
        files[rel] = await readFile(full, "utf8");
      }
    }
  }

  await walk(dir, "");
  return files;
}

