"use client";

import { useState } from "react";

type Props = { initialCap: number | null; spent: number };

export default function SpendCapForm({ initialCap, spent }: Props) {
  const [enabled, setEnabled] = useState(initialCap !== null);
  const [value, setValue] = useState(initialCap === null ? "" : String(initialCap));
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ kind: "ok" | "error"; text: string } | null>(null);

  async function save() {
    setSaving(true);
    setMessage(null);

    const cap = enabled ? Number(value) : null;
    if (enabled && (!Number.isInteger(cap) || (cap as number) < 1)) {
      setMessage({ kind: "error", text: "Enter a whole number of credits." });
      setSaving(false);
      return;
    }

    try {
      const res = await fetch("/api/account/spend-cap", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cap }),
      });
      const data = await res.json();
      if (!res.ok) {
        setMessage({ kind: "error", text: data.error ?? "Couldn't save that." });
      } else {
        setMessage({
          kind: "ok",
          text: data.cap === null ? "Cap removed." : `Cap set to ${data.cap} credits.`,
        });
      }
    } catch {
      setMessage({ kind: "error", text: "Couldn't reach the server. Try again." });
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="rounded-xl border border-black/10 p-5 dark:border-white/10">
      <h2 className="text-sm font-medium">Spending cap</h2>
      <p className="mt-1 text-sm text-black/60 dark:text-white/60">
        Stop builds once you&apos;ve spent this many credits in any 30-day period. Your cap,
        your call — we&apos;ll never raise it for you. You&apos;ve used{" "}
        <span className="font-medium tabular-nums">{spent}</span> in the last 30 days.
      </p>

      <label className="mt-4 flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          checked={enabled}
          onChange={(e) => {
            setEnabled(e.target.checked);
            setMessage(null);
          }}
          className="h-4 w-4 rounded border-black/20 dark:border-white/20"
        />
        Limit my spending
      </label>

      {enabled && (
        <div className="mt-3 flex items-center gap-2">
          <input
            type="number"
            min={1}
            step={1}
            value={value}
            onChange={(e) => {
              setValue(e.target.value);
              setMessage(null);
            }}
            placeholder="1000"
            className="w-32 rounded-lg border border-black/15 bg-transparent px-3 py-1.5 text-sm tabular-nums outline-none focus:border-black/40 dark:border-white/15 dark:focus:border-white/40"
          />
          <span className="text-sm text-black/60 dark:text-white/60">credits per 30 days</span>
        </div>
      )}

      <div className="mt-4 flex items-center gap-3">
        <button
          onClick={save}
          disabled={saving}
          className="rounded-lg bg-black px-3 py-1.5 text-sm font-medium text-white disabled:opacity-50 dark:bg-white dark:text-black"
        >
          {saving ? "Saving…" : "Save"}
        </button>
        {message && (
          <span
            className={
              message.kind === "ok"
                ? "text-sm text-emerald-600 dark:text-emerald-400"
                : "text-sm text-red-600 dark:text-red-400"
            }
          >
            {message.text}
          </span>
        )}
      </div>
    </div>
  );
}

