// Promote an existing account to ADMIN, or demote one back to CUSTOMER.
//
//   node scripts/make-admin.mjs you@example.com
//   node scripts/make-admin.mjs you@example.com --revoke
//
// Deliberately a script and not a UI: role changes should leave a shell-history
// trail on the box, and there is no self-service path to grant yourself access
// to cost, margin, and customer prompts. Run it on whichever machine owns the
// database you mean — DATABASE_URL differs per environment.

import { PrismaClient } from "@prisma/client";

const email = process.argv[2]?.trim().toLowerCase();
const revoke = process.argv.includes("--revoke");

if (!email) {
  console.error("Usage: node scripts/make-admin.mjs <email> [--revoke]");
  process.exit(1);
}

const db = new PrismaClient();

try {
  const user = await db.user.findUnique({
    where: { email },
    select: { id: true, email: true, role: true },
  });

  if (!user) {
    console.error(`No account with email ${email}.`);
    process.exit(1);
  }

  const role = revoke ? "CUSTOMER" : "ADMIN";

  if (user.role === role) {
    console.log(`${user.email} is already ${role}. Nothing to do.`);
  } else {
    await db.user.update({ where: { id: user.id }, data: { role } });
    console.log(`${user.email}: ${user.role} -> ${role}`);
  }

  const admins = await db.user.findMany({
    where: { role: "ADMIN" },
    select: { email: true },
    orderBy: { email: "asc" },
  });
  console.log(`\nAdmins now (${admins.length}): ${admins.map((a) => a.email).join(", ") || "none"}`);
} finally {
  await db.$disconnect();
}

