" -H "Host: kodely.me" http://localhost:3009/admin; echo "--- /admin on ADMIN host ---"; curl -s -o /dev/null -w "HTTP %{http_code}
" -H "Host: ops-test.kodely.me" http://localhost:3009/admin; echo "--- / on ADMIN host (should rewrite to /admin) ---"; curl -s -o /dev/null -w "HTTP %{http_code}
