" -H "Host: kodely.me" http://localhost:3009/definitely-not-a-route

Start-Sleep -Seconds 8
$tests = @(
  @{n='/admin on WRONG host';h='kodely.me';p='/admin'},
  @{n='/admin on ADMIN host';h='ops-test.kodely.me';p='/admin'},
  @{n='/ on ADMIN host';h='ops-test.kodely.me';p='/'},
