//     agent tool calls (lib/build-narration.ts) — never a timed script.
//  2. Make the wait feel like craft rather than a hang. The skeleton resolves
//     in the shape of an actual page, so the shape of what is coming is
//     legible before any of it exists.
//
// No progress BAR anywhere: we genuinely cannot know what fraction is done,
// and a bar that stalls at 80% is the exact thing that makes people reload.

function Bar({ className = "", delay = 0 }: { className?: string; delay?: number }) {
  return (
    <div
      className={`kodely-skeleton rounded-md ${className}`}
      style={{ animationDelay: `${delay}s` }}
    />
  );
}

export default function BuildingOverlay({ status }: { status: string | null }) {
  return (
    <div className="flex h-full w-full flex-col items-center justify-center gap-8 bg-white p-8 dark:bg-neutral-950">
      <div className="flex flex-col items-center gap-3">
        <div className="kodely-breathe motion-reduce:animate-none">
          <Mark size={44} />
        </div>
        <p
          className="min-h-5 text-center text-sm text-black/60 dark:text-white/60"
          aria-live="polite"
        >
          {status ?? "Getting started"}
        </p>
      </div>

      {/* A page taking shape. Deliberately generic — nav, hero, three cards —
          because guessing the actual layout would mean showing something the
          finished site then contradicts. */}
      <div
        className="flex w-full max-w-md flex-col gap-4 opacity-70"
        aria-hidden="true"
      >
        <div className="flex items-center justify-between gap-3">
          <Bar className="h-3 w-20" delay={0} />
          <div className="flex gap-2">
            <Bar className="h-2.5 w-10" delay={0.1} />
            <Bar className="h-2.5 w-10" delay={0.15} />
            <Bar className="h-2.5 w-10" delay={0.2} />
          </div>
        </div>

        <Bar className="h-24 w-full" delay={0.3} />

        <div className="flex flex-col gap-2">
          <Bar className="h-3 w-3/4" delay={0.45} />
          <Bar className="h-3 w-1/2" delay={0.5} />
        </div>

        <Bar className="h-7 w-28" delay={0.6} />

        <div className="mt-2 grid grid-cols-3 gap-3">
          <Bar className="h-16" delay={0.7} />
          <Bar className="h-16" delay={0.78} />
          <Bar className="h-16" delay={0.86} />
        </div>
      </div>
    </div>
  );
}

