import { classifyFollowUp, type Intent } from "./lib/feedback-intent.ts";

const cases: [string, Intent][] = [
  ["the page is blank", "broken"],
  ["nothing shows up", "broken"],
  ["it's broken, can you make the colors nicer", "broken"],
  ["wow this is amazing", "praise"],
  ["thanks!", "praise"],
  ["Perfect", "praise"],
  ["remove the testimonials section", "remove"],
  ["get rid of the footer", "remove"],
  ["add a contact form", "add"],
  ["can you add a pricing section", "add"],
  ["make the colors warmer", "visual"],
  ["this looks really generic", "visual"],
  ["use a bolder font", "visual"],
  ["move the nav to the right", "layout"],
  ["make the hero bigger", "layout"],
  ["change the headline to 'Welcome to Bloom'", "content"],
  ["fix the typo in the about text", "content"],
  ["update the phone number", "content"],
  ["hmm", "other"],
  ["", "other"],
  ["make it pop", "other"],
];

let fails = 0;
for (const [input, expected] of cases) {
  const got = classifyFollowUp(input);
  const ok = got === expected;
  if (!ok) fails++;
  console.log(`${ok ? "ok  " : "FAIL"}  ${JSON.stringify(input).padEnd(48)} expected=${expected.padEnd(9)} got=${got}`);
}
console.log(`\n${cases.length - fails}/${cases.length} passed`);

