// Ordered: the FIRST match wins, so the list runs most-specific first.
// "broken" outranks everything — a blank page is not a styling note even when
// the user politely phrases it as one.
const RULES: { intent: Intent; pattern: RegExp }[] = [
  {
    intent: "broken",
    pattern:
      /\b(broken|not working|doesn'?t work|blank|white screen|empty page|error|crash(ed|ing)?|bug|nothing (shows|happens|loads)|won'?t load|failed)\b/i,
  },
  {
    intent: "praise",
    pattern:
      /^(?:\s*(?:wow|nice|great|perfect|awesome|amazing|love it|looks good|thanks?|thank you|beautiful|excellent)\b[\s!.,]*)+$/i,
  },
  {
    intent: "remove",
    pattern: /\b(remove|delete|get rid of|take out|drop the|don'?t (want|need))\b/i,
  },
  {
    intent: "add",
    pattern:
      /\b(add|include|insert|another|a new|also (want|need)|can (you|we) (add|put)|put in|create a)\b/i,
  },
  {
    intent: "visual",
    pattern:
      /\b(colou?r|font|typeface|bolder|darker|lighter|background|gradient|style|styling|theme|ugly|bland|generic|boring|prettier|nicer|modern|rounded|shadow|spacing|padding|margin)\b/i,
  },
