  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const [balance, avgBuildCredits, projects] = await Promise.all([
    getBalance(user.id),
    averageBuildCredits(user.id),
    db.project.findMany({
      where: { userId: user.id },
      orderBy: { updatedAt: "desc" },
      select: { id: true, name: true, slug: true, publishedAt: true, updatedAt: true },
    }),
  ]);

  return (
    <div className="mx-auto max-w-4xl px-6 py-10">
      <div className="mb-8 flex items-center justify-between">
        <div>
          <div className="text-lg font-semibold tracking-tight">kodely</div>
          <p className="text-sm text-black/60 dark:text-white/60">{user.email}</p>
        </div>
        <div className="flex items-center gap-4">
          <CreditMeter
            balance={balance}
            avgBuildCredits={avgBuildCredits}
            reference={SIGNUP_GRANT}
            canTopUp={billingEnabled()}
          />
          {billingEnabled() && <TopUpButton />}
          {/* Deliberately NOT gated on billingEnabled(): this page is mostly
              the credit statement, which matters just as much — arguably more —
              when top-ups are unavailable and someone is trying to work out
              where their credits went. */}
          <Link
            href="/dashboard/billing"
            className="text-sm text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
          >
            Billing
          </Link>
          <Link
            href="/settings"
            className="text-sm text-black/60 hover:text-black dark:text-white/60 dark:hover:text-white"
          >
            Settings
          </Link>
          <SignOutButton />
        </div>
      </div>

      {/* Renders nothing once they've published — reaching the North Star is
          the exit condition, so there is no flag to store or reset. */}
      <FirstRunChecklist />

      <div className="mb-6 flex items-center justify-between">
        <h1 className="text-base font-medium">Your sites</h1>
        <NewProjectButton />
      </div>

      {projects.length === 0 ? (
        <div className="rounded-xl border border-dashed border-black/15 p-10 text-center text-sm text-black/60 dark:border-white/15 dark:text-white/60">
          Nothing here yet. Create a site and describe what you want built.
        </div>
      ) : (
        <ul className="divide-y divide-black/10 rounded-xl border border-black/10 dark:divide-white/10 dark:border-white/10">
          {projects.map((p) => (
            <li key={p.id}>
              <ProjectRow
                project={{
                  id: p.id,
                  name: p.name,
                  slug: p.slug,
                  published: p.publishedAt !== null,
                }}
              />
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

