import { registerTsResolution, quietNodeWarnings, loadEnv } from "./scripts/eval/loader.mjs";
quietNodeWarnings(); loadEnv({ quiet: true }); registerTsResolution();
const { applyHead } = await import("./app/api/projects/[id]/seo/head.ts");

