import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";

const db = new DatabaseSync("board.sqlite");
const B = "720aa8c1-d259-4e49-b777-c58965efabd1";
const done = db.prepare("SELECT id FROM columns WHERE boardId = ? AND name = ?").get(B, "Done — awaiting deploy").id;

// Matched on a distinctive substring, because several titles carry characters
// that are painful to reproduce exactly. Each entry is a card whose work I can
// point at in the tree — not one that merely sounds related.
const COMPLETE = [
  ["Projects / sites registry + moderation + takedown", "/admin/sites — registry, per-site findings, review verdicts, and takedown that clears publishedAt without deleting the customer's work. Takedown proved end to end: 200 before, 404 on all five paths after, project and all four file rows intact."],
  ["Support inbox + user notes + feedback board", "/admin/feedback — individual build ratings, a reason breakdown, and per-user operator notes. The question it leads with is whether thumbs-down builds are the ones that needed a repair pass, which separates a quality problem from a reliability one."],
  ["Blog / SEO CMS (manage the 200+ SEO pages)", "/admin/content — list, search across body text, stale-claim flagging, validated editing and preview. Reuses scripts/seo/validate.mjs directly rather than a second rule set, refuses to save invalid HTML (bodyHtml is injected unsanitised into a public page), and calls revalidatePath so a correction is not invisible for an hour."],
  ["GDPR / data compliance (export, delete, retention, consent)", "Account-level export (streamed JSON, every table, with an explicit notIncluded block), a two-step deletion with a 7-day grace, a data-rights page, and a retention policy with a dry-run-by-default runner. Cookie consent was investigated and deliberately NOT built — all three cookies are strictly necessary, so a banner would ask permission for nothing."],
  ["Retention & cohort analysis", "/admin/analytics — signup cohorts by week against first build, first publish and first purchase, sourced from User/Project/Build/CreditLedger rather than Event, because those tables have recorded since day one and the event stream has not."],
  ["Revenue analytics (MRR / ARR / churn / LTV / CAC)", "Built as the honest subset, and the refusals are IN THE PRODUCT as a 'Not computed, and why' table. MRR/ARR are undefined (no subscriptions exist — CREDIT_PACKS are one-time), churn is undefined (nothing to cancel), CAC is uncomputable (no spend or attribution is recorded anywhere). What was built instead: realised revenue, cost and meter recovery, cohorts, and credit liability — which is the number nothing showed before."],
  ["Per-user journey / session timeline", "The event journey on /admin/users/[id], served off the [userId, createdAt] index, alongside that user's ledger statement, projects and build history."],
  ["First-party event pipeline + taxonomy (self-hosted, $0)", "lib/events.ts + the Event table. Closed dotted vocabulary, small non-PII props, fire-and-forget so analytics can never fail a build. Every name in the vocabulary is verified to actually fire — two acquisition names were REMOVED because nothing emitted them and the privacy policy is written from this list."],
  ["Activation metric + North Star + funnel instrumentation", "North Star is first PUBLISH, not signup or first generation — the moment the product delivers what it promises. The funnel counts DISTINCT USERS rather than events, so one enthusiastic user cannot look like retention."],
  ["Public status page + incident response runbook", "/status plus docs/ops/incident-response.md. The status page is notable for what it refuses: it never reads Build.error at all (it can contain customer source), publishes volume as a band rather than a count, and treats 'unknown' as outranking 'operational' so it cannot round no-signal up to fine."],
  ["Cookie consent + GDPR/CCPA data rights", "Data rights built. Cookie consent deliberately NOT built, with evidence: all three cookies (session and two OAuth anti-forgery state cookies) are strictly necessary, there is no third-party script anywhere, and published sites run under a CSP blocking every external host. A banner would change nothing whichever button was pressed. The full inventory is published on /legal/rights instead."],
  ["Responsive preview (device frames)", "Desktop/tablet/mobile widths in the editor preview, verified at 896/768/380px with mutually exclusive aria-pressed and the iframe node surviving width changes rather than reloading."],
  ["Plan-before-spend mode", "estimateCredits() finally has a caller. Shown as a deliberately wide bracket (120-550 create) with no midpoint computed, switching to the user's own measured average once they have build history — gated on a real build count so the global fallback constant is never labelled 'yours'."],
  ["Command palette / keyboard shortcuts", "Cmd/Ctrl-K, focus trapped while open, Escape restores focus to the exact element it came from. Needed a window-level Escape net because the editor unbinds its global shortcuts while the palette is open — without it the palette went keyboard-dead."],
  ["Connection-loss / sandbox-death recovery UX", "The three outcomes are now distinguishable: a deliberate stop, a dropped stream, and a server error each say something different. Deliberately promises NO resume, because RUNNING is written in one place and read nowhere — there is no reattach to offer."],
  ["User-facing SEO / meta panel", "A fourth editor view for title, meta description and OG tags, editable without paying for a generation. There is no SEO column anywhere — the head of the project's own index.html is the storage — so the save route rewrites both draft trees and deliberately never touches published rows."],
];

const PARTIAL = [
  ["User & team management + impersonation", "User management is built (/admin/users, list + detail + ledger + journey). Impersonation is deliberately NOT built: it was excluded from the brief as read-only, and a 'view as' feature needs an audit story of its own before it exists."],
  ["Sandbox isolation hardening + pre-GA security review", "The review happened (docs/security/audit-2026-08.md) and four findings are fixed — two critical, two high. NOT done: the audit could not assess production KODELY_ENGINE, nginx/Cloudflare config, VM permissions or DB roles, and no finding was confirmed against production. Pre-GA still needs that."],
  ["SLOs + error budgets + on-call rotation", "docs/ops/slos.md exists and is honest: one objective is committable, every availability nine was DECLINED, and any p95 was refused outright as arithmetic over five samples. There is still no uptime monitoring, no alerting and no on-call — so these remain proposals, not commitments."],
  ["Streaming generation UX (stop / regenerate / branch)", "STOP is built and its copy verified true on the live SDK engine (an aborted build persists nothing, so it no longer claims files are kept). Regenerate and branch are not built."],
  ["Builder UI accessibility (WCAG / screen reader)", "The PUBLIC pages passed a full accessibility pass — 12 lint errors fixed at source, labels, landmarks, focus states, reduced-motion, contrast. The BUILDER UI itself has not had that pass, and has a known unresolved 380px overflow (the sidebar is w-96)."],
];

const find = db.prepare(
  `SELECT c.id, c.title, c.columnId FROM cards c JOIN columns co ON co.id = c.columnId
   WHERE co.boardId = ? AND c.archivedAt IS NULL AND c.title LIKE ?`,
);
const addComment = db.prepare("INSERT INTO comments (id, cardId, authorName, body) VALUES (?, ?, 'Claude', ?)");
const maxPos = db.prepare("SELECT COALESCE(MAX(position), -1) AS p FROM cards WHERE columnId = ?");
const move = db.prepare("UPDATE cards SET columnId = ?, position = ? WHERE id = ?");

const AW = "\n\nSTATUS: complete and verified locally. NOT deployed — prisma db push must reach staging and prod before the code ships.";

let moved = 0;
for (const [needle, note] of COMPLETE) {
  const card = find.get(B, `%${needle}%`);
  if (!card) { console.log(`!! not found: ${needle}`); continue; }
  if (card.columnId === done) { console.log(`already | ${card.title.slice(0, 58)}`); continue; }
  addComment.run(randomUUID(), card.id, note + AW);
  move.run(done, maxPos.get(done).p + 1, card.id);
  moved++;
  console.log(`done    | ${card.title.slice(0, 58)}`);
}
for (const [needle, note] of PARTIAL) {
  const card = find.get(B, `%${needle}%`);
  if (!card) { console.log(`!! not found: ${needle}`); continue; }
  addComment.run(randomUUID(), card.id, `PARTIALLY DONE — ${note}`);
  console.log(`partial | ${card.title.slice(0, 58)}`);
}
console.log(`\n${moved} more moved to Done.`);

