import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";

const db = new DatabaseSync("board.sqlite");
const B = "720aa8c1-d259-4e49-b777-c58965efabd1";
const col = (n) => db.prepare("SELECT id FROM columns WHERE boardId = ? AND name = ?").get(B, n).id;
const DONE = col("Done — awaiting deploy");
const SHIPPED = col("Shipped — Live in Prod");

const find = db.prepare(
  `SELECT c.id, c.title, c.columnId FROM cards c JOIN columns co ON co.id = c.columnId
   WHERE co.boardId = ? AND c.archivedAt IS NULL AND c.title LIKE ?`,
);
const addComment = db.prepare("INSERT INTO comments (id, cardId, authorName, body) VALUES (?, ?, 'Claude', ?)");
const maxPos = db.prepare("SELECT COALESCE(MAX(position), -1) AS p FROM cards WHERE columnId = ?");
const move = db.prepare("UPDATE cards SET columnId = ?, position = ? WHERE id = ?");
const retitle = db.prepare("UPDATE cards SET title = ? WHERE id = ?");

const MOVES = [
  {
    match: "%transparent credit meter%",
    to: DONE,
    // The tick in the title is now finally true, but it was false for days.
    title: "MVP: transparent credit meter + pre-generation cost estimate",
    note: `NOW GENUINELY COMPLETE — and the title no longer carries a tick it had not earned.

This card claimed SHIPPED while estimateCredits() had ZERO callers. Nothing showed anyone a cost before they spent, which is how an SEO article ended up claiming "you see an estimated cost range before you spend" and having to retract it.

Both halves exist now:
- The meter: a real bar on the dashboard, an inline warning in the editor, and "about N more builds" from that user's own measured average. Its amber threshold was also fixed — it was firing on brand-new accounts at a full 750-credit balance, which is noise that trains people to ignore the real warning.
- The estimate: shown before Build as a deliberately wide bracket (120-550 create), with NO midpoint computed, switching to the user's own average once they have history and gated on a real build count so the global fallback constant is never labelled "yours".

It also refuses to claim a mid-build cutoff, because there isn't one: the only pre-flight gate is balance <= 0, and chargeForBuild writes the real amount even when that takes the balance negative.`,
  },
  {
    match: "Free credit gifts for following our socials",
    to: DONE,
    note: `Built. app/api/rewards/** — 50 credits per platform, granted once per account ever.

Discord is genuinely verified: OAuth plus a server-to-server member check on the specific guild, chosen over scanning the user's guild list because that list caps at ~200 and would false-negative a real user in many servers. Instagram and LinkedIn are self-declared with a 72h hold, and the code says so in plain terms rather than implying verification it does not do.

Cross-account abuse is handled by an HMAC of the external identity in the ledger reason string — keyed, not a plain digest, because Discord snowflakes and handles are low-entropy and an unkeyed hash would let anyone with DB read access test whether a given handle is a customer.

FACEBOOK IS DELIBERATELY INERT. Meta's developer incentivization policy names rewarding Page Likes as a prohibited example. The code exists but does nothing unless KODELY_FACEBOOK_URL is set, and the file tells the reader not to set it until a human has read Meta's current policy.

Requires KODELY_REWARDS_ID_SALT to be set, or nothing is ever granted.`,
  },
  {
    match: "%SEO, analytics & meta baked in%",
    to: DONE,
    note: `Done across three pieces:
- Auto-SEO on generated sites already shipped (lib/site-seo.ts — title, meta, OG, canonical, robots.txt, sitemap.xml, with a backstop that only fills gaps).
- A user-facing SEO/meta panel now lets the owner edit title, description and OG tags WITHOUT paying for a generation.
- First-party analytics (lib/events.ts) is self-hosted with a closed event vocabulary.

One real bug fixed along the way: applySeo read the title while it was still entity-encoded and then escaped it again, so a site called "Bloom & Co" reached link previews as "Bloom &amp; Co".`,
  },
  {
    match: "Secret-leak scanning in generated code",
    to: SHIPPED,
    note: `Moving to Shipped — this one genuinely IS live in production, unlike the rest of this session's work.

Independently confirmed by the security audit: publish is BLOCKED, not merely warned, and the TrustBento marketing copy listing the patterns matches lib/secret-scan.ts exactly.

Its sibling — abuse moderation on publish (lib/moderation.ts) — is built but NOT deployed, and sits in Done awaiting deploy.`,
  },
];

for (const m of MOVES) {
  const card = find.get(B, m.match);
  if (!card) {
    console.log(`!! not found: ${m.match}`);
    continue;
  }
  addComment.run(randomUUID(), card.id, m.note);
  if (m.title && m.title !== card.title) retitle.run(m.title, card.id);
  if (card.columnId !== m.to) {
    move.run(m.to, maxPos.get(m.to).p + 1, card.id);
    console.log(`moved   | ${card.title.slice(0, 56)}`);
  } else {
    console.log(`already | ${card.title.slice(0, 56)}`);
  }
}

console.log("\n=== stages ===");
for (const c of db
  .prepare(
    "SELECT name, (SELECT COUNT(*) FROM cards k WHERE k.columnId = c.id AND k.archivedAt IS NULL) n FROM columns c WHERE c.boardId = ? ORDER BY c.position",
  )
  .all(B)
  .slice(0, 8))
  console.log(`  ${c.name.padEnd(26)}${c.n}`);

