@import "tailwindcss";

/* Class-based dark mode (".dark" on <html>) so the manual theme toggle can
   override the OS preference — Tailwind's dark: classes elsewhere in the
   app are unaffected in shape, only in what triggers them. */
@custom-variant dark (&:where(.dark, .dark *));

:root {
  --background: #ffffff;
  --foreground: #171717;

  /* Kodely brand tokens — ported 1:1 from the approved reference mockup
     (scratchpad/kodely.html) so the shipped site and the approved design
     don't drift again. */
  --ink-2: #605b66;
  --faint: #a49fad;
  --line: rgba(11, 10, 13, 0.09);
  --line-2: rgba(11, 10, 13, 0.045);
  --panel: #ffffff;
  --accent: #e01b6e;
  --glow: rgba(247, 37, 112, 0.13);
  --glow-2: rgba(163, 61, 255, 0.12);
  --sh-s: 0 1px 2px rgba(11, 10, 13, 0.04), 0 6px 16px -8px rgba(11, 10, 13, 0.1);
  --sh: 0 40px 100px -50px rgba(120, 40, 160, 0.3), 0 18px 50px -30px rgba(11, 10, 13, 0.16);

  --brand-gradient: linear-gradient(100deg, #f72570 0%, #ff6b67 44%, #ff9868 66%, #a33dff 100%);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root:not(.light) {
    --background: #0a0a0a;
    --foreground: #ededed;
    --ink-2: #a8a1b0;
    --faint: #5f5869;
    --line: rgba(246, 243, 247, 0.1);
    --line-2: rgba(246, 243, 247, 0.05);
    --panel: #100e15;
    --accent: #ff5c97;
    --glow: rgba(255, 76, 139, 0.22);
    --glow-2: rgba(180, 114, 255, 0.2);
    --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
    --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
    --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
  }
}

:root.dark {
  --background: #0a0a0a;
  --foreground: #ededed;
  --ink-2: #a8a1b0;
  --faint: #5f5869;
  --line: rgba(246, 243, 247, 0.1);
  --line-2: rgba(246, 243, 247, 0.05);
  --panel: #100e15;
  --accent: #ff5c97;
  --glow: rgba(255, 76, 139, 0.22);
  --glow-2: rgba(180, 114, 255, 0.2);
  --sh-s: 0 1px 2px rgba(0, 0, 0, 0.5), 0 8px 20px -10px rgba(0, 0, 0, 0.6);
  --sh: 0 50px 120px -50px rgba(0, 0, 0, 0.8), 0 20px 60px -30px rgba(180, 114, 255, 0.4);
  --brand-gradient: linear-gradient(100deg, #ff4c8b 0%, #ff8778 44%, #ffae7e 66%, #b472ff 100%);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
}

.brand-gradient-text {
  background: var(--brand-gradient);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Ambient background — one very slow, very soft light behind every
   marketing page. Fixed, never scrolls, never shifts color — the motion
   budget is spent on foreground elements, not this. */
.aura {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.aura b {
  position: absolute;
  border-radius: 50%;
  filter: blur(120px);
  opacity: 0.6;
}
.aura .a1 {
  width: 52vw;
  height: 52vw;
  left: -8vw;
  top: -14vw;
  background: radial-gradient(closest-side, var(--glow), transparent);
}
.aura .a2 {
  width: 46vw;
  height: 46vw;
  right: -10vw;
  bottom: -4vw;
  background: radial-gradient(closest-side, var(--glow-2), transparent);
}

/* The prompt-box glow ring (PromptHero) — a Gemini-style "chasing light"
   ring, rebuilt using only decade-old, maximally-compatible CSS: plain
   `transform: rotate()` and `overflow: hidden` clipping. No @property, no
   CSS masking — both were dropped after repeated reports that the effect
   still wasn't appearing correctly even in a fresh browser with a verified
   non-cached, up-to-date stylesheet, which means the earlier @property +
   mask-composite combination (both comparatively modern CSS features) was
   the most likely remaining suspect, even though I could not get direct
   visual confirmation either way in this environment.

   The technique: each layer is a STATIC outer clipper
   (`.glow-clip-a/-b`, position:absolute, overflow:hidden, never
   transforms) containing one OVERSIZED inner rotator
   (`.glow-spin-a/-b`, ~2x the clipper's size, centered via inset:-50%).
   Only the inner rotator spins via plain `transform: rotate()` — since
   it's oversized, its corners sweeping outside a same-sized box (the
   original "wide rectangle rotated as a rigid body" bug) never matters:
   they're clipped away by the static outer box at every angle. The
   composer sitting on top (z-10, opaque) covers the rotator's entire
   interior, leaving only the outer few px visible as a ring — no masking
   needed for that either. */
@keyframes glow-spin {
  to {
    transform: rotate(360deg);
  }
}
.glow-spin-a {
  animation: glow-spin 9s linear infinite;
}
.glow-spin-b {
  animation: glow-spin 14s linear infinite reverse;
}

/* Entrance fade-in — plain CSS on the static outer clipper, not a
   framer-motion `whileInView` (depends on IntersectionObserver + React
   state + framer's scheduling — more moving parts than necessary here).
   `forwards` is load-bearing: without it, the element snaps back to its
   non-animated base style the instant the single iteration ends. */
@keyframes glow-fade-in-a {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
  to {
    opacity: 0.35;
    transform: scale(1);
  }
}
@keyframes glow-fade-in-b {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
  to {
    opacity: 0.2;
    transform: scale(1);
  }
}

/* Ambient pulse — a slow breathe, kept subtle so it reads as the glow
   "living" rather than blinking. Runs as a THIRD animation chained after
   the entrance: the fade-in owns opacity for its first 0.8s, then this
   takes over from the same value it settled on (0.35 / 0.2), so there is
   no jump at the handoff — keep the two in sync when retuning intensity.
   Its delay must match the fade-in's duration.
   The floor never approaches 0 — the glow dims and brightens, it never
   disappears. */
@keyframes glow-pulse-a {
  0%,
  100% {
    opacity: 0.35;
  }
  50% {
    opacity: 0.5;
  }
}
@keyframes glow-pulse-b {
  0%,
  100% {
    opacity: 0.2;
  }
  50% {
    opacity: 0.33;
  }
}
.glow-clip-a {
  animation:
    glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
    glow-pulse-a 4.5s ease-in-out 0.8s infinite;
}
.glow-clip-b {
  animation:
    glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,
    glow-pulse-b 6s ease-in-out 1s infinite;
}

/* Scroll entrance for the hero mock (HeroMock.tsx). A CSS transition
   toggled by an `is-entered` class from an IntersectionObserver — no
   dependence on framer-motion's in-view scheduling, which applied its
   initial styles here but never actually triggered. */
@keyframes hero-mock-in {
  from {
    opacity: 0;
    transform: translateY(56px) scale(0.94);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Fallback for browsers without scroll-driven animation support: play the
   entrance once on load. Not as nice as scroll-linked, but never leaves
   the mock stuck invisible. */
.hero-mock-enter {
  animation: hero-mock-in 0.9s cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* The real thing: a native scroll-driven animation, progressed by the
   element's own position in the viewport. No IntersectionObserver, no
   scroll listener, no React state — every JS-based trigger tried here
   (framer's whileInView, a raw IntersectionObserver, a scroll listener)
   failed to fire in practice, and this removes that entire class of
   failure. `view()` ties progress to the element crossing the viewport;
   the range runs from just after it appears to a third of the way up, so
   it finishes as you arrive at it rather than while it's still an
   off-screen sliver. */
@supports (animation-timeline: view()) {
  .hero-mock-enter {
    /* Longhands, not the `animation` shorthand: the shorthand defaults
       animation-duration to 0s when it's omitted, which — combined with
       fill:both — snapped straight to the end state at every scroll
       position (i.e. no visible animation at all). Scroll-driven
       animations need `auto`, which maps progress onto animation-range.
       The shorthand also resets animation-timeline, so setting these
       individually keeps the two declarations from fighting. */
    animation-name: hero-mock-in;
    animation-duration: auto;
    animation-timing-function: linear;
    animation-fill-mode: both;
    animation-timeline: view();
    /* Spans the element's whole entry into the viewport: starts just after
       its top edge appears and finishes exactly when it's fully on screen.
       Both endpoints in the same phase keeps it predictable (an earlier
       `entry 15% cover 38%` mixed phases, which is legal but harder to
       reason about and compressed the motion into a shorter scroll). */
    animation-range: entry 10% entry 100%;
  }
}

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* ── Build-in-progress treatment (app/projects/[id]/BuildingOverlay.tsx) ──
   The Kodely mark breathes while a build runs. Scale only, and only 3% —
   enough to read as alive, small enough not to look like a loading spinner
   fighting for attention. */
@keyframes kodely-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.03);
  }
}
.kodely-breathe {
  animation: kodely-breathe 2.4s ease-in-out infinite;
}

/* Skeleton blocks: fade up into place once (staggered by inline delay), then
   a highlight sweeps across them continuously. `background-position` rather
   than a moving pseudo-element so there is nothing to clip or overflow. */
@keyframes kodely-skeleton-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes kodely-skeleton-sweep {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}
.kodely-skeleton {
  opacity: 0;
  background-color: color-mix(in oklab, currentColor 8%, transparent);
  background-image: linear-gradient(
    90deg,
    transparent 20%,
    color-mix(in oklab, currentColor 10%, transparent) 50%,
    transparent 80%
  );
  background-size: 200% 100%;
  animation:
    kodely-skeleton-in 0.45s ease-out forwards,
    kodely-skeleton-sweep 1.8s linear infinite;
}

/* Motion here is decoration, not information — the status line carries the
   meaning — so it is safe to drop entirely. The blocks must still be VISIBLE,
   hence opacity:1 rather than just cancelling the animation. */
@media (prefers-reduced-motion: reduce) {
  .kodely-breathe,
  .kodely-skeleton {
    animation: none;
  }
  .kodely-skeleton {
    opacity: 1;
  }
}

/* Staggered dots beside the live build-progress line in the editor chat.
   Opacity only — no transform — so the three dots never shift the text
   baseline beside them while a build runs. */
@keyframes kodely-pulse {
  0%,
  100% {
    opacity: 0.25;
  }
  50% {
    opacity: 1;
  }
}

/* CTA button hover treatment — ported from Nxeon's real .btn-deploy
   pattern (see that codebase's app/globals.css) using Kodely's own brand
   gradient instead of Nxeon's blue/purple one. Two pieces:
   1. .btn-shine — a one-shot shimmer sweep on hover (all CTAs).
   2. .btn-cta-gradient — the background gradient itself shifts position on
      hover (only on buttons whose background already IS the brand
      gradient — a plain dark/monochrome button has no gradient to shift). */
@keyframes btn-shine {
  from {
    left: -40%;
  }
  to {
    left: 120%;
  }
}
.group:hover .btn-shine {
  animation: btn-shine 0.75s ease;
}

.btn-cta-gradient {
  background-image: var(--brand-gradient);
  background-size: 220% 100%;
  background-position: 0% 0;
  transition: background-position 0.6s ease;
}
.group:hover .btn-cta-gradient {
  background-position: 100% 0;
}

/* Prose styling for blog/SEO content (BlogPost.bodyHtml) — hand-rolled
   instead of a Tailwind typography plugin dependency, matching the same
   near-monochrome + generous-whitespace system as the rest of the site. */
.article-body h2 {
  margin-top: 2.75rem;
  margin-bottom: 1rem;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.article-body h3 {
  margin-top: 2rem;
  margin-bottom: 0.75rem;
  font-size: 1.15rem;
  font-weight: 600;
}
.article-body p {
  margin-bottom: 1.25rem;
  line-height: 1.75;
  color: var(--foreground);
}
.article-body ul,
.article-body ol {
  margin: 1.25rem 0 1.25rem 1.25rem;
  line-height: 1.75;
}
.article-body ul {
  list-style: disc;
}
.article-body ol {
  list-style: decimal;
}
.article-body li {
  margin-bottom: 0.4rem;
}
.article-body a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--foreground) 30%, transparent);
}
.article-body strong {
  font-weight: 600;
}
.article-body code {
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.875em;
  background: color-mix(in srgb, var(--foreground) 6%, transparent);
  padding: 0.15em 0.4em;
  border-radius: 0.3em;
}
.article-body table {
  width: 100%;
  margin: 1.5rem 0;
  border-collapse: collapse;
  font-size: 0.9rem;
}
.article-body th,
.article-body td {
  border: 1px solid color-mix(in srgb, var(--foreground) 12%, transparent);
  padding: 0.6rem 0.9rem;
  text-align: left;
}
.article-body th {
  font-weight: 600;
  background: color-mix(in srgb, var(--foreground) 4%, transparent);
}
.article-body blockquote {
  border-left: 3px solid color-mix(in srgb, var(--foreground) 20%, transparent);
  padding-left: 1.1rem;
  margin: 1.5rem 0;
  color: color-mix(in srgb, var(--foreground) 70%, transparent);
}

@media (prefers-reduced-motion: reduce) {
