/* ══════════════════════════════════════════════════════════════════════════
   KODELY PRODUCT SURFACE
   ══════════════════════════════════════════════════════════════════════════
   The tokens above (--accent, --brand-gradient, --glow…) are the MARKETING
   system and are ported from the approved reference mockup. Do not repoint
   them; the marketing pages read them directly.

   These are the PRODUCT tokens — the portal and the builder. They are additive
   and share the same brand hues on purpose, because a customer crosses
   marketing → portal → builder in one session and the seam should be
   invisible. What differs is density: marketing is a poster, the product is an
   instrument, so the product gets a surface ramp, semantic status colour, and
   a tighter spacing/type scale that the marketing pages have no use for.

   TYPEFACE: deliberately still Geist. A display serif was considered and
   rejected — the marketing site the customer just came from is set in Geist,
   and swapping faces at the /dashboard boundary would break the one continuity
   requirement that matters most. "Premium" here is bought with the type SCALE,
   tracking, tabular numerals and weight discipline below, not a second family.

   NEUTRALS are hue-biased toward the brand (a touch of magenta in light, a
   touch of indigo in dark) rather than pure grey, so panels sit in the same
   world as the accent instead of looking like a default admin theme. */
:root {
  /* Surface ramp — canvas sits BEHIND panels, so it is darker than --surface
     in light mode. Everything else steps up from there. */
  --surface-canvas: #faf8fb;
  --surface: #ffffff;
  --surface-2: #f5f2f7;
  --surface-3: #ece8f0;
  --surface-inset: #f8f6fa;

  --border-soft: rgba(11, 10, 13, 0.06);
  --border-mid: rgba(11, 10, 13, 0.1);
  --border-strong: rgba(11, 10, 13, 0.18);

  --text-1: #16131c;
  --text-2: #605b6b;
  --text-3: #948da3;
  --text-inv: #ffffff;

  /* Brand, as flat UI colour. --accent is the marketing pink; these add the
     tints a product needs (a fill you can put text on, a focus ring). */
  --brand: #e01b6e;
  --brand-hover: #c4155e;
  --brand-tint: rgba(224, 27, 110, 0.08);
  --brand-tint-2: rgba(224, 27, 110, 0.14);
  --brand-ring: rgba(224, 27, 110, 0.38);
  --brand-ink: #a41050;

  /* Semantic status. Kept clearly OFF the brand ramp: a "success" that reads
     as brand pink is unreadable as status, and the peach in the gradient is
     close enough to amber that warning is pushed yellow-ward to separate. */
  --ok: #0d8f5b;
  --ok-tint: rgba(13, 143, 91, 0.1);
  --warn: #a86a08;
  --warn-tint: rgba(214, 145, 20, 0.14);
  --danger: #cf2b3c;
  --danger-tint: rgba(207, 43, 60, 0.1);
  --info: #5b4ee0;
  --info-tint: rgba(91, 78, 224, 0.1);

  /* Elevation. Two axes deliberately: a neutral drop for depth plus a faint
     violet cast, which is what stops white cards on a white-ish canvas from
     looking like flat rectangles with a border. */
  --e1: 0 1px 2px rgba(11, 10, 13, 0.04);
  --e2:
    0 1px 2px rgba(11, 10, 13, 0.04), 0 8px 20px -12px rgba(90, 40, 140, 0.18);
  --e3:
    0 2px 4px rgba(11, 10, 13, 0.05), 0 24px 48px -24px rgba(90, 40, 140, 0.26);

  /* Radii. "Rounded but not bubbly" — the step from control (10) to card (14)
     to sheet (20) is what reads as considered; one radius everywhere is what
     reads as a Tailwind default. */
  --r-xs: 6px;
  --r-sm: 8px;
  --r-md: 10px;
  --r-lg: 14px;
  --r-xl: 20px;
  --r-2xl: 28px;
  --r-full: 999px;

  /* Motion. One easing for everything that enters or resizes, one for state
     flips. Durations are short on purpose: "fast and expensive", not flashy. */
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-io: cubic-bezier(0.4, 0, 0.2, 1);
  --t-1: 120ms;
  --t-2: 200ms;
  --t-3: 380ms;

  --sidebar-w: 248px;
  --sidebar-w-collapsed: 68px;
  --topbar-h: 60px;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light) {
    /* Deep navy-indigo rather than the marketing near-black. A product surface
       is looked at for an hour at a time and the slight blue lift reads as a
       lit room instead of a switched-off screen. */
    --surface-canvas: #080714;
    --surface: #100e1e;
    --surface-2: #191730;
    --surface-3: #232040;
    --surface-inset: #0c0b1a;

    --border-soft: rgba(228, 224, 255, 0.06);
    --border-mid: rgba(228, 224, 255, 0.11);
    --border-strong: rgba(228, 224, 255, 0.2);

    --text-1: #eceaf6;
    --text-2: #a49db8;
    --text-3: #6d6684;
    --text-inv: #0a0918;

    --brand: #ff5c97;
    --brand-hover: #ff7aab;
    --brand-tint: rgba(255, 92, 151, 0.12);
    --brand-tint-2: rgba(255, 92, 151, 0.2);
    --brand-ring: rgba(255, 92, 151, 0.45);
    --brand-ink: #ffd0e0;

    --ok: #34d399;
    --ok-tint: rgba(52, 211, 153, 0.14);
    --warn: #fbbf5a;
    --warn-tint: rgba(251, 191, 90, 0.14);
    --danger: #ff7080;
    --danger-tint: rgba(255, 112, 128, 0.14);
    --info: #9b8cff;
    --info-tint: rgba(155, 140, 255, 0.14);

    --e1: 0 1px 2px rgba(0, 0, 0, 0.5);
    --e2: 0 1px 2px rgba(0, 0, 0, 0.5), 0 10px 24px -14px rgba(0, 0, 0, 0.8);
    --e3: 0 2px 6px rgba(0, 0, 0, 0.55), 0 28px 56px -26px rgba(0, 0, 0, 0.9);
  }
}

:root.dark {
  --surface-canvas: #080714;
  --surface: #100e1e;
  --surface-2: #191730;
  --surface-3: #232040;
  --surface-inset: #0c0b1a;

  --border-soft: rgba(228, 224, 255, 0.06);
  --border-mid: rgba(228, 224, 255, 0.11);
  --border-strong: rgba(228, 224, 255, 0.2);

  --text-1: #eceaf6;
  --text-2: #a49db8;
  --text-3: #6d6684;
  --text-inv: #0a0918;

  --brand: #ff5c97;
  --brand-hover: #ff7aab;
  --brand-tint: rgba(255, 92, 151, 0.12);
  --brand-tint-2: rgba(255, 92, 151, 0.2);
  --brand-ring: rgba(255, 92, 151, 0.45);
  --brand-ink: #ffd0e0;

  --ok: #34d399;
  --ok-tint: rgba(52, 211, 153, 0.14);
  --warn: #fbbf5a;
  --warn-tint: rgba(251, 191, 90, 0.14);
  --danger: #ff7080;
  --danger-tint: rgba(255, 112, 128, 0.14);
  --info: #9b8cff;
  --info-tint: rgba(155, 140, 255, 0.14);

  --e1: 0 1px 2px rgba(0, 0, 0, 0.5);
  --e2: 0 1px 2px rgba(0, 0, 0, 0.5), 0 10px 24px -14px rgba(0, 0, 0, 0.8);
  --e3: 0 2px 6px rgba(0, 0, 0, 0.55), 0 28px 56px -26px rgba(0, 0, 0, 0.9);
}

/* Exposed to Tailwind so the product can be written as `bg-surface`,
   `text-text-2`, `border-border-mid`, `rounded-lg` etc. rather than as
   arbitrary-value brackets on every element. This is the whole reason the
   design system holds together across pages written by different hands. */
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);

  --color-canvas: var(--surface-canvas);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-inset: var(--surface-inset);

  --color-hair: var(--border-soft);
  --color-line-mid: var(--border-mid);
  --color-line-strong: var(--border-strong);

  --color-ink: var(--text-1);
  --color-ink-2: var(--text-2);
  --color-ink-3: var(--text-3);
  --color-ink-inv: var(--text-inv);

  --color-brand: var(--brand);
  --color-brand-hover: var(--brand-hover);
  --color-brand-tint: var(--brand-tint);
  --color-brand-tint-2: var(--brand-tint-2);
  --color-brand-ink: var(--brand-ink);

  --color-ok: var(--ok);
  --color-ok-tint: var(--ok-tint);
  --color-warn: var(--warn);
  --color-warn-tint: var(--warn-tint);
  --color-danger: var(--danger);
  --color-danger-tint: var(--danger-tint);
  --color-info: var(--info);
  --color-info-tint: var(--info-tint);

  --radius-xs: var(--r-xs);
  --radius-sm: var(--r-sm);
  --radius-md: var(--r-md);
  --radius-lg: var(--r-lg);
  --radius-xl: var(--r-xl);
  --radius-2xl: var(--r-2xl);

  --shadow-e1: var(--e1);
  --shadow-e2: var(--e2);
  --shadow-e3: var(--e3);
}

