/* Exposed to Tailwind so the product can be written as `bg-surface`,
   `text-text-2`, `border-border-mid`, `rounded-lg` etc. rather than as
   arbitrary-value brackets on every element. This is the whole reason the
   design system holds together across pages written by different hands. */
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);

  --color-canvas: var(--surface-canvas);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-inset: var(--surface-inset);

  --color-hair: var(--border-soft);
  --color-line-mid: var(--border-mid);
  --color-line-strong: var(--border-strong);

  --color-ink: var(--text-1);
  --color-ink-2: var(--text-2);
  --color-ink-3: var(--text-3);
  --color-ink-inv: var(--text-inv);

  --color-brand: var(--brand);
  --color-brand-hover: var(--brand-hover);
  --color-brand-tint: var(--brand-tint);
  --color-brand-tint-2: var(--brand-tint-2);
  --color-brand-ink: var(--brand-ink);

  --color-ok: var(--ok);
  --color-ok-tint: var(--ok-tint);
  --color-warn: var(--warn);
  --color-warn-tint: var(--warn-tint);
  --color-danger: var(--danger);
  --color-danger-tint: var(--danger-tint);
  --color-info: var(--info);
  --color-info-tint: var(--info-tint);

  --radius-xs: var(--r-xs);
  --radius-sm: var(--r-sm);
  --radius-md: var(--r-md);
  --radius-lg: var(--r-lg);
  --radius-xl: var(--r-xl);
  --radius-2xl: var(--r-2xl);

  --shadow-e1: var(--e1);
  --shadow-e2: var(--e2);
  --shadow-e3: var(--e3);
}

