/* ══════════════════════════════════════════════════════════════════════════
   PRODUCT UTILITIES
   Small, named, reused everywhere in the portal and builder. Each one exists
   because expressing it as a Tailwind class chain at every call site is how
   the old portal drifted out of alignment with itself.
   ══════════════════════════════════════════════════════════════════════════ */

/* One focus treatment for the whole product. Always visible, never removed —
   a ring that only shows on :focus-visible still has to exist. */
.k-focus:focus-visible {
  outline: 2px solid var(--brand-ring);
  outline-offset: 2px;
}

/* Type scale. Display sizes get negative tracking (optical correction — at
   32px+ the default spacing reads loose); the label size gets positive
   tracking and uppercase, which is the only place caps are used. */
.k-display {
  font-size: clamp(1.75rem, 1.2rem + 1.6vw, 2.35rem);
  line-height: 1.1;
  letter-spacing: -0.028em;
  font-weight: 600;
  text-wrap: balance;
}
.k-h1 {
  font-size: 1.5rem;
  line-height: 1.2;
  letter-spacing: -0.02em;
  font-weight: 600;
}
.k-h2 {
  font-size: 1.0625rem;
  line-height: 1.35;
  letter-spacing: -0.011em;
  font-weight: 600;
}
.k-label {
  font-size: 0.6875rem;
  line-height: 1;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--text-3);
}
/* Anywhere digits stack in a column — usage, credits, invoices, versions. */
.k-num {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

/* Any wide child (table, code, diagram) scrolls inside its own box so the
   page body never scrolls sideways. */
.k-scroll-x {
  overflow-x: auto;
  overscroll-behavior-x: contain;
}

/* A 1px brand-gradient hairline around a panel, done with a padding box so it
   works on any background without a second opaque layer to keep in sync. */
.k-gradient-border {
  background:
    linear-gradient(var(--surface), var(--surface)) padding-box,
    var(--brand-gradient) border-box;
  border: 1px solid transparent;
}

/* ── AI progress: the three states a step can be in ──
   Reused by the build overlay, the chat progress list and the preview
   loading treatment, so all three read as the same object. */
@keyframes k-step-pulse {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.88);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}
.k-step-active {
  animation: k-step-pulse 1.4s var(--ease-io) infinite;
}

@keyframes k-step-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.k-step-in {
  animation: k-step-in 0.32s var(--ease) both;
}

/* The travelling sheen along an in-progress bar. Position, not a moving
   child, so there is nothing to clip. */
@keyframes k-indeterminate {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}
.k-indeterminate {
  background-image: linear-gradient(
    90deg,
    var(--brand-tint) 0%,
    var(--brand) 40%,
    var(--brand) 60%,
    var(--brand-tint) 100%
  );
  background-size: 200% 100%;
  animation: k-indeterminate 1.6s linear infinite;
}

/* Preview while the AI is applying a change. Deliberately mild: the customer
   must still recognise their own site underneath, otherwise it reads as the
   site having been replaced rather than edited. */
.k-preview-busy {
  filter: blur(2.5px) saturate(0.82);
  transform: scale(1.008);
  transition:
    filter var(--t-3) var(--ease-io),
    transform var(--t-3) var(--ease-io);
}
.k-preview-idle {
  filter: none;
  transform: none;
  transition:
    filter var(--t-3) var(--ease-io),
    transform var(--t-3) var(--ease-io);
}

/* Chat message entrance — one shared animation so an assistant reply and a
   progress row arrive the same way. */
@keyframes k-msg-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.k-msg-in {
  animation: k-msg-in 0.28s var(--ease) both;
}

/* Ambient brand wash for hero panels inside the product (dashboard welcome,
   create-website prompt). Softer than the marketing .aura and NOT fixed —
   it belongs to its panel and scrolls with it. */
.k-wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  border-radius: inherit;
}
.k-wash::before,
.k-wash::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  filter: blur(72px);
}
.k-wash::before {
  width: 46%;
  aspect-ratio: 1;
  left: -6%;
  top: -42%;
  background: radial-gradient(closest-side, var(--glow), transparent);
}
.k-wash::after {
  width: 40%;
  aspect-ratio: 1;
  right: -4%;
  bottom: -50%;
  background: radial-gradient(closest-side, var(--glow-2), transparent);
}

/* Sidebar collapse. The width lives on the shell as a custom property so the
   sidebar, the mobile drawer and the main column all animate off one value
   and cannot disagree mid-transition. */
.k-shell {
  --shell-sidebar: var(--sidebar-w);
}
.k-shell[data-collapsed="true"] {
  --shell-sidebar: var(--sidebar-w-collapsed);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.2s !important;
  }
  /* Blur is motion-adjacent for some vestibular users and, unlike the
     animations above, is not covered by the duration override. */
  .k-preview-busy {
    filter: saturate(0.82);
    transform: none;
  }
}

