"use client";

import type { ReactNode } from "react";
import { ToastProvider } from "@/components/ui/Toast";
import { MobileNav } from "./MobileNav";
import { Sidebar } from "./Sidebar";

/* The frame every portal page renders inside. Pages supply content only — no
   page owns its own navigation, header chrome or toast host, which is the
   thing that let the old portal drift into five different header treatments.

   The main column is offset with padding-left driven by the SAME custom
   property the sidebar animates its width with, so the two move together
   instead of the content lagging a frame behind the rail. */
export function AppShell({
  children,
  initialCollapsed,
  user,
  balance,
}: {
  children: ReactNode;
  initialCollapsed: boolean;
  user: { email: string; name: string | null };
  balance: number;
}) {
  return (
    <ToastProvider>
      <div
        className="k-shell min-h-dvh bg-canvas"
        data-collapsed={initialCollapsed}
        style={{ ["--shell-sidebar" as string]: undefined }}
      >
        <Sidebar initialCollapsed={initialCollapsed} user={user} balance={balance} />
        <MobileNav user={user} balance={balance} />
        <div className="lg:pl-[var(--shell-pad)] transition-[padding] duration-[var(--t-2)] ease-[var(--ease)]">
          {/* pb-20 on small screens keeps the last row of content clear of the
              fixed bottom bar; without it the final card is permanently half
              hidden and looks like a rendering bug. */}
          <main className="mx-auto w-full max-w-[1400px] px-4 pt-6 pb-24 sm:px-6 lg:px-8 lg:pt-8 lg:pb-12">
            {children}
          </main>
        </div>
      </div>
    </ToastProvider>
  );
}

