5	import { PanelLeft, PanelLeftClose } from "lucide-react";
6	import { Logo, Mark } from "@/components/marketing/Logo";
7	import { isActive, NAV } from "./nav";
8	import type { NavItem } from "./nav";
9	import { UserMenu } from "./UserMenu";
10	
11	/** Controlled by AppShell — see the note there for why the state is not
12	    owned here. */
13	export function Sidebar({
14	  collapsed,
15	  onToggle,
16	  user,
17	  balance,
18	}: {
19	  collapsed: boolean;
20	  onToggle: () => void;
21	  user: { email: string; name: string | null };
22	  balance: number;
23	}) {
24	  const pathname = usePathname();
25	
26	  return (
27	    <aside
28	      // Reads the shell's custom property rather than branching on the prop:
29	      // one declaration, and the width interpolates instead of swapping.
30	      style={{ width: "var(--shell-sidebar)" }}
31	      className="fixed inset-y-0 left-0 z-40 hidden shrink-0 flex-col border-r border-hair bg-surface transition-[width] duration-[var(--t-2)] ease-[var(--ease)] lg:flex"
32	    >
33	      <div className="flex h-[var(--topbar-h)] items-center gap-2 px-3">
34	        <Link
35	          href="/dashboard"
36	          aria-label="Kodely home"
37	          className="k-focus flex min-w-0 items-center rounded-md px-1.5 py-1"
38	        >
39	          {/* Collapsed, only the mark. Both branches render the SAME <Mark>
40	              component (Logo is Mark + wordmark), so there is one source of
41	              truth for the brand shape and no second asset to keep in sync. */}
42	          {collapsed ? (
43	            <Mark size={22} />
44	          ) : (
45	            <Logo markSize={22} className="text-[0.9375rem]" />
46	          )}
47	        </Link>
48	        {!collapsed && (
49	          <button
50	            type="button"
51	            onClick={onToggle}
52	            aria-label="Collapse sidebar"
53	            title="Collapse sidebar"
54	            className="k-focus ml-auto rounded-md p-1.5 text-ink-3 transition-colors hover:bg-surface-2 hover:text-ink"
55	          >
56	            <PanelLeftClose className="size-4" />
57	          </button>
58	        )}
59	      </div>
60	
61	      {collapsed && (
62	        <button
63	          type="button"
64	          onClick={onToggle}
65	          aria-label="Expand sidebar"
66	          title="Expand sidebar"
67	          className="k-focus mx-auto mb-1 rounded-md p-1.5 text-ink-3 transition-colors hover:bg-surface-2 hover:text-ink"
68	        >
69	          <PanelLeft className="size-4" />
70	        </button>
71	      )}
72	
73	      <nav aria-label="Main" className="flex-1 overflow-y-auto px-2.5 pb-4">
74	        {NAV.map((group) => (
75	          <div key={group.title} className="mb-5">
76	            {/* The group heading disappears when collapsed but the grouping
77	                survives as spacing — the rhythm is what people navigate by
78	                once they know the product. */}
79	            {collapsed ? (
80	              <div className="mx-2 mb-2 h-px bg-hair" aria-hidden />
81	            ) : (
82	              <p className="k-label mb-1.5 px-2">{group.title}</p>
83	            )}
84	            <ul className="flex flex-col gap-0.5">
85	              {group.items.map((item) => (
86	                <li key={item.href}>
87	                  <NavLink item={item} active={isActive(item, pathname)} collapsed={collapsed} />
88	                </li>
89	              ))}
90	            </ul>
91	          </div>
92	        ))}
93	      </nav>
94	
95	      <UserMenu user={user} balance={balance} collapsed={collapsed} />
96	    </aside>
97	  );
98	}
99	
100	function NavLink({
101	  item,
102	  active,
103	  collapsed,
104	}: {
105	  item: NavItem;
106	  active: boolean;
107	  collapsed: boolean;
108	}) {
109	  const Icon = item.icon;
110	  return (
111	    <Link
112	      href={item.href}
113	      aria-current={active ? "page" : undefined}
