115	      // is unusable for anyone who has not memorised the order.
116	      title={collapsed ? item.label : undefined}
117	      className={[
118	        "k-focus group relative flex items-center gap-2.5 rounded-md px-2 py-1.5 text-[0.8125rem] font-medium",
119	        "transition-colors duration-[var(--t-1)]",
120	        collapsed ? "justify-center" : "",
121	        active ? "bg-brand-tint text-brand-ink dark:text-brand" : "text-ink-2 hover:bg-surface-2 hover:text-ink",
122	      ].join(" ")}
123	    >
