129	          aria-hidden
130	          className="absolute top-1/2 -left-2.5 h-4 w-0.5 -translate-y-1/2 rounded-r-full bg-brand"
131	        />
132	      )}
133	      <Icon className="size-4 shrink-0" strokeWidth={active ? 2.25 : 1.9} />
134	      {!collapsed && (
135	        <>
136	          <span className="truncate">{item.label}</span>
137	          {item.soon && (
138	            <span className="ml-auto rounded-full bg-surface-3 px-1.5 py-0.5 text-[0.625rem] font-medium text-ink-3">
139	              Soon
140	            </span>
141	          )}
142	        </>
143	      )}
144	    </Link>
145	  );
146	}

