import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";

const db = new DatabaseSync("board.sqlite");
const B = "720aa8c1-d259-4e49-b777-c58965efabd1";
const NAME = "Customer Portal & Builder Overhaul";

// Sits with the active work columns rather than at the bottom with research —
// the last time a new stage landed at position 29 of 32 it was invisible.
let col = db.prepare("SELECT id FROM columns WHERE boardId = ? AND name = ?").get(B, NAME);
if (!col) {
  db.prepare("UPDATE columns SET position = position + 1 WHERE boardId = ? AND position >= 7").run(B);
  const id = randomUUID();
  db.prepare("INSERT INTO columns (id, boardId, name, position) VALUES (?, ?, ?, 7)").run(id, B, NAME);
  col = { id };
  console.log("stage created at position 7");
}
const C = col.id;

const CARDS = [
  ["Design system: tokens, primitives and the app shell",
`DONE and verified (tsc clean, eslint 0/0). This is the foundation every other card in this stage builds on.

WHAT LANDED:
- app/globals.css — a PRODUCT token layer additive to the marketing one. Surface ramp, hue-biased neutrals, semantic status off the brand ramp, a radius step (control 10 / card 14 / sheet 20) and a motion scale. Exposed through @theme inline so pages write bg-surface / text-ink-2 / rounded-lg instead of arbitrary-value brackets — that bracket habit is most of why the old portal drifted.
- Dark mode moved to deep navy-indigo (#080714 canvas) per the brief, away from the marketing near-black.
- components/ui/ — Button, Card, Badge, Field, Progress, Skeleton, EmptyState, Menu, Modal, Toast, Segmented, Stat, Avatar, Spinner, AIProgress.
- components/app/ — Sidebar (collapsible, cookie-persisted so there is no hydration flash), MobileNav (drawer + thumb-reachable bottom bar), UserMenu, AppShell.
- app/(portal)/ route group; /dashboard and /settings moved into it. URLs unchanged.
- docs/design-system.md — the binding contract, including the audited list of what does not exist.

TYPEFACE DECISION: stayed on Geist. A display serif was considered and rejected — the marketing site the customer just came from is set in Geist and swapping faces at the /dashboard boundary breaks the one continuity requirement that matters most. Premium is bought with the type scale, tracking, tabular numerals and weight discipline instead.

WHAT IS NOT IN THE SYSTEM ON PURPOSE: no notification bell (no notifications backend), no plan chip (no subscription exists), no avatar image branch (no upload exists).`,
   "FEATURE", "HIGH", ["design-system", "portal"]],

  ["Portal backend reality audit — what is real vs what was only asked for",
`The audit that governs every other card here. Verdicts, each cited to file:line in the full report:

REAL: version history (checkpoints, restore, real line diff) · in-editor preview (interactive srcdoc iframe, owner-only) · publish · rename / duplicate / delete · credit balance, ledger, spend cap, per-build cost · templates (as prompts) · image attachment end-to-end.

PARTIAL: Home (projects + credits real; activity and plan absent) · My Websites (actions real; thumbnails, archived, domain absent) · Usage (credits real and per-site attributable; no reset date, no storage, no bandwidth) · Billing (packs + ledger real; no plan, price, renewal, payment method, invoices) · Settings (spend cap, rewards, delete, export real; name/password/2FA/sessions/notifications absent).

NOTHING AT ALL: Domains · Integrations · Support tickets · Workspaces, members, roles.

THE FIVE THAT WOULD HAVE BEEN THE MOST VISIBLE LIES:
1. "Kodely Pro — $XX/month, next billing date" — there is no subscription. Checkout is one-off payment mode for credit packs.
2. "Credits reset September 1" — credits never expire; the spend cap is a ROLLING 30 days chosen specifically so there is no reset day.
3. A screenshot thumbnail on every site card — nothing captures one. No field, no headless browser.
4. An Archived filter — no soft-delete column exists.
5. A ticket list with statuses — no ticket model; SupportNote is admin-only and the schema says outright it is never shown to the customer.

TWO THINGS THAT ARE NOT BUILT BUT ARE CHEAP AND REAL, now commissioned: editing User.name (field exists, no edit path) and an active-sessions list with revoke (Session is per-user and fully queryable; logout kills only the current one).`,
   "CHORE", "URGENT", ["audit", "portal", "honesty"]],

  ["Home dashboard + My Websites", "Commissioned. Website cards, real activity feed from Event, usage summary, grid/list, search, filter, sort, and the full per-site action menu. Thumbnail approach must not pose as a screenshot.", "FEATURE", "HIGH", ["portal"]],
  ["Create Website: prompt-first entry + honest build progress", "Commissioned. Prompt box as the only focus, image attach (real) but no generic file upload (not real), template hand-off, and AIProgress driven by the generate route's actual SSE events — not a timer.", "FEATURE", "HIGH", ["portal", "ai-ux"]],
  ["Builder overhaul: chat + live preview + every state", "Commissioned. Chat panel as an assistant, preview as a real browser, the eight editor states each designed, version history surfaced, and a mobile interaction that is not a shrunk desktop.", "FEATURE", "URGENT", ["builder", "ai-ux"]],
  ["Usage + Billing rebuilt on what actually exists", "Commissioned. Per-website credit attribution (real, one groupBy away), usage over time as a dependency-free accessible chart, spend cap, credit statement. No plan, no invoices, no reset date — those are stated as absent, not faked.", "FEATURE", "HIGH", ["portal", "billing"]],
  ["Settings split into sections + name editing + session revoke", "Commissioned. Sectioned settings, Danger Zone carrying the existing two-step deletion and data export, plus the two cheap real features: User.name editing and an active-sessions list with revoke.", "FEATURE", "HIGH", ["portal", "security"]],
  ["Support, Domains, Integrations — three honest pages over almost nothing", "Commissioned. Authenticated contact form with site context (no fake tickets), the real <slug>.kodely.site address per site with copy/open (no fake domain connect form), and a truthful integrations state.", "FEATURE", "NORMAL", ["portal", "honesty"]],
  ["Admin asset library — icons / images / videos", "Commissioned. Browse and inspect what the build agent can actually reach for today, with licence provenance as a first-class column. Catalogue is now 502 entries after the procedural imagery expansion.", "FEATURE", "NORMAL", ["admin", "assets"]],
];

const NA = db.prepare("SELECT id FROM columns WHERE boardId = ? AND name = ?").get(B, "Needs Attention").id;

const DECISIONS = [
  ["Custom domains: the single biggest gap between the portal brief and the product",
`Domains were specified as a full section — connect, purchase, DNS, SSL, primary domain. NONE of it exists: no Domain model, no customDomain field, no ACME code, no purchase flow. The host allowlist is hard-coded to three shapes in app/api/site/[slug]/site-host.ts:68-76, and the live SEO content already tells readers custom domains are unsupported.

Every published site DOES have a real working address at <slug>.kodely.site, so the page being built is genuinely useful. But "connect your own domain" is a real project, not a screen: a Domain model, DNS verification, certificate issuance and renewal, and a routing change at the edge.

DECISION NEEDED: is this a near-term commitment? It is one of the most common reasons a customer will not treat a builder as their real website, and it is also the most-requested paid upgrade trigger in this category.`,
   "IDEA", "HIGH", ["decision", "domains", "portal"]],

  ["There is no subscription — the portal brief assumed one throughout",
`The brief specified a plan name, a monthly price, a next-billing date, a payment method on file, invoice history, and a Free/Pro/Business comparison. The product sells one-off credit packs (500/$9, 2500/$40, 6000/$90) in Stripe payment mode. No plan, no renewal, no invoices fetched.

This is not a UI gap, it is a business-model question, and it is being answered by default right now: every screen that would show a plan instead shows a credit balance.

Worth noting the two are not merely different presentations. A subscription changes what the Usage page can honestly say (a reset date becomes real), what the sidebar can show, and what "upgrade" means as a call to action. It also interacts with the Kodely Pro credit thesis card in Needs Attention.

DECISION NEEDED: stay credit-only, or introduce a subscription. The portal has been built credit-only and truthfully; switching later is a billing project, not a restyle.`,
   "IDEA", "HIGH", ["decision", "billing", "pricing"]],

  ["Site cards have no thumbnail because nothing captures one",
`No screenshot field, no headless browser dependency, no image generation, nowhere to store one. A project card in any competitor product leads with a picture of the site; ours cannot.

Options, roughly in cost order: a deterministic generated cover from the site's own palette (cheap, honest, but not the site) · rendering the real build output into a tiny sandboxed iframe as a live thumbnail (real, uses infrastructure that already exists, but expensive at ten per page) · an actual capture service (a headless browser, storage, and an invalidation rule on every publish).

The card grid has been built without a fake screenshot. Which of the three we want is a product call.`,
   "IDEA", "NORMAL", ["decision", "portal"]],
];

const findCard = db.prepare(
  `SELECT c.id FROM cards c JOIN columns co ON co.id = c.columnId
   WHERE co.boardId = ? AND c.archivedAt IS NULL AND c.title = ?`,
);
const ins = db.prepare(
  "INSERT INTO cards (id, columnId, title, description, type, priority, labels, position) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
);
const maxPos = db.prepare("SELECT COALESCE(MAX(position), -1) AS p FROM cards WHERE columnId = ?");

for (const [target, list] of [[C, CARDS], [NA, DECISIONS]]) {
  for (const [title, desc, type, prio, labels] of list) {
    if (findCard.get(B, title)) { console.log(`skip | ${title.slice(0, 58)}`); continue; }
    ins.run(randomUUID(), target, title, desc, type, prio, JSON.stringify(labels), maxPos.get(target).p + 1);
    console.log(`card | ${title.slice(0, 58)}`);
  }
}

