import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";

const db = new DatabaseSync("board.sqlite");
const B = "720aa8c1-d259-4e49-b777-c58965efabd1";
const col = (n) => db.prepare("SELECT id FROM columns WHERE boardId = ? AND name = ?").get(B, n).id;
const DONE = col("Done — awaiting deploy");
const NA = col("Needs Attention");

const find = db.prepare(
  `SELECT c.id, c.title, c.columnId FROM cards c JOIN columns co ON co.id = c.columnId
   WHERE co.boardId = ? AND c.archivedAt IS NULL AND c.title LIKE ?`,
);
const addComment = db.prepare("INSERT INTO comments (id, cardId, authorName, body) VALUES (?, ?, 'Claude', ?)");
const maxPos = db.prepare("SELECT COALESCE(MAX(position), -1) AS p FROM cards WHERE columnId = ?");
const move = db.prepare("UPDATE cards SET columnId = ?, position = ? WHERE id = ?");
const ins = db.prepare(
  "INSERT INTO cards (id, columnId, title, description, type, priority, labels, position) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
);

// ── move the commissioned card to Done with its real report ──────────────────
const card = find.get(B, "%Admin asset library%");
if (card) {
  addComment.run(randomUUID(), card.id, `Built at /admin/assets — three tabs, backed by the SAME listAssets() that materialize.ts writes to disk and that find_assets is served from, so the id, format and byte size on screen are measured on the exact string the build agent is handed rather than on a parallel description of it.

REAL COUNTS: Icons 502 assets / 121.6 kB of source (icon 147, flag 250, gradient 30, divider 12, pattern 12, illustration 12, mark 11, backdrop 10, empty-state 8, mesh 6, texture 3, avatar 1). Images 0. Videos 0 — both truthfully empty, no invented rows.

Previews are generated by calling iconSvg/flagSvg/spotSvg directly rather than by rendering the catalogue's own 'source' field, because that field is JSX and an HTML parser silently drops strokeWidth. Inlined with dangerouslySetInnerHTML, justified in a comment that contrasts it against components/brand/LogoPreview.tsx where the input IS user-supplied and must never be inlined.

NO PRISMA MODEL, deliberately: the catalogue is literals in .ts files, so a table would be a second copy free to drift and needing seeding on every deploy. When Pixabay/Pexels assets start arriving per build, those are per-site records with timestamps and remote ids — a genuinely different table and the right moment to add one.

Search here is a literal substring match, NOT findAssets(). The page says so and points at GET /api/assets?q= for the agent's ranked, synonym-expanded search. Conflating 'what is in here' with 'what would the model pick' would make both answers less trustworthy.

UNTESTED: the page has never been loaded in a browser — reaching it needs an admin session against prod Postgres and that query was blocked. next build compiles the route; the whole data layer was executed directly (502 rows, all four facet builders, every preview branch) with 0 placeholder fallbacks and 0 empty CSS previews. Layout, spacing and dark mode are unverified.`);
  if (card.columnId !== DONE) {
    move.run(DONE, maxPos.get(DONE).p + 1, card.id);
    console.log("done | Admin asset library");
  }
}

// ── two findings that are real problems, not UI work ─────────────────────────
const CARDS = [
  ["195 of the 250 country flags are emoji text, which renders as grey boxes on Windows",
