const B = "720aa8c1-d259-4e49-b777-c58965efabd1";
const col = (n) => db.prepare("SELECT id FROM columns WHERE boardId=? AND name=?").get(B, n).id;
const DONE = col("Done — awaiting deploy");
const NA = col("Needs Attention");
const find = db.prepare(
  `SELECT c.id,c.title,c.columnId FROM cards c JOIN columns co ON co.id=c.columnId
   WHERE co.boardId=? AND c.archivedAt IS NULL AND c.title LIKE ?`,
);
const addC = db.prepare("INSERT INTO comments (id,cardId,authorName,body) VALUES (?,?,'Claude',?)");
const maxPos = db.prepare("SELECT COALESCE(MAX(position),-1) AS p FROM cards WHERE columnId=?");
const move = db.prepare("UPDATE cards SET columnId=?,position=? WHERE id=?");
const ins = db.prepare(
  "INSERT INTO cards (id,columnId,title,description,type,priority,labels,position) VALUES (?,?,?,?,?,?,?,?)",
);

const c = find.get(B, "%Create Website: prompt-first entry%");
if (c) {
  addC.run(
    randomUUID(),
    c.id,
    `Built and RENDERED against the running dev server on :3003 as a real authenticated user — the first page in this overhaul actually verified in a browser rather than only compiled.

/dashboard/new — one k-display heading, one prompt box in a single k-wash panel, everything else quiet underneath. Six one-tap example chips, attach-image, use-a-template, help-me-write-it into /wizard.

IMAGE HANDLING IS BETTER THAN WHAT IT COPIED. It narrows the picker to png/jpg/jpeg/webp and RE-ENCODES to JPEG, so the output always matches the data:image/(png|jpeg|webp);base64, regex at app/api/generate/route.ts:57. Anything else is refused in the UI with a reason instead of being silently dropped server-side later. The panel states the real limit: reference images only, first attempt only, no documents, no ZIP, no site upload.

CREDIT HONESTY, and this one is a genuine catch: it shows 120-550 as a RANGE, labelled "a range, not a quote". Balance at or below zero is a hard block (the route would 402 anyway). Below 550 it warns that THE BALANCE IS ONLY CHECKED WHEN A BUILD STARTS, so a build can finish and take you below zero — which is true, chargeForBuild just writes balance - credits. Nothing in the product said that before.

/dashboard/templates — leads with "These are briefs, not themes" and says outright there is no theme, no layout and no preview behind a card. Full brief collapsible with a real word count, copy, and hand-off to /dashboard/new?template=<id> pre-filled and editable. Public /templates untouched. It also found lib/templates.ts has 23 templates, not the 22 the audit reported; its UI counts the array so it is right either way.

THE ARCHITECTURAL FINDING, which changes the shape of the product: the launch screen runs the REAL build and only navigates to /projects/<id> on `done`. Navigating mid-stream closes the response body, triggers cancel(), and ABORTS THE BUILD SERVER-SIDE. So "narrate briefly then hand over" is not a design option — it would kill the build it was narrating. It therefore aborts on unmount deliberately, so "leaving this page stops the build" is TRUE rather than hopeful, and says so on screen next to a real Stop button.

UNTESTED, stated plainly: no live end-to-end build was fired because it spends real credits. The reducer is verified against synthetic-but-literal event sequences (happy path, one repair, pre-stream refusal, mid-build error, lost stream, post-terminal frames) and the stream parsing mirrors Editor.tsx's proven loop. The warn/danger credit callouts never rendered — the test account had 750, above the 550 estimate.`,
  );
  if (c.columnId !== DONE) {
    move.run(DONE, maxPos.get(DONE).p + 1, c.id);
    console.log("done | Create Website + Templates");
  }
}

const CARDS = [
  [
    "The six-step build progress in the brief is not supportable — five real steps shipped instead",
    `Recording this because it is the clearest example of the rule the whole overhaul is being held to.

The brief specified: Understanding your idea / Planning the structure / Designing the layout / Generating your website / Adding content / Finalizing your design.

THE STREAM CANNOT SUPPORT FOUR OF THOSE SIX. There is no planning marker, no designing marker, and no way to separate layout work from copy work — a write to Hero.tsx emits one `file` event either way. Shipping six would have meant inventing four.

WHAT THE STREAM ACTUALLY CARRIES: text, progress, status, file{path,action}, done{credits,remaining,filesWritten,buildId,repairAttempts,repairWaived,waivedCredits}, error{message}. Note `usage` is produced by the agent but consumed SERVER-SIDE for billing and never forwarded — so a live spend readout during a build is impossible without a route change.

THE FIVE SHIPPED STEPS, each with exactly one observable trigger:
  Creating your project              <- POST /api/projects returns an id
  Sending your brief to Kodely       <- POST /api/generate answers 200 (kill switch, balance, spend cap, rate limit all passed; Build row exists)
  Reading the brief and starter files<- first write evidence: a file event, or progress matching /^(Writing|Updating|Removing|Making an edit)\\b/
  Writing your site's files          <- progress === "Compiling the site"
  Compiling the site                 <- done

The reducer lives in build-steps.ts as a pure function WITH NO CLOCK ACCESS, so it physically cannot self-advance. A repair status moves the list BACKWARD and increments a real counter. error freezes the list and marks the dying step failed. A stream that closes without done or error reports a dropped connection, never "finished". The verbatim latest progress line renders under the list as the raw signal.

This is the pattern for every future progress UI in the product: one observable trigger per step, no timers, fewer truthful steps over more invented ones.`,
    "CHORE",
    "NORMAL",
    ["ai-ux", "honesty", "pattern"],
  ],
  [
    "A build can finish and take a customer below zero credits",
    `Found while writing honest cost copy for /dashboard/new, and it is a real behaviour rather than a UI concern.

The balance is checked when a build STARTS. It is not checked again when the build settles — chargeForBuild simply writes balance - credits. So a customer with 300 credits can start a build estimated at 120-550, have it come in at 480, and end at -180.

The new create page now warns about this explicitly when the balance is below the top of the estimate range. Nothing in the product said it before.

WHETHER THIS IS A BUG OR A DELIBERATE KINDNESS IS A PRODUCT CALL. Refusing to settle would mean either abandoning finished work the customer can see, or serving them a site they have not paid for. Going negative and blocking the NEXT build is arguably the better of the three. But it should be a decision on the record, and the spend cap is the control that actually bounds it.

Worth confirming: that a negative balance does in fact block the next build cleanly, and that the low-credits notification fires on the way down rather than only at zero.`,
    "BUG",
    "NORMAL",
    ["credits", "decision"],
  ],
  [
    "BuildingOverlay may now be dead code on the first-build path",
    `Consequence of how /dashboard/new had to be built.

The launch screen runs the real build to completion and only navigates to /projects/<id> on done — because navigating mid-stream closes the response body, fires cancel(), and aborts the build server-side. "Narrate briefly then hand over" is therefore not available as a design.

So a customer arriving in the builder from the new create flow arrives at a FINISHED site, and app/projects/[id]/BuildingOverlay.tsx will almost never be seen on a first build.

It is not necessarily dead — a direct link, a refresh mid-build, or a project created by some other path could still hit it. But it needs a deliberate decision rather than being left to rot: is it edit-only now, or does it keep a first-build branch?

Routed to the builder agent while it was still working. Confirm what it decided.`,
    "CHORE",
    "NORMAL",
    ["builder", "cleanup"],
  ],
];

for (const [t, d, ty, p, l] of CARDS) {
  if (find.get(B, `%${t.slice(0, 32)}%`)) {
    console.log(`skip | ${t.slice(0, 54)}`);
    continue;
  }
  ins.run(randomUUID(), NA, t, d, ty, p, JSON.stringify(l), maxPos.get(NA).p + 1);
  console.log(`card | ${t.slice(0, 54)}`);
}
console.log(
  `\nDone: ${db.prepare("SELECT COUNT(*) n FROM cards WHERE columnId=? AND archivedAt IS NULL").get(DONE).n}`,
);

