"use client";

import type { ReactNode } from "react";

export type SegmentOption<T extends string> = {
  value: T;
  label: string;
  /** When set, the label is hidden and this is the accessible name — used by
      the grid/list and device toggles, which are icon-only by convention. */
  iconOnly?: boolean;
  icon?: ReactNode;
};

/* A radio group wearing a segmented control's clothes. Real radios, not
   buttons: arrow-key navigation between options and single-tab-stop
   behaviour are what the customer's keyboard already expects from a
   this-or-that choice, and neither comes free with <button>. */
export function Segmented<T extends string>({
  name,
  value,
  onChange,
  options,
  size = "md",
  className = "",
  ariaLabel,
}: {
  name: string;
  value: T;
  onChange: (v: T) => void;
  options: SegmentOption<T>[];
  size?: "sm" | "md";
  className?: string;
  ariaLabel: string;
}) {
  const h = size === "sm" ? "h-7" : "h-8";
  return (
    <div
      role="radiogroup"
      aria-label={ariaLabel}
      className={`inline-flex items-center gap-0.5 rounded-md border border-hair bg-surface-2 p-0.5 ${className}`}
    >
      {options.map((o) => {
        const active = o.value === value;
        return (
          <label
            key={o.value}
            title={o.iconOnly ? o.label : undefined}
            className={[
              "relative inline-flex cursor-pointer items-center justify-center gap-1.5 rounded-[6px] px-2.5 text-[0.8125rem] font-medium",
              h,
              active
                ? "bg-surface text-ink shadow-e1"
                : "text-ink-2 hover:text-ink",
              "transition-colors duration-[var(--t-1)] has-[:focus-visible]:outline has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-[var(--brand-ring)]",
            ].join(" ")}
          >
            <input
              type="radio"
              name={name}
              value={o.value}
              checked={active}
              onChange={() => onChange(o.value)}
              className="sr-only"
            />
            {o.icon}
            {o.iconOnly ? <span className="sr-only">{o.label}</span> : o.label}
          </label>
        );
      })}
    </div>
  );
}

import {
  Blocks,
  CreditCard,
  Gauge,
  Globe,
  House,
  LayoutTemplate,
  LifeBuoy,
  Link2,
  Settings,
  Sparkles,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

export type NavItem = {
  href: string;
  label: string;
  icon: LucideIcon;
  /** Marks the destination as not yet backed by anything real. The item still
      appears — hiding it would leave the customer hunting for a feature we
      have talked about — but it is visibly labelled and its page says plainly
      what does not exist yet. See the honesty note below. */
  soon?: boolean;
  /** Exact-match highlighting. Without it /dashboard would light up for every
      page beneath it. */
  exact?: boolean;
};

export type NavGroup = { title: string; items: NavItem[] };

/* HONESTY RULE FOR THIS FILE
   ─────────────────────────
   Domains and Integrations have no backend whatsoever — no model, no route,
   no field (confirmed by a full audit of prisma/schema.prisma and app/api).
   They are kept in the navigation because they were specified as part of the
   product's shape, but they carry `soon` and their pages state exactly what
   is and is not possible today rather than showing a mock. A screen that
   looks operable and is not is worse than an absent one; a screen that says
   "this does not exist yet, here is what you have instead" is neither.

   Anything WITHOUT `soon` is fully wired to real data. Do not add an item
   here until that is true of it. */
export const NAV: NavGroup[] = [
  {
    title: "Workspace",
    items: [
      { href: "/dashboard", label: "Home", icon: House, exact: true },
      { href: "/dashboard/websites", label: "My Websites", icon: Globe },
      { href: "/dashboard/new", label: "Create Website", icon: Sparkles },
      { href: "/dashboard/templates", label: "Templates", icon: LayoutTemplate },
    ],
  },
  {
    title: "Manage",
    items: [
      { href: "/dashboard/usage", label: "Usage", icon: Gauge },
      { href: "/dashboard/billing", label: "Billing", icon: CreditCard },
      { href: "/dashboard/domains", label: "Domains", icon: Link2 },
      { href: "/dashboard/integrations", label: "Integrations", icon: Blocks, soon: true },
    ],
  },
  {
    title: "Support",
    items: [{ href: "/support", label: "Support", icon: LifeBuoy }],
  },
  {
    title: "Account",
    items: [{ href: "/settings", label: "Settings", icon: Settings }],
  },
];

/** Shared by the sidebar and the mobile drawer so the two can never disagree
    about which item is current. */
export function isActive(item: NavItem, pathname: string): boolean {
  return item.exact ? pathname === item.href : pathname.startsWith(item.href);
}

/** The four items that reach the mobile bottom bar. Chosen by frequency, not
    by nav order: on a phone the bar is the whole navigation for the tasks
    people actually do one-handed, and everything else lives in the drawer. */
export const MOBILE_BAR: NavItem[] = [
  { href: "/dashboard", label: "Home", icon: House, exact: true },
  { href: "/dashboard/websites", label: "Sites", icon: Globe },
  { href: "/dashboard/new", label: "Create", icon: Sparkles },
  { href: "/dashboard/usage", label: "Usage", icon: Gauge },
];

