import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";

const db = new DatabaseSync("board.sqlite");
const B = "720aa8c1-d259-4e49-b777-c58965efabd1";
const col = (n) => db.prepare("SELECT id FROM columns WHERE boardId = ? AND name = ?").get(B, n).id;
const STAGE = col("Customer Portal & Builder Overhaul");
const DONE = col("Done — awaiting deploy");

const find = db.prepare(
  `SELECT id, title FROM cards WHERE columnId = ? AND archivedAt IS NULL AND title LIKE ?`,
);
const addComment = db.prepare("INSERT INTO comments (id, cardId, authorName, body) VALUES (?, ?, 'Claude', ?)");
const maxPos = db.prepare("SELECT COALESCE(MAX(position), -1) AS p FROM cards WHERE columnId = ?");
const move = db.prepare("UPDATE cards SET columnId = ?, position = ? WHERE id = ?");

const UPDATES = [
  ["Home dashboard + My Websites", `SHIPPED. This card had been sitting as "Commissioned" from before the work started — updating with what actually landed.

HOME: k-wash hero, one primary button (Create Website), a real activity feed built off Event's per-user index — but honestly, joined against the project name where one still exists ("Deleted a site" when it doesn't, never a raw id). Credit summary phrases the balance as "about N more builds" rather than inventing a percentage of an allowance that doesn't exist.

MY WEBSITES: grid/list toggle, search, sort, and an HONEST filter set — no Archived filter, because there is no soft-delete column and it could never match anything. Building IS offered, gated on a stated rule: a RUNNING build only reads as "building" while younger than 10 minutes, double the generate route's own 300s ceiling, so an abandoned SSE row collapses instead of claiming to build forever.

THUMBNAIL DECISION: a generated cover, deliberately not shaped like a screenshot (no browser chrome, no fake layout). Uses the site's real brand-kit palette when one exists, otherwise a deterministic hash of the slug into curated pairs. The page says outright: "Covers are generated from each site's own colours — Kodely doesn't capture screenshots."

Delete restored the type-the-site's-name confirmation for PUBLISHED sites only (a regression I caught and fixed myself — the first pass dropped it when moving to the shared ConfirmModal).`],

  ["Builder overhaul: chat + live preview + every state", `SHIPPED, in two passes — the first agent was terminated by a session limit mid-edit, and a second pass finished and verified it.

Chat panel is a real assistant: named header, live status badge, undo/retry/stop all wired to what the server can actually do (stop genuinely aborts the request; no upload control exists because none is real). AI progress is driven by the ACTUAL generate-route SSE events — text/progress/status/file/done/error — not a timer. A repair moves the step list BACKWARD and increments a real counter; a dropped connection is reported as a dropped connection, never as success.

Preview is a real interactive srcdoc iframe (sandbox="allow-scripts allow-forms", no allow-same-origin) with device toggle, refresh, open-in-tab, zoom, fullscreen. All eight states designed, including Publishing, which had been a bare spinner.

Version history surfaces the two truths that matter: snapshots are pruned (newest 20 per project, only those over 30 days old eligible), and restoring refunds nothing and cancels nothing.

FOUR REAL DEFECTS FOUND AND FIXED DURING VERIFICATION: the failed-step icon in AIProgress was unreachable in every real code path; a customer-initiated Stop and a dropped connection were both rendering as a red "this step broke"; the connection-loss check used the wrong signal and could tell someone "nothing was charged" for a build that had already started; and the error copy needed a fourth branch distinguishing "the server said no" from "we never heard back and can't promise anything."`],

  ["Usage + Billing rebuilt on what actually exists", `SHIPPED, restructured a second time to match a reference layout the owner supplied, and it held its own honesty on the retry.

Kept everything that was already true and improved the presentation: gradient stat card for the balance (matching the sidebar's card, not contradicting it — no invented "75% of 1,000 monthly credits", no reset date), four plain stat cards with real deltas only where computable, credits-over-time as a dependency-free accessible SVG chart with a real table fallback, a per-website breakdown, and an explicit reconciliation row for credits spent on since-deleted projects (their buildId is SET NULL on delete, so the ledger total and the per-site sum would otherwise silently disagree).

Refused the donut chart from the reference explicitly: failed builds are never charged (verified against lib/credits.ts), so a slice attributing spend to failures would be a fabricated number, not a simplification.

Billing keeps the pack comparison and credit statement where the reference showed a plan card and invoice history, with EmptyState explaining there is no subscription rather than a fake Pro/Starter/Business table.`],
];

for (const [title, comment] of UPDATES) {
  const card = find.get(B, `%${title.slice(0, 30)}%`);
  if (!card) { console.log(`!! not found: ${title}`); continue; }
  addComment.run(randomUUID(), card.id, comment);
  console.log(`updated | ${card.title}`);
}

// Move all five to Done, now that all carry an accurate final report.
const cards = db.prepare(
  "SELECT id, title FROM cards WHERE columnId = ? AND archivedAt IS NULL ORDER BY position",
).all(STAGE);

for (const c of cards) {
  move.run(DONE, maxPos.get(DONE).p + 1, c.id);
  console.log(`moved to Done | ${c.title}`);
}

console.log(`\nStage now has: ${db.prepare("SELECT COUNT(*) n FROM cards WHERE columnId = ? AND archivedAt IS NULL").get(STAGE).n} cards`);
console.log(`Done column: ${db.prepare("SELECT COUNT(*) n FROM cards WHERE columnId = ? AND archivedAt IS NULL").get(DONE).n} cards`);

