import type { Metadata } from "next";
import type { ReactNode } from "react";
import Link from "next/link";
import { redirect } from "next/navigation";
import {
  ArrowDownRight,
  ArrowUpRight,
  Gauge,
  Hammer,
  PiggyBank,
  Receipt,
  Rocket,
  Wrench,
  XCircle,
  Zap,
} from "lucide-react";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { averageBuildCredits, getBalance, getSpendCapStatus, spentInWindow } from "@/lib/credits";
import { ButtonLink } from "@/components/ui/Button";
import { Card, CardHeader, SectionHeader } from "@/components/ui/Card";
import { EmptyState } from "@/components/ui/EmptyState";
import { Progress } from "@/components/ui/Progress";
import { Stat } from "@/components/ui/Stat";
import { SpendCapPanel } from "../billing/SpendCapPanel";
import { formatCredits, formatDay } from "../billing/ledger";
import {
  accountSpanDays,
  dailySpend,
  groupBuckets,
  ledgerTotals,
  monthToDate,
  notCharged,
  previousWindowSpend,
  siteUsage,
} from "./data";
import { RangeTabs } from "./RangeTabs";
import type { RangeKey } from "./RangeTabs";
import { UsageChart } from "./UsageChart";

export const dynamic = "force-dynamic";

// The "— Kodely" suffix comes from the title template on the (portal) layout.
export const metadata: Metadata = { title: "Usage" };

/* /dashboard/usage — what the credits went ON.
   ───────────────────────────────────────────────────────────────────────────
   The brief for this screen asked for storage, bandwidth, a plan allowance and
   a reset date. None of the four exist (docs/design-system.md, "What does not
   exist"), so none of the four are drawn here. What IS real turns out to be
   more useful anyway: every credit ever charged is a successful build, every
   build belongs to a website, and both facts are already in the database.

   Every figure on this page is in CREDITS. Build.costMicros is real model
   spend — the cost side of the retail prices in lib/stripe.ts — and it is used
   only inside the arithmetic in ./data.ts, never rendered as money.

   THREE THINGS THIS LAYOUT DELIBERATELY DOES NOT DO, all of which the visual
   reference for it showed:
     1. The gradient card does NOT read "75% of 1,000 monthly credits" or
        "resets in 18 days". There is no allowance to be a percentage of and no
        reset date to count down to. It shows the balance and what it buys, in
        the same words as components/app/SidebarFooter.tsx and the /support
        card, because those three sit in front of the same customer.
     2. There is NO donut splitting spend across successful, failed and "other"
        builds. Failed builds are charged zero — chargeForBuild is only reached
        on the SUCCEEDED path in app/api/generate/route.ts, and both failure
        paths write creditsCharged: 0 and no ledger row — so that donut would
        be one 100% slice and two empty ones. The honest breakdown of spend is
        by WEBSITE, which is what "Where your credits went" draws, and the
        zero-charge story is the "What isn't charged" strip at the bottom.
     3. Deltas appear on exactly ONE stat, and only when the account is old
        enough for the comparison period to be real. See previousWindowSpend. */

// Closed range table, looked up with hasOwnProperty so a query string of
// "constructor" or "__proto__" resolves to a miss rather than to something on
// Object.prototype.
const RANGES: Record<string, true> = { "30": true, "90": true, all: true };
const FIXED_DAYS: Record<string, number> = { "30": 30, "90": 90 };
const DEFAULT_RANGE: RangeKey = "30";

// Above this many days a daily bar is thinner than the gap beside it, so the
// chart groups into weeks instead. See groupBuckets in ./data.ts.
const WEEKLY_ABOVE_DAYS = 120;

const MONTH = new Intl.DateTimeFormat("en-GB", {
  month: "long",
  year: "numeric",
  timeZone: "UTC",
});

function pickRange(params: Record<string, string | string[] | undefined>): RangeKey {
  const raw = Object.prototype.hasOwnProperty.call(params, "range") ? params.range : undefined;
  // `?range=30&range=90` arrives as an array; there is no sane single answer to
  // that, so it falls through to the default rather than picking one at random.
  const key = typeof raw === "string" ? raw : DEFAULT_RANGE;
  if (Object.prototype.hasOwnProperty.call(RANGES, key)) return key as RangeKey;
  return DEFAULT_RANGE;
}

export default async function UsagePage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const rangeKey = pickRange(await searchParams);

  const [cap, span] = await Promise.all([
    getSpendCapStatus(user.id),
    // "All time" has to be a real span, not an arbitrary large number of days.
    accountSpanDays(user.id),
  ]);

  // A null span means no ledger rows at all, which should not happen (the
  // signup grant writes one) but is not worth crashing over: fall back to the
  // default window and label it as such.
  const days =
    rangeKey === "all" ? Math.max(1, span ?? FIXED_DAYS[DEFAULT_RANGE]) : FIXED_DAYS[rangeKey];
  const rangeLabel =
    rangeKey === "all" && span !== null
      ? `the ${formatCredits(span)} days since your account opened`
      : `the last ${formatCredits(days)} days`;

  const [
    balance,
    spent,
    avgBuildCredits,
    measuredBuilds,
    sites,
    totals,
    waived,
    dayBuckets,
    trend,
    mtd,
  ] = await Promise.all([
    getBalance(user.id),
    // getSpendCapStatus skips the spend query when the user is uncapped; this
    // page needs the figure either way, and it must be the same query the cap
    // enforces so the two can't disagree.
    cap.cap === null ? spentInWindow(user.id) : Promise.resolve(cap.spent),
    averageBuildCredits(user.id),
    // averageBuildCredits falls back to a global constant when there is no
    // history. That constant is a fine default for "builds remaining" — the
    // rail and the /support card both use it that way — but it is NOT a
    // measurement of this person, so any tile claiming to describe THEIR builds
    // waits for this count.
    db.build.count({
      where: { project: { userId: user.id }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
    }),
    siteUsage(user.id),
    ledgerTotals(user.id),
    notCharged(user.id),
    dailySpend(user.id, days),
    previousWindowSpend(user.id),
    monthToDate(user.id),
  ]);

  const buckets = groupBuckets(dayBuckets, days > WEEKLY_ABOVE_DAYS ? 7 : 1);

  const attributed = sites.reduce((sum, s) => sum + s.credits, 0);
  // Deleting a project cascades its builds away and SET NULLs the ledger's
  // buildId, so the charge outlives the thing it was for. That gap is real and
  // is shown as its own row rather than quietly rounding the percentages.
  const orphaned = Math.max(0, totals.spent - attributed);
  const largest = Math.max(attributed > 0 ? sites[0].credits : 0, orphaned, 1);
  // A real 1-credit site rounding to a flat "0%" reads as "this cost nothing",
  // which is the one thing it definitely did not do.
  const share = (credits: number) => {
    if (totals.spent <= 0 || credits <= 0) return "0%";
    const pct = (credits / totals.spent) * 100;
    return pct < 1 ? "<1%" : `${Math.round(pct)}%`;
  };

  // The same arithmetic the sidebar rail and the /support card do, so all three
  // answer "how much more can I build?" with the same number. No denominator is
  // invented anywhere: there is no allowance for the balance to be a fraction
  // of, which is exactly why none of the three draws a bar.
  const buildsLeft = avgBuildCredits > 0 ? Math.floor(balance / avgBuildCredits) : 0;

  // Only computed when the account lived through the whole earlier window, and
  // only expressed as a percentage when there is a non-zero base to divide by.
  const delta =
    trend.comparable && trend.previous > 0
      ? Math.round(((spent - trend.previous) / trend.previous) * 100)
      : null;

  return (
    <>
      <SectionHeader
        as="h1"
        title="Usage & Credits"
        description="Track your AI credits usage and build activity."
        action={
          <ButtonLink href="/dashboard/billing" variant="secondary" size="sm">
            Billing &amp; statements
          </ButtonLink>
        }
      />

      {/* ── Where you stand ─────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-5">
        {/* The one gradient fill this page contributes, and the reason the
            gradient rule in docs/design-system.md now names four places. No
            bar, no percentage, no reset: credits are bought in packs and never
            expire, so a denominator would have to be invented. The number and
            what it buys is the whole truth available — the same sentence the
            rail beside this page is already showing. */}
        <div className="btn-cta-gradient relative overflow-hidden rounded-xl p-5 text-white shadow-e2">
          <div className="flex items-start justify-between gap-2">
            <p className="text-[0.6875rem] leading-none font-semibold tracking-[0.07em] uppercase opacity-80">
              Credits left
            </p>
            <Zap className="size-4 shrink-0 opacity-80" aria-hidden />
          </div>
          <p className="mt-3 flex items-baseline gap-1.5">
            <span className="k-num text-2xl leading-none font-semibold tracking-tight">
              {formatCredits(balance)}
            </span>
            <span className="text-[0.8125rem] opacity-90">credits</span>
          </p>
          <p className="mt-2 text-xs leading-relaxed opacity-95">
            {balance <= 0
              ? "Out of credits — the next build won't start until you top up."
              : buildsLeft >= 1
                ? `About ${formatCredits(buildsLeft)} more ${buildsLeft === 1 ? "build" : "builds"}.`
                : "Not quite enough for a full build."}
          </p>
          <p className="mt-1.5 text-[0.6875rem] leading-relaxed opacity-85">
            {measuredBuilds > 0
              ? `Measured from your own builds, averaging ${formatCredits(avgBuildCredits)} credits each.`
              : `Based on a typical build, about ${formatCredits(avgBuildCredits)} credits.`}{" "}
            Credits never expire and nothing renews.
          </p>
        </div>

        <StatTile
          icon={<Receipt className="size-4" aria-hidden />}
          label="Credits spent"
          value={formatCredits(spent)}
          unit="credits"
          detail={
            <>
              {delta !== null && (
                <span className="mb-1 flex items-center gap-1 font-medium text-ink-2">
                  {delta >= 0 ? (
                    <ArrowUpRight className="size-3.5 shrink-0" aria-hidden />
                  ) : (
                    <ArrowDownRight className="size-3.5 shrink-0" aria-hidden />
                  )}
                  <span className="k-num">{Math.abs(delta)}%</span>
                  <span>vs the 30 days before</span>
                </span>
              )}
              A rolling window measured to the hour, not a calendar month. There is no reset day.
              {delta === null && trend.comparable && trend.previous === 0
                ? " Nothing was spent in the 30 days before this one, so there is no change to quote."
                : ""}
            </>
          }
        />

        <StatTile
          icon={<Gauge className="size-4" aria-hidden />}
          label="Your average build"
          value={measuredBuilds > 0 ? formatCredits(avgBuildCredits) : "—"}
          unit={measuredBuilds > 0 ? "credits" : undefined}
          detail={
            measuredBuilds > 0
              ? `Measured across your recent builds — ${formatCredits(measuredBuilds)} charged so far.`
              : "Nothing measured yet. You haven't been charged for a build."
          }
        />

        <StatTile
          icon={<Hammer className="size-4" aria-hidden />}
          label="Builds this month"
          value={formatCredits(mtd.builds)}
          unit={mtd.builds === 1 ? "build" : "builds"}
          detail={`Charged builds since 1 ${MONTH.format(new Date(mtd.start))} (UTC). A calendar count for orientation — nothing resets on the 1st.`}
        />

        <StatTile
          icon={<Rocket className="size-4" aria-hidden />}
          label="Builds you can afford"
          value={formatCredits(buildsLeft)}
          unit="more"
          detail={
            measuredBuilds > 0
              ? "At your own measured average. A bigger site costs more than a smaller one."
              : "Based on a typical Kodely build, not on you — you haven't had one charged yet, so there is nothing of your own to measure."
          }
        />
      </div>

      {/* ── The two-column body ─────────────────────────────────────────── */}
      <div className="mt-4 grid grid-cols-1 items-start gap-4 lg:grid-cols-3">
        <Card className="lg:col-span-2">
          <CardHeader
            title="Credits over time"
            description="Only successful, metered builds are charged, so only those appear."
            action={
              <RangeTabs
                value={rangeKey}
                allLabel={span === null ? "All time" : `All time`}
              />
            }
          />

          <UsageChart buckets={buckets} days={days} rangeLabel={rangeLabel} />

          <p className="mt-4 text-xs leading-relaxed text-ink-3">
            These bars are UTC calendar {days > WEEKLY_ABOVE_DAYS ? "weeks" : "days"}; the
            &ldquo;credits spent&rdquo; figure above is a rolling window measured to the hour. The
            two totals can differ by up to one {days > WEEKLY_ABOVE_DAYS ? "week" : "day"}&apos;s
            spend, and that is the reason — neither is an estimate.
          </p>
        </Card>

        <div className="flex flex-col gap-4">
          {/* ── This calendar month, said plainly as a calendar month ───── */}
          <Card>
            <CardHeader
              title="Usage this month"
              description={`1–${mtd.daysElapsed} ${MONTH.format(new Date(mtd.start))}, UTC.`}
            />
            <div className="mt-5 grid grid-cols-2 gap-x-6 gap-y-6 divide-x divide-hair">
              <Stat
                label="Credits spent"
                value={formatCredits(mtd.credits)}
                unit="credits"
                detail="Every credit that has come off your balance since the 1st."
              />
              <Stat
                className="pl-6"
                label="Builds charged"
                value={formatCredits(mtd.builds)}
                unit={mtd.builds === 1 ? "build" : "builds"}
                detail="Successful builds with measured model cost."
              />
            </div>
            <p className="mt-4 text-xs leading-relaxed text-ink-3">
              A month boundary is a convenient way to read the chart and nothing more. Nothing
              resets on the 1st: credits never expire, there is no monthly allowance, and the
              spending cap below rolls day by day.
            </p>
          </Card>

          {/* ── Per-website attribution ─────────────────────────────────── */}
          <Card>
            <CardHeader
              title="Where your credits went"
              description="Every charge on this account is one successful site build, grouped by the website it built."
            />

            {sites.length === 0 && orphaned === 0 ? (
              <EmptyState
                className="mt-5"
                kind="empty"
                title="Nothing charged yet"
                body="You haven't been charged for a build, so there is nothing to break down. Build something and this fills in on its own."
                action={
                  <ButtonLink href="/dashboard/new" variant="secondary" size="sm">
                    Create a website
                  </ButtonLink>
                }
              />
            ) : (
              <>
                <ul className="mt-5 flex flex-col gap-4">
                  {sites.map((site) => (
                    <SiteRow
                      key={site.projectId}
                      name={
                        <Link
                          href={`/projects/${site.projectId}`}
                          className="k-focus rounded-sm font-medium break-words text-ink hover:text-brand"
                        >
                          {site.name}
                        </Link>
                      }
                      credits={site.credits}
                      max={largest}
                      share={share(site.credits)}
                      tone="brand"
                      barLabel={`${site.name}: ${formatCredits(site.credits)} credits`}
                      footnote={
                        <>
                          <span className="k-num">{formatCredits(site.builds)}</span>{" "}
                          {site.builds === 1 ? "build" : "builds"} · last charged{" "}
                          <span className="k-num">{formatDay(site.lastAt)}</span>
                        </>
                      }
                    />
                  ))}

                  {orphaned > 0 && (
                    <SiteRow
                      name={
                        <span className="font-medium break-words text-ink-2">
                          Websites you&apos;ve deleted
                        </span>
                      }
                      credits={orphaned}
                      max={largest}
                      share={share(orphaned)}
                      tone="neutral"
                      barLabel={`Deleted websites: ${formatCredits(orphaned)} credits`}
                      footnote="Their build records are gone, so these charges can no longer be pointed at a site — but the credits really were spent, so they stay on your statement."
                    />
                  )}
                </ul>

                <p className="mt-4 text-xs leading-relaxed text-ink-3">
                  Shares are of <span className="k-num">{formatCredits(totals.spent)}</span> credits
                  spent in total, against <span className="k-num">{formatCredits(totals.added)}</span>{" "}
                  ever added (welcome credits, top-ups and rewards combined).
                </p>
              </>
            )}
          </Card>
        </div>
      </div>

      {/* ── The one real control over usage ─────────────────────────────── */}
      <div className="mt-4">
        <SpendCapPanel cap={cap.cap} spent={spent} />
      </div>

      {/* ── The bills that never arrived ────────────────────────────────── */}
      <section className="mt-6">
        <SectionHeader
          title="What isn't charged"
          description="Kodely's two billing rules, restated as arithmetic on your own account rather than as a promise."
        />
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
          <WaivedTile
            icon={<XCircle className="size-4" aria-hidden />}
            label="Builds that failed"
            value={formatCredits(waived.failedBuilds)}
            detail="Recorded at their true cost and charged zero credits. A build you can't use is never a build you pay for."
          />
          <WaivedTile
            icon={<Wrench className="size-4" aria-hidden />}
            label="Builds we repaired"
            value={formatCredits(waived.repairedBuilds)}
            detail="Didn't compile first time. You were charged for your original attempt only — the repair pass is on us."
          />
          <WaivedTile
            icon={<PiggyBank className="size-4" aria-hidden />}
            label="Credits absorbed on repairs"
            value={formatCredits(waived.repairWaivedCredits)}
            detail="Worked out from what those repaired builds actually cost against what you paid, rounded down. The real figure is this or a little more."
          />
        </div>
      </section>

      {/* ── Say plainly what is not measured ────────────────────────────── */}
      <div className="mt-4">
        <EmptyState
          kind="unavailable"
          title="Storage and bandwidth aren't measured"
          body="Nothing in Kodely records how much disk your sites take up or how much traffic they serve, so there is no honest number to put here. Credits are the only thing this account meters — and there is no plan, allowance or renewal date behind them either."
        />
      </div>
    </>
  );
}

/** One of the four plain stat cards in the top row. The icon chip is
    decorative — it carries no status, which is why it is brand tint rather
    than an `ok`/`warn` tint that would imply one. */
function StatTile({
  icon,
  label,
  value,
  unit,
  detail,
}: {
  icon: ReactNode;
  label: string;
  value: string;
  unit?: string;
  detail: ReactNode;
}) {
  return (
    <Card className="flex flex-col">
      <span
        aria-hidden
        className="mb-4 grid size-8 shrink-0 place-items-center rounded-md bg-brand-tint text-brand-ink dark:text-brand"
      >
        {icon}
      </span>
      <Stat label={label} value={value} unit={unit} detail={detail} />
    </Card>
  );
}

/** One tile in the bottom "what isn't charged" strip. */
function WaivedTile({
  icon,
  label,
  value,
  detail,
}: {
  icon: ReactNode;
  label: string;
  value: string;
  detail: ReactNode;
}) {
  return (
    <Card className="flex items-start gap-3">
      <span
        aria-hidden
        className="grid size-9 shrink-0 place-items-center rounded-md bg-surface-2 text-ink-2"
      >
        {icon}
      </span>
      <div className="min-w-0 flex-1">
        <Stat label={label} value={value} detail={detail} />
      </div>
    </Card>
  );
}

/** One website's share of spend: the figure, a bar against the largest single
    line, and the percentage of everything ever spent. Rows rather than a table
    because this column is a third of the page wide — a five-column table here
    would scroll sideways inside its own box on every screen. */
function SiteRow({
  name,
  credits,
  max,
  share,
  tone,
  barLabel,
  footnote,
}: {
  name: ReactNode;
  credits: number;
  max: number;
  share: string;
  tone: "brand" | "neutral";
  barLabel: string;
  footnote: ReactNode;
}) {
  return (
    <li>
      <div className="flex items-baseline justify-between gap-3">
        <span className="min-w-0 text-sm">{name}</span>
        <span className="k-num shrink-0 text-sm font-medium whitespace-nowrap text-ink">
          {formatCredits(credits)}
        </span>
      </div>
      <div className="mt-2 flex items-center gap-2">
        <Progress className="flex-1" size="sm" tone={tone} value={credits} max={max} label={barLabel} />
        <span className="k-num w-9 shrink-0 text-right text-xs text-ink-3">{share}</span>
      </div>
      <p className="mt-1.5 text-xs leading-relaxed text-ink-3">{footnote}</p>
    </li>
  );
}

import type { Metadata } from "next";
import type { ReactNode } from "react";
import Link from "next/link";
import { redirect } from "next/navigation";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import {
  MICROS_PER_CREDIT,
  averageBuildCredits,
  estimateCredits,
  getBalance,
  getSpendCapStatus,
  spentInWindow,
} from "@/lib/credits";
import { CREDIT_PACKS, billingEnabled } from "@/lib/stripe";
import { ButtonLink, buttonClass } from "@/components/ui/Button";
import { Card, CardHeader, SectionHeader } from "@/components/ui/Card";
import { EmptyState } from "@/components/ui/EmptyState";
import { Stat, StatRow } from "@/components/ui/Stat";
import TopUpButton from "../TopUpButton";
import { SpendCapPanel } from "./SpendCapPanel";
import {
  describeReason,
  formatCredits,
  formatDay,
  formatTime,
  formatUsdCents,
  signedCredits,
} from "./ledger";

export const dynamic = "force-dynamic";

// The "— Kodely" suffix comes from the title template on the (portal) layout.
// This page previously inherited the MARKETING homepage title, so the tab for
// a customer's credit statement read "Kodely — AI Website Builder".
export const metadata: Metadata = { title: "Billing & credits" };

/* /dashboard/billing — the customer's own view of the ledger.
   ───────────────────────────────────────────────────────────────────────────
   READ-ONLY, end to end: this page never writes to CreditLedger, never grants
   or deducts, and the only money action it offers is the checkout owned by
   TopUpButton. The ledger is append-only and auditable by design (see
   prisma/schema.prisma and lib/credits.ts) — it was simply never shown to the
   person it is about.

   WHAT THIS PAGE REFUSES TO DRAW, because none of it exists:
     · a plan, a price per month, or a renewal date — checkout is one-off
       `payment` mode for credit packs (lib/stripe.ts), and nothing subscribes;
     · a saved payment method — only User.stripeCustomerId is stored and it is
       never read back from Stripe;
     · invoice history — no Stripe invoice is ever fetched. The statement below
       is the only history that exists, and it is a better one;
     · a credit reset date — credits never expire and the cap window rolls.
   The last card says all of that out loud rather than leaving the customer to
   wonder where their plan went. */

const PAGE_SIZE = 25;

export default async function BillingPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const cap = await getSpendCapStatus(user.id);

  const [balance, spent, avgBuildCredits, measuredBuilds, totalEntries] = await Promise.all([
    getBalance(user.id),
    // getSpendCapStatus skips the spend query when uncapped; this page needs it
    // either way. Same shape as app/(portal)/settings/page.tsx so both report
    // the number the cap actually enforces.
    cap.cap === null ? spentInWindow(user.id) : Promise.resolve(cap.spent),
    averageBuildCredits(user.id),
    // averageBuildCredits falls back to a global constant when a user has no
    // history. That constant is a reasonable default for "builds remaining" but
    // it is NOT a measurement of this person, so the tile below only shows an
    // average when this count says there is one.
    db.build.count({
      where: { project: { userId: user.id }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
    }),
    db.creditLedger.count({ where: { userId: user.id } }),
  ]);

  const pageCount = Math.max(1, Math.ceil(totalEntries / PAGE_SIZE));

  // hasOwnProperty rather than `in`: `?page=…` is attacker-controlled and a
  // prototype key ("constructor") must read as absent, not as a function.
  const params = await searchParams;
  const rawPage = Object.prototype.hasOwnProperty.call(params, "page") ? params.page : undefined;
  const requested = Number(typeof rawPage === "string" ? rawPage : Number.NaN);
  const page =
    Number.isInteger(requested) && requested >= 1 ? Math.min(requested, pageCount) : 1;

  const entries = await db.creditLedger.findMany({
    where: { userId: user.id },
    // Same ordering as getBalance in lib/credits.ts, with `id` as a stable
    // tiebreak — so the top row on page 1 IS the row that defines the balance.
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    skip: (page - 1) * PAGE_SIZE,
    take: PAGE_SIZE,
    select: {
      id: true,
      createdAt: true,
      delta: true,
      reason: true,
      balanceAfter: true,
      build: {
        // repairAttempts + costMicros + creditsCharged are here for one reason,
        // spelled out in the chargeForBuild comment in lib/credits.ts: the
        // reason string stays exactly "build" even when rule 4 waived a repair,
        // so the waiver has to be read off the build row instead. Nothing here
        // is rendered as money — see the note where the row is drawn.
        select: {
          repairAttempts: true,
          costMicros: true,
          creditsCharged: true,
          project: { select: { id: true, name: true } },
        },
      },
    },
  });

  const canTopUp = billingEnabled();
  const create = estimateCredits("create");
  const edit = estimateCredits("edit");

  const firstIndex = totalEntries === 0 ? 0 : (page - 1) * PAGE_SIZE + 1;
  const lastIndex = (page - 1) * PAGE_SIZE + entries.length;

  return (
    <>
      <SectionHeader as="h1"
        title="Billing & credits"
        description={`${user.email} — billed per build, never per month.`}
        action={
          <ButtonLink href="/dashboard/usage" variant="secondary" size="sm">
            Usage breakdown
          </ButtonLink>
        }
      />

      {/* ── Where you stand ─────────────────────────────────────────────── */}
      <Card>
        <StatRow>
          <Stat
            label="Credits left"
            value={formatCredits(balance)}
            unit="credits"
            detail={
              balance === 0
                ? "You're out of credits. Nothing expired — this is simply what's left."
                : "Credits never expire and nothing renews."
            }
          />
          <Stat
            label="Used · last 30 days"
            value={formatCredits(spent)}
            unit="credits"
            detail="A rolling window, not a calendar month. There is no reset day."
          />
          <Stat
            label="Your average build"
            value={measuredBuilds > 0 ? formatCredits(avgBuildCredits) : "—"}
            unit={measuredBuilds > 0 ? "credits" : undefined}
            detail={
              measuredBuilds > 0
                ? `Measured across your recent builds — ${formatCredits(measuredBuilds)} charged so far.`
                : "Nothing measured yet — you haven't been charged for a build."
            }
          />
          <Stat
            label="Statement entries"
            value={formatCredits(totalEntries)}
            detail="Every credit that has ever moved on this account, listed below."
          />
        </StatRow>
      </Card>

      {/* ── Adding credits ──────────────────────────────────────────────── */}
      <Card className="mt-4">
        <CardHeader
          title="Add credits"
          description="One-off packs. A single payment each time — nothing subscribes, nothing renews, and no card is stored on your Kodely account."
        />

        {canTopUp ? (
          <>
            {/* Packs come from the server's own CREDIT_PACKS table so this page
                cannot drift from what checkout will actually charge. */}
            <div className="k-scroll-x mt-5 rounded-lg border border-hair">
              <table className="w-full min-w-xl text-left text-sm">
                <caption className="sr-only">
                  The three credit packs, their prices and their price per credit.
                </caption>
                <thead>
                  <tr className="border-b border-hair">
                    <th scope="col" className="k-label px-4 py-2.5 font-semibold">
                      Pack
                    </th>
                    <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
                      Credits
                    </th>
                    <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
                      Price
                    </th>
                    <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
                      Per credit
                    </th>
                    <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
                      Your builds
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-hair">
                  {CREDIT_PACKS.map((pack) => (
                    <tr key={pack.id}>
                      <th scope="row" className="px-4 py-3 text-left font-medium text-ink">
                        {pack.label}
                      </th>
                      <td className="k-num px-4 py-3 text-right whitespace-nowrap text-ink">
                        {formatCredits(pack.credits)}
                      </td>
                      <td className="k-num px-4 py-3 text-right whitespace-nowrap text-ink">
                        {formatUsdCents(pack.priceUsdCents)}
                      </td>
                      <td className="k-num px-4 py-3 text-right whitespace-nowrap text-ink-2">
                        ${(pack.priceUsdCents / 100 / pack.credits).toFixed(3)}
                      </td>
                      <td className="k-num px-4 py-3 text-right whitespace-nowrap text-ink-2">
                        {measuredBuilds > 0
                          ? `about ${formatCredits(Math.floor(pack.credits / avgBuildCredits))}`
                          : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <p className="mt-3 text-xs leading-relaxed text-ink-3">
              {measuredBuilds > 0
                ? "The last column is that pack divided by your own measured average build, rounded down. It is a guide, not an entitlement — a bigger site costs more than a smaller one."
                : "The last column stays empty until you have been charged for a build. We would rather show nothing than divide by a number that isn't about you."}
            </p>

            <div className="mt-5 border-t border-hair pt-5">
              <TopUpButton packs={CREDIT_PACKS.map((p) => ({ id: p.id, label: p.label }))} />
            </div>
          </>
        ) : (
          // Stripe is not configured on this deployment. Everything else on this
          // page still works — the statement below is complete and unaffected.
          <div className="mt-4">
            <TopUpButton enabled={false} />
          </div>
        )}
      </Card>

      {/* ── The one real control over spend ─────────────────────────────── */}
      <div className="mt-4">
        <SpendCapPanel cap={cap.cap} spent={spent} />
      </div>

      {/* ── The statement ───────────────────────────────────────────────── */}
      <Card className="mt-4">
        <CardHeader
          title="Credit statement"
          description="Newest first. Every row is one entry in an append-only record — nothing here is ever edited or removed — and the balance column is your balance immediately after that entry."
        />

        {entries.length === 0 ? (
          <EmptyState
            className="mt-5"
            kind="empty"
            title="No credit activity yet"
            body="Nothing has been added to or taken from this account. Your welcome credits and every build you are charged for will appear here."
          />
        ) : (
          <div className="k-scroll-x mt-5 rounded-lg border border-hair">
            <table className="w-full min-w-xl text-left text-sm">
              <caption className="sr-only">
                Your credit entries, newest first, page {page} of {pageCount}
              </caption>
              <thead>
                <tr className="border-b border-hair">
                  <th scope="col" className="k-label px-4 py-2.5 font-semibold">
                    When (UTC)
                  </th>
                  <th scope="col" className="k-label px-4 py-2.5 font-semibold">
                    What for
                  </th>
                  <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
                    Change
                  </th>
                  <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
                    Balance
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-hair">
                {entries.map((entry) => {
                  const what = describeReason(entry.reason, entry.delta);
                  const build = entry.build;
                  const project = build?.project ?? null;
                  // Deleting a project cascades its builds away and sets
                  // CreditLedger.buildId to NULL — the charge row stays
                  // (lib/retention.ts, NEVER_PRUNED). Say so rather than
                  // leaving a charge with nothing attached to it.
                  const secondary =
                    project === null && entry.reason === "build"
                      ? "The site this was for has since been deleted."
                      : what.detail;
                  // Rule 4 of the anti-bill-shock contract, read back off the
                  // build itself. Stated in credits, never in dollars: costMicros
                  // is our model spend, and the point here is what the CUSTOMER
                  // did not pay, not what we did.
                  const repaired =
                    build != null &&
                    build.repairAttempts > 0 &&
                    build.costMicros > build.creditsCharged * MICROS_PER_CREDIT;

                  return (
                    <tr key={entry.id}>
                      <td className="k-num px-4 py-3 align-top whitespace-nowrap text-ink-2">
                        {formatDay(entry.createdAt)}
                        <span className="block text-xs text-ink-3">
                          {formatTime(entry.createdAt)}
                        </span>
                      </td>
                      <td className="px-4 py-3 align-top">
                        <span className="block break-words text-ink">{what.label}</span>
                        {project ? (
                          <Link
                            href={`/projects/${project.id}`}
                            className="k-focus mt-0.5 block rounded-sm text-xs break-words text-ink-2 hover:text-brand"
                          >
                            {project.name}
                          </Link>
                        ) : secondary ? (
                          <span className="mt-0.5 block text-xs break-words text-ink-3">
                            {secondary}
                          </span>
                        ) : null}
                        {repaired && (
                          <span className="mt-0.5 block text-xs break-words text-ok">
                            Needed a repair pass — you weren&apos;t charged for it.
                          </span>
                        )}
                      </td>
                      <td
                        className={`k-num px-4 py-3 text-right align-top font-medium whitespace-nowrap ${
                          entry.delta > 0
                            ? "text-ok"
                            : entry.delta < 0
                              ? "text-danger"
                              : "text-ink-3"
                        }`}
                      >
                        {signedCredits(entry.delta)}
                      </td>
                      <td className="k-num px-4 py-3 text-right align-top whitespace-nowrap text-ink-2">
                        {formatCredits(entry.balanceAfter)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {totalEntries > 0 && (
          <nav
            aria-label="Credit statement pages"
            className="mt-4 flex flex-wrap items-center justify-between gap-3"
          >
            <p className="text-xs text-ink-3">
              Showing <span className="k-num">{firstIndex}</span>–
              <span className="k-num">{lastIndex}</span> of{" "}
              <span className="k-num">{formatCredits(totalEntries)}</span>
            </p>
            <div className="flex items-center gap-2">
              <PageLink page={page - 1} disabled={page <= 1} rel="prev">
                ← Newer
              </PageLink>
              <PageLink page={page + 1} disabled={page >= pageCount} rel="next">
                Older →
              </PageLink>
            </div>
          </nav>
        )}

        <p className="mt-4 text-xs leading-relaxed text-ink-3">
          A build only reaches this statement if it succeeded and had measured model cost. A build
          that fails is recorded with its true cost and charged nothing, so it never appears here.
        </p>
      </Card>

      {/* ── What a build costs ──────────────────────────────────────────── */}
      <Card className="mt-4">
        <CardHeader
          title="What a build costs"
          description="Credits come off the model usage we actually metered, after a build succeeds — never a flat guess up front."
        />
        <p className="mt-4 text-sm leading-relaxed text-ink-2">
          If a build doesn&apos;t compile, Kodely repairs it and tries again, and the repair is
          free: you&apos;re charged for your original attempt only, exactly as if it had compiled
          first time.
        </p>

        <dl className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2">
          <RangeRow term="Building a new site" low={create.low} high={create.high} />
          <RangeRow term="Making an edit" low={edit.low} high={edit.high} />
        </dl>

        <p className="mt-4 text-xs leading-relaxed text-ink-3">
          Treat those as wide brackets, not predictions. They are drawn from only two builds we have
          measured end to end — <span className="k-num">144</span> credits and{" "}
          <span className="k-num">472</span> credits — which is a more-than-threefold spread
          and nowhere near enough to call a typical build. That is why there is no single figure
          here. Your own builds can land outside these brackets, and the numbers in your statement
          above are the only ones that are actually about you.
        </p>
      </Card>

      {/* ── The things a billing page usually has, and this one does not ── */}
      <div className="mt-4">
        <EmptyState
          kind="unavailable"
          title="There is no plan, invoice or saved card to show"
          body={
            <>
              Kodely has no subscription: no tier, no monthly price, no renewal date, and nothing
              to downgrade. Payments are single charges for credit packs, so there are no Stripe
              invoices to list, and your card details stay with Stripe — Kodely never reads them
              back and cannot display a last-four. The statement above is the complete record of
              money and credits on this account.
            </>
          }
        />
      </div>
    </>
  );
}

function RangeRow({ term, low, high }: { term: string; low: number; high: number }) {
  return (
    <div className="rounded-lg border border-hair bg-surface-2 p-4">
      <dt className="k-label">{term}</dt>
      <dd className="mt-2 text-sm text-ink">
        somewhere between <span className="k-num font-medium">{formatCredits(low)}</span> and{" "}
        <span className="k-num font-medium">{formatCredits(high)}</span> credits
      </dd>
    </div>
  );
}

function PageLink({
  page,
  disabled,
  rel,
  children,
}: {
  page: number;
  disabled: boolean;
  rel: "prev" | "next";
  children: ReactNode;
}) {
  if (disabled) {
    // A span, not a disabled link: there is nothing to navigate to, so there is
    // nothing that should take focus or be announced as a control.
    return (
      <span
        aria-hidden
        className={buttonClass({ variant: "ghost", size: "xs", className: "opacity-40" })}
      >
        {children}
      </span>
    );
  }

  return (
    <ButtonLink
      href={page <= 1 ? "/dashboard/billing" : `/dashboard/billing?page=${page}`}
      rel={rel}
      aria-label={rel === "prev" ? "Newer entries" : "Older entries"}
      variant="secondary"
      size="xs"
    >
      {children}
    </ButtonLink>
  );
}

