1	import { db } from "@/lib/db";
2	import { MICROS_PER_CREDIT } from "@/lib/credits";
3	
4	// Aggregations for /dashboard/usage. Everything here is derived from rows that
5	// already exist — CreditLedger and Build — with no schema change and no
6	// estimate. If a number cannot be computed from those two tables it is not in
7	// this file, and the page says so instead of inventing it.
8	//
9	// Deliberately absent, because nothing measures them: storage, bandwidth,
10	// request counts, seats, and anything resembling a plan allowance.
11	//
12	// COST BASIS IS NOT EXPOSED. Build.costMicros is our real model spend, which is
13	// the cost side of the retail prices in lib/stripe.ts. Every figure this module
14	// returns is in CREDITS; costMicros is only ever used inside an arithmetic
15	// comparison against what was charged, never returned as money.
16	
17	const MS_DAY = 24 * 60 * 60 * 1000;
18	
19	/** Epoch ms for the start of the UTC calendar day containing `d`. */
20	function utcDayStart(d: Date): number {
21	  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
22	}
23	
24	export type DayBucket = {
25	  /** Start of the UTC day, epoch ms. */
26	  ts: number;
27	  credits: number;
28	};
29	
30	/**
31	 * Credits spent per UTC calendar day over the last `days` days, today included.
32	 *
33	 * NOTE the deliberate mismatch with spentInWindow() in lib/credits.ts: that one
34	 * measures a rolling window to the millisecond because it is what the spend cap
35	 * enforces. A chart cannot have a half-day bucket at its left edge, so this
36	 * snaps to UTC day boundaries. The two totals can therefore differ by up to one
37	 * day's spend, and the page says so rather than presenting them as the same
38	 * number twice.
39	 *
40	 * Row count is bounded by one user's charges in 90 days, so bucketing in JS
41	 * beats a raw SQL date_trunc that would have to be written per-dialect.
42	 */
43	export async function dailySpend(userId: string, days: number): Promise<DayBucket[]> {
44	  const firstDay = utcDayStart(new Date()) - (days - 1) * MS_DAY;
45	
46	  const rows = await db.creditLedger.findMany({
47	    where: { userId, delta: { lt: 0 }, createdAt: { gte: new Date(firstDay) } },
48	    select: { createdAt: true, delta: true },
49	  });
50	
51	  const buckets: DayBucket[] = Array.from({ length: days }, (_, i) => ({
52	    ts: firstDay + i * MS_DAY,
53	    credits: 0,
54	  }));
55	
56	  for (const row of rows) {
57	    const index = Math.round((utcDayStart(row.createdAt) - firstDay) / MS_DAY);
58	    // Defensive: a DST-free UTC calculation should never land outside the
59	    // array, but a clock skew between Postgres and this process could. A bar
60	    // silently written past the end of the chart is worse than a dropped one.
61	    if (index >= 0 && index < days) {
62	      buckets[index].credits += Math.abs(row.delta);
63	    }
64	  }
65	
66	  return buckets;
67	}
68	
69	export type SpendBucket = {
70	  /** Start of the first UTC day in the group, epoch ms. */
71	  ts: number;
72	  /** How many UTC days this bar covers. 1 for a daily bar. */
73	  days: number;
74	  credits: number;
75	};
76	
77	/**
78	 * Collapse day buckets into fixed-width groups so a long range stays legible.
79	 * `size` of 1 is the identity, which is why every caller can go through here.
80	 *
81	 * Grouped from the NEWEST end on purpose. Grouping from the left leaves the
82	 * partial group at the right edge — the current, incomplete week — and a bar
83	 * covering three days next to bars covering seven reads as a collapse in usage
84	 * rather than as a shorter period. Anchoring to the newest day puts the short
85	 * group at the far left instead, where it is the oldest data and where the
86	 * label (which carries the real span) is read first.
87	 */
88	export function groupBuckets(buckets: DayBucket[], size: number): SpendBucket[] {
89	  if (size <= 1) return buckets.map((b) => ({ ts: b.ts, days: 1, credits: b.credits }));
90	
91	  const out: SpendBucket[] = [];
92	  for (let end = buckets.length; end > 0; end -= size) {
93	    const slice = buckets.slice(Math.max(0, end - size), end);
94	    out.unshift({
95	      ts: slice[0].ts,
96	      days: slice.length,
97	      credits: slice.reduce((sum, b) => sum + b.credits, 0),
98	    });
99	  }
100	  return out;
101	}
102	
103	/**
104	 * Whole UTC days from this account's first ledger entry to today, inclusive —
105	 * or null when there is no ledger at all. Drives the "All time" chart range,
106	 * which has to be a real span rather than an arbitrary large number of days.
107	 *
108	 * The first ledger row is the signup grant, so this is effectively account age.
109	 */
110	export async function accountSpanDays(userId: string): Promise<number | null> {
111	  const earliest = await db.creditLedger.findFirst({
112	    where: { userId },
113	    orderBy: { createdAt: "asc" },
114	    select: { createdAt: true },
115	  });
116	  if (earliest === null) return null;
117	  return Math.max(1, Math.round((utcDayStart(new Date()) - utcDayStart(earliest.createdAt)) / MS_DAY) + 1);
118	}
119	
120	// Must stay equal to CAP_WINDOW_DAYS in lib/credits.ts. The comparison below is
121	// against the window the spend cap actually enforces; a different length here
122	// would silently compare a 30-day figure to a 28-day one.
123	const WINDOW_DAYS = 30;
124	
125	export type SpendComparison = {
126	  /** Credits spent in the 30 days immediately BEFORE the current window. */
127	  previous: number;
128	  /**
129	   * False when this account did not exist for the whole of that earlier window,
130	   * in which case `previous` is not a period this person lived through and any
131	   * percentage drawn from it would be fiction. The page shows nothing at all
132	   * rather than a 0% that looks like a measurement.
133	   */
134	  comparable: boolean;
135	};
136	
137	export async function previousWindowSpend(userId: string): Promise<SpendComparison> {
138	  const now = Date.now();
139	  const windowStart = new Date(now - WINDOW_DAYS * MS_DAY);
140	  const priorStart = new Date(now - 2 * WINDOW_DAYS * MS_DAY);
141	
142	  const [earliest, prior] = await Promise.all([
143	    db.creditLedger.findFirst({
144	      where: { userId },
145	      orderBy: { createdAt: "asc" },
146	      select: { createdAt: true },
147	    }),
148	    db.creditLedger.aggregate({
149	      where: { userId, delta: { lt: 0 }, createdAt: { gte: priorStart, lt: windowStart } },
150	      _sum: { delta: true },
151	    }),
152	  ]);
153	
154	  return {
155	    previous: Math.abs(prior._sum.delta ?? 0),
156	    comparable: earliest !== null && earliest.createdAt.getTime() <= priorStart.getTime(),
157	  };
158	}
159	
160	export type MonthToDate = {
161	  /** First instant of the current UTC calendar month, epoch ms. */
162	  start: number;
163	  credits: number;
164	  builds: number;
165	  /** UTC days elapsed this month, today included. */
166	  daysElapsed: number;
167	};
168	
169	/**
170	 * This calendar month so far, in UTC.
171	 *
172	 * A CALENDAR COUNT AND NOTHING MORE. There is no monthly allowance, no billing
173	 * month and no reset on the 1st — credits never expire and the spend cap rolls
174	 * (docs/design-system.md). This exists because "how much have I built lately"
175	 * is a question people ask in months, not because anything in Kodely renews in
176	 * one, and the page has to say so where it is rendered.
177	 */
178	export async function monthToDate(userId: string): Promise<MonthToDate> {
179	  const now = new Date();
180	  const start = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1);
181	  const since = new Date(start);
182	
183	  const [spend, builds] = await Promise.all([
184	    db.creditLedger.aggregate({
185	      where: { userId, delta: { lt: 0 }, createdAt: { gte: since } },
186	      _sum: { delta: true },
187	    }),
188	    db.build.count({
189	      where: {
190	        project: { userId },
191	        status: "SUCCEEDED",
192	        creditsCharged: { gt: 0 },
193	        createdAt: { gte: since },
194	      },
195	    }),
196	  ]);
197	
198	  return {
199	    start,
200	    credits: Math.abs(spend._sum.delta ?? 0),
201	    builds,
202	    daysElapsed: now.getUTCDate(),
203	  };
204	}
205	
206	export type SiteUsage = {
207	  projectId: string;
208	  name: string;
209	  credits: number;
210	  builds: number;
211	  lastAt: Date;
212	};
213	
214	/**
215	 * Credits charged, grouped by the website they were charged for.
216	 *
217	 * Attribution is real, not inferred: CreditLedger.buildId -> Build.projectId.
218	 * This groups the Build side because it also carries the build count and the
219	 * last-charged date, which the ledger alone does not.
220	 *
221	 * IT CANNOT SEE DELETED SITES. Project deletion cascades its builds away and
222	 * SET NULLs CreditLedger.buildId (prisma/schema.prisma), so the charge survives
223	 * on the statement with nothing attached. The caller reconciles this total
224	 * against the ledger and shows the difference explicitly — see the page.
225	 */
226	export async function siteUsage(userId: string): Promise<SiteUsage[]> {
227	  const grouped = await db.build.groupBy({
228	    by: ["projectId"],
229	    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
230	    _sum: { creditsCharged: true },
231	    _count: true,
232	    _max: { createdAt: true },
233	  });
234	
235	  if (grouped.length === 0) return [];
236	
237	  const projects = await db.project.findMany({
238	    where: { id: { in: grouped.map((g) => g.projectId) }, userId },
239	    select: { id: true, name: true },
240	  });
241	  const nameById = new Map(projects.map((p) => [p.id, p.name]));
242	
243	  const rows: SiteUsage[] = [];
244	  for (const g of grouped) {
245	    const name = nameById.get(g.projectId);
246	    const lastAt = g._max.createdAt;
247	    // A group with no matching project, or no date, means the read raced a
248	    // delete. Drop it rather than rendering a row with a placeholder name — the
249	    // reconciliation below folds it into the deleted-sites total instead, which
250	    // is where it honestly belongs.
251	    if (name === undefined || lastAt === null) continue;
252	    rows.push({
253	      projectId: g.projectId,
254	      name,
255	      credits: g._sum.creditsCharged ?? 0,
256	      builds: g._count,
257	      lastAt,
258	    });
259	  }
260	
261	  return rows.sort((a, b) => b.credits - a.credits || a.name.localeCompare(b.name));
262	}
263	
264	export type NotCharged = {
265	  failedBuilds: number;
266	  repairedBuilds: number;
267	  /** Credits the repair rule absorbed. Conservative — see below. */
268	  repairWaivedCredits: number;
269	};
270	
271	/**
272	 * The two things Kodely records but never bills: failed builds and repair
273	 * passes. Both are rules 3 and 4 of the contract in lib/credits.ts, restated as
274	 * arithmetic on this user's own rows.
275	 *
276	 * The waived figure is DERIVED, exactly as lib/credits.ts says it can be:
277	 * repairAttempts > 0 together with costMicros > creditsCharged * MICROS_PER_CREDIT
278	 * is "this run was repaired and we absorbed the difference".
279	 *
280	 * It understates on purpose. creditsCharged is rounded UP from the billable
281	 * attempt, so charging-side micros are overstated and the derived difference
282	 * comes out low. On a page whose entire point is not overclaiming, a saving
283	 * quoted slightly under the truth is the only acceptable rounding direction.
284	 */
285	export async function notCharged(userId: string): Promise<NotCharged> {
286	  const [failedBuilds, repaired] = await Promise.all([
287	    db.build.count({ where: { project: { userId }, status: "FAILED" } }),
288	    db.build.aggregate({
289	      where: { project: { userId }, status: "SUCCEEDED", repairAttempts: { gt: 0 } },
290	      _count: true,
291	      _sum: { costMicros: true, creditsCharged: true },
292	    }),
293	  ]);
294	
295	  const trueMicros = repaired._sum.costMicros ?? 0;
296	  const chargedMicros = (repaired._sum.creditsCharged ?? 0) * MICROS_PER_CREDIT;
297	
298	  return {
299	    failedBuilds,
300	    repairedBuilds: repaired._count,
301	    repairWaivedCredits: Math.max(0, Math.floor((trueMicros - chargedMicros) / MICROS_PER_CREDIT)),
302	  };
303	}
304	
305	export type LedgerTotals = {
306	  /** Every positive delta: the signup grant, paid top-ups, social rewards. */
307	  added: number;
308	  /** Every negative delta. Today only chargeForBuild writes one. */
309	  spent: number;
