import type { Metadata } from "next";
import type { ReactNode } from "react";
import Link from "next/link";
import { redirect } from "next/navigation";
import {
  ArrowDownRight,
  ArrowUpRight,
  Code2,
  Eye,
  Gauge,
  Hammer,
  HelpCircle,
  History,
  PartyPopper,
  Receipt,
  Rocket,
  ShieldCheck,
  Sparkles,
  UploadCloud,
  Wrench,
  XCircle,
  Zap,
} from "lucide-react";
import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { billingEnabled } from "@/lib/stripe";
import { getSpendCapStatus, averageBuildCredits, getBalance, spentInWindow } from "@/lib/credits";
import { Button, ButtonLink } from "@/components/ui/Button";
import { Card, CardHeader, SectionHeader } from "@/components/ui/Card";
import { EmptyState } from "@/components/ui/EmptyState";
import { InfoPopover } from "@/components/ui/InfoPopover";
import { Progress } from "@/components/ui/Progress";
import { Stat } from "@/components/ui/Stat";
import { SpendCapPanel } from "../billing/SpendCapPanel";
import { formatCredits, formatDay } from "../billing/ledger";
import { ActivityTable } from "./ActivityTable";
import {
  accountSpanDays,
  dailySpend,
  groupBuckets,
  ledgerTotals,
  monthToDate,
  mtdBuildKind,
  notCharged,
  previousWindowSpend,
  recentActivity,
  siteUsage,
} from "./data";
import { RangeTabs } from "./RangeTabs";
import type { RangeKey } from "./RangeTabs";
import { SpendKindDonut } from "./SpendKindDonut";
import { UsageChart } from "./UsageChart";

export const dynamic = "force-dynamic";

// The "— Kodely" suffix comes from the title template on the (portal) layout.
export const metadata: Metadata = { title: "Usage" };

/* /dashboard/usage — what the credits went ON.
   ───────────────────────────────────────────────────────────────────────────
   The brief for this screen has, twice now, asked for things that do not
   exist on this account: a monthly allowance with a reset date, a donut
   attributing spend to failed builds, workspace/team invites, custom domains
   as a free Kodely feature, and usage-alert toggles. None of the five are
   drawn here — see the note beside each below — because a dashboard that
   shows a customer something untrue about their own bill is a worse dashboard
   than a plainer one that doesn't.

   Every figure on this page is in CREDITS. Build.costMicros is real model
   spend — the cost side of the retail prices in lib/stripe.ts — and it is
   used only inside the arithmetic in ./data.ts, never rendered as money.

   THE FIVE SUBSTITUTIONS:
     1. No monthly allowance / reset date. The gradient card shows the
        customer's own SPEND CAP when one is set (real ceiling, real rolling
        window) and a plain sentence when it isn't.
     2. No donut over successful/failed/other builds — a failed build is
        charged zero (chargeForBuild is only reached on the SUCCEEDED path in
        app/api/generate/route.ts), so that shape would be one 100% slice and
        two empty ones. SpendKindDonut draws each project's first charged
        build ("new sites") against every build after it ("edits") instead —
        a genuine category recovered from data that already exists.
     3. No usage-alert toggles ("80% alert: On"). There is no notification
        system behind them — lib/notifications sends four fixed transactional
        emails and nothing configurable. The Spending Cap card offers the one
        control that is real: the cap itself.
     4. No "Team invites" / "Custom domains" as free features — there is no
        workspace concept in the product, and connecting your own domain is a
        separate paid Nxeon product, not a free Kodely one. The six tiles
        below are things that are actually free.
     5. No "Upgrade plan" button — there is no subscription to upgrade. The
        bottom CTA offers "Buy credits" only, and only when Stripe is
        configured on this deployment.
   A "you're spending less!" banner only renders when it's true (`spendingLess`
   below) — praising an increase would be worse than no banner. */

// Closed range table, looked up with hasOwnProperty so a query string of
// "constructor" or "__proto__" resolves to a miss rather than to something on
// Object.prototype.
const RANGES: Record<string, true> = { "30": true, "90": true, all: true };
const FIXED_DAYS: Record<string, number> = { "30": 30, "90": 90 };
const DEFAULT_RANGE: RangeKey = "30";

// Above this many days a daily bar is thinner than the gap beside it, so the
// chart groups into weeks instead. See groupBuckets in ./data.ts.
const WEEKLY_ABOVE_DAYS = 120;

const MONTH = new Intl.DateTimeFormat("en-GB", {
  month: "long",
  year: "numeric",
  timeZone: "UTC",
});

function pickRange(params: Record<string, string | string[] | undefined>): RangeKey {
  const raw = Object.prototype.hasOwnProperty.call(params, "range") ? params.range : undefined;
  // `?range=30&range=90` arrives as an array; there is no sane single answer to
  // that, so it falls through to the default rather than picking one at random.
  const key = typeof raw === "string" ? raw : DEFAULT_RANGE;
  if (Object.prototype.hasOwnProperty.call(RANGES, key)) return key as RangeKey;
  return DEFAULT_RANGE;
}

export default async function UsagePage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const rangeKey = pickRange(await searchParams);

  const [cap, span] = await Promise.all([
    getSpendCapStatus(user.id),
    // "All time" has to be a real span, not an arbitrary large number of days.
    accountSpanDays(user.id),
  ]);

  // A null span means no ledger rows at all, which should not happen (the
  // signup grant writes one) but is not worth crashing over: fall back to the
  // default window and label it as such.
  const days =
    rangeKey === "all" ? Math.max(1, span ?? FIXED_DAYS[DEFAULT_RANGE]) : FIXED_DAYS[rangeKey];
  const rangeLabel =
    rangeKey === "all" && span !== null
      ? `the ${formatCredits(span)} days since your account opened`
      : `the last ${formatCredits(days)} days`;

  const [
    balance,
    spent,
    avgBuildCredits,
    measuredBuilds,
    sites,
    totals,
    waived,
    dayBuckets,
    trend,
    mtd,
    mtdKind,
    activity,
  ] = await Promise.all([
    getBalance(user.id),
    // getSpendCapStatus skips the spend query when the user is uncapped; this
    // page needs the figure either way, and it must be the same query the cap
    // enforces so the two can't disagree.
    cap.cap === null ? spentInWindow(user.id) : Promise.resolve(cap.spent),
    averageBuildCredits(user.id),
    // averageBuildCredits falls back to a global constant when there is no
    // history. That constant is a fine default for "builds remaining" — the
    // rail and the /support card both use it that way — but it is NOT a
    // measurement of this person, so any tile claiming to describe THEIR builds
    // waits for this count.
    db.build.count({
      where: { project: { userId: user.id }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
    }),
    siteUsage(user.id),
    ledgerTotals(user.id),
    notCharged(user.id),
    dailySpend(user.id, days),
    previousWindowSpend(user.id),
    monthToDate(user.id),
    mtdBuildKind(user.id),
    recentActivity(user.id, 6),
  ]);

  const buckets = groupBuckets(dayBuckets, days > WEEKLY_ABOVE_DAYS ? 7 : 1);

  const attributed = sites.reduce((sum, s) => sum + s.credits, 0);
  // Deleting a project cascades its builds away and SET NULLs the ledger's
  // buildId, so the charge outlives the thing it was for. That gap is real and
  // is shown as its own row rather than quietly rounding the percentages.
  const orphaned = Math.max(0, totals.spent - attributed);
  const largest = Math.max(attributed > 0 ? sites[0].credits : 0, orphaned, 1);
  // A real 1-credit site rounding to a flat "0%" reads as "this cost nothing",
  // which is the one thing it definitely did not do.
  const share = (credits: number) => {
    if (totals.spent <= 0 || credits <= 0) return "0%";
    const pct = (credits / totals.spent) * 100;
    return pct < 1 ? "<1%" : `${Math.round(pct)}%`;
  };

  // The same arithmetic the sidebar rail and the /support card do, so all three
  // answer "how much more can I build?" with the same number. No denominator is
  // invented anywhere: there is no allowance for the balance to be a fraction
  // of, which is exactly why none of the three draws a bar tied to it.
  const buildsLeft = avgBuildCredits > 0 ? Math.floor(balance / avgBuildCredits) : 0;

  // Only computed when the account lived through the whole earlier window, and
  // only expressed as a percentage when there is a non-zero base to divide by.
  const delta =
    trend.comparable && trend.previous > 0
      ? Math.round(((spent - trend.previous) / trend.previous) * 100)
      : null;

  // A congratulatory banner, ONLY when there is something real to congratulate.
  // Below a token threshold the change is noise, not a trend, so nothing is
  // shown rather than praising a 1% wobble.
  const spendingLess = delta !== null && delta <= -5;

  // Three real states for the hero card. "Low" mirrors the create-flow's own
  // definition of tight (Composer.tsx): can't be sure of covering one more
  // average build. Both thresholds are about THIS account's own numbers, not
  // an arbitrary credit count.
  const zero = balance <= 0;
  const low = !zero && measuredBuilds > 0 && balance < avgBuildCredits;

  const canBuyCredits = billingEnabled();
  const hasAnyUsage = totals.spent > 0 || activity.length > 0;

  return (
    <>
      <SectionHeader
        as="h1"
        title="Usage & Credits"
        description="Track your AI usage, build activity, and remaining credits."
        action={
          <div className="flex items-center gap-2">
            <ButtonLink href="/dashboard/billing" variant="secondary" size="sm">
              Billing &amp; statements
            </ButtonLink>
            <InfoPopover label="About this page" align="end">
              This page reads directly from your credit ledger and build history — every figure is
              real, nothing here is a projection or an estimate framed as a fact.
            </InfoPopover>
          </div>
        }
      />

      {/* ── Where you stand ─────────────────────────────────────────────── */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-5">
        <HeroCreditsCard
          balance={balance}
          buildsLeft={buildsLeft}
          measuredBuilds={measuredBuilds}
          avgBuildCredits={avgBuildCredits}
          cap={cap.cap}
          spent={spent}
          zero={zero}
          low={low}
          canBuyCredits={canBuyCredits}
        />

        <StatTile
          icon={<Receipt className="size-4" aria-hidden />}
          label="Credits spent"
          value={formatCredits(spent)}
          unit="credits"
          detail={
            <>
              {delta !== null && (
                <span className="mb-1 flex items-center gap-1 font-medium text-ink-2">
                  {delta >= 0 ? (
                    <ArrowUpRight className="size-3.5 shrink-0" aria-hidden />
                  ) : (
                    <ArrowDownRight className="size-3.5 shrink-0" aria-hidden />
                  )}
                  <span className="k-num">{Math.abs(delta)}%</span>
                  <span>vs the 30 days before</span>
                </span>
              )}
              Rolling 30 days, not a calendar month. There is no reset day.
              {delta === null && trend.comparable && trend.previous === 0
                ? " Nothing was spent in the 30 days before this one, so there is no change to quote."
                : ""}
            </>
          }
        />

        <StatTile
          icon={<Gauge className="size-4" aria-hidden />}
          label="Your average build"
          value={measuredBuilds > 0 ? formatCredits(avgBuildCredits) : "—"}
          unit={measuredBuilds > 0 ? "credits" : undefined}
          detail={
            measuredBuilds > 0
              ? `Per successful build — ${formatCredits(measuredBuilds)} charged so far.`
              : "Nothing measured yet. You haven't been charged for a build."
          }
        />

        <StatTile
          icon={<Hammer className="size-4" aria-hidden />}
          label="Builds this month"
          value={formatCredits(mtd.builds)}
          unit={mtd.builds === 1 ? "build" : "builds"}
          detail={`Since 1 ${MONTH.format(new Date(mtd.start))} (UTC) — a calendar count for orientation, nothing resets on the 1st.`}
        />

        <StatTile
          icon={<Rocket className="size-4" aria-hidden />}
          label="Builds you can afford"
          value={formatCredits(buildsLeft)}
          unit="more"
          info={
            <InfoPopover label="How this is calculated">
              Your credit balance divided by{" "}
              {measuredBuilds > 0 ? "your own measured average build cost" : "a typical Kodely build cost"}
              , rounded down. A bigger or more complex site costs more than a smaller one, so treat
              this as a rough guide, not a guarantee.
            </InfoPopover>
          }
          detail={
            measuredBuilds > 0
              ? "At your own measured average."
              : "Based on a typical Kodely build — you haven't had one charged yet."
          }
        />
      </div>

      {/* ── How Kodely credits work — one line, the rest behind a click ──── */}
      <Card className="mt-4 flex flex-wrap items-center justify-between gap-3 py-3.5">
        <p className="flex items-center gap-2.5 text-sm text-ink-2">
          <Sparkles className="size-4 shrink-0 text-brand" aria-hidden />
          <span>
            <span className="font-medium text-ink">How Kodely credits work:</span> credits are spent
            when the AI generates or significantly changes your site. Previews, manual edits and
            publishing are free.
          </span>
        </p>
        <CreditsExplainer />
      </Card>

      {!hasAnyUsage ? (
        <EmptyState
          className="mt-4"
          kind="empty"
          title="Your usage will appear here"
          body="Once you build or update a website with Kodely AI, your credit activity, charts and breakdowns fill in on their own."
          action={
            <ButtonLink href="/dashboard/new" variant="primary" size="sm">
              Create a website
            </ButtonLink>
          }
        />
      ) : (
        <>
          {/* ── Credits over time + Usage this month ─────────────────────── */}
          <div className="mt-4 grid grid-cols-1 items-start gap-4 lg:grid-cols-3">
            <Card className="lg:col-span-2">
              <CardHeader
                title="Credits over time"
                description="Daily AI credits spent (UTC)."
                action={<RangeTabs value={rangeKey} allLabel={span === null ? "All time" : "All time"} />}
              />

              <UsageChart buckets={buckets} days={days} rangeLabel={rangeLabel} />

              <p className="mt-4 text-xs leading-relaxed text-ink-3">
                Only successful, metered builds are charged, so only those appear. These bars are
                UTC calendar {days > WEEKLY_ABOVE_DAYS ? "weeks" : "days"}; the rolling 30-day
                figure above can differ from a sum of these bars by up to one{" "}
                {days > WEEKLY_ABOVE_DAYS ? "week" : "day"}&apos;s spend — neither is an estimate,
                they're just measured over different windows.
              </p>

              {spendingLess && (
                <div className="mt-4 flex flex-wrap items-center gap-2.5 rounded-lg border border-ok/30 bg-ok-tint px-4 py-3">
                  <Sparkles className="size-4 shrink-0 text-ok" aria-hidden />
                  <p className="text-sm text-ok">
                    You spent <span className="k-num font-medium">{Math.abs(delta ?? 0)}%</span>{" "}
                    less than the 30 days before this one.
                  </p>
                </div>
              )}
            </Card>

            <Card>
              <CardHeader
                title="Usage this month"
                description={`1–${mtd.daysElapsed} ${MONTH.format(new Date(mtd.start))}, UTC.`}
              />
              <div className="mt-5">
                <SpendKindDonut createCredits={mtdKind.createCredits} editCredits={mtdKind.editCredits} />
              </div>
              <p className="mt-4 text-xs leading-relaxed text-ink-3">
                A month boundary is a convenient way to read this and nothing more — credits never
                expire and there is no monthly allowance behind them.
              </p>
            </Card>
          </div>

          {/* ── Recent activity + Spending cap ───────────────────────────── */}
          <div className="mt-4 grid grid-cols-1 items-start gap-4 lg:grid-cols-3">
            <Card className="lg:col-span-2">
              <CardHeader
                title="Recent credit activity"
                description="Your newest charges and credits."
              />
              <div className="mt-4">
                <ActivityTable rows={activity} />
              </div>
            </Card>

            <SpendCapPanel cap={cap.cap} spent={spent} />
          </div>

          {/* ── Per-website attribution ───────────────────────────────────── */}
          <Card className="mt-4">
            <CardHeader
              title="Where your credits went"
              description="See which websites are using the most AI credits."
            />

            {sites.length === 0 && orphaned === 0 ? (
              <EmptyState
                className="mt-5"
                kind="empty"
                title="Nothing charged yet"
                body="You haven't been charged for a build, so there is nothing to break down."
              />
            ) : (
              <>
                <ul className="mt-5 flex flex-col gap-4">
                  {sites.map((site) => (
                    <SiteRow
                      key={site.projectId}
                      name={
                        <Link
                          href={`/projects/${site.projectId}`}
                          className="k-focus rounded-sm font-medium break-words text-ink hover:text-brand"
                        >
                          {site.name}
                        </Link>
                      }
                      credits={site.credits}
                      max={largest}
                      share={share(site.credits)}
                      tone="brand"
                      barLabel={`${site.name}: ${formatCredits(site.credits)} credits`}
                      footnote={
                        <>
                          <span className="k-num">{formatCredits(site.builds)}</span>{" "}
                          {site.builds === 1 ? "build" : "builds"} · last charged{" "}
                          <span className="k-num">{formatDay(site.lastAt)}</span>
                        </>
                      }
                    />
                  ))}

                  {orphaned > 0 && (
                    <SiteRow
                      name={
                        <span className="font-medium break-words text-ink-2">
                          Websites you&apos;ve deleted
                        </span>
                      }
                      credits={orphaned}
                      max={largest}
                      share={share(orphaned)}
                      tone="neutral"
                      barLabel={`Deleted websites: ${formatCredits(orphaned)} credits`}
                      footnote="Their build records are gone, so these charges can no longer be pointed at a site — but the credits really were spent, so they stay on your statement."
                    />
                  )}
                </ul>

                <div className="mt-4 flex flex-wrap items-center justify-between gap-3">
                  <p className="text-xs leading-relaxed text-ink-3">
                    Shares are of <span className="k-num">{formatCredits(totals.spent)}</span>{" "}
                    credits spent in total, against{" "}
                    <span className="k-num">{formatCredits(totals.added)}</span> ever added.
                  </p>
                  <Link
                    href="/dashboard/websites"
                    className="k-focus shrink-0 rounded-sm text-xs font-medium text-brand hover:underline"
                  >
                    View all projects →
                  </Link>
                </div>
              </>
            )}
          </Card>

          {/* ── Build reliability ─────────────────────────────────────────── */}
          <section className="mt-6">
            <SectionHeader
              title="Build reliability"
              description="What happens when a build doesn't go right the first time — and what it costs you."
            />
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
              <ReliabilityTile
                icon={<XCircle className="size-4" aria-hidden />}
                label="Failed builds"
                value={formatCredits(waived.failedBuilds)}
                reassuring={waived.failedBuilds === 0}
                reassuringText="No failed builds recently"
                detail="Recorded at their true cost, charged zero credits. A build you can't use is never a build you pay for."
              />
              <ReliabilityTile
                icon={<Wrench className="size-4" aria-hidden />}
                label="Repaired builds"
                value={formatCredits(waived.repairedBuilds)}
                reassuring={waived.repairedBuilds === 0}
                reassuringText="No repairs needed recently"
                detail="Didn't compile first time. You're charged for your original attempt only — the repair pass is on us."
              />
              <ReliabilityTile
                icon={<ShieldCheck className="size-4" aria-hidden />}
                label="Credits charged for failed builds"
                value="0"
                reassuring
                reassuringText="Always zero — by design"
                detail={`${formatCredits(waived.repairWaivedCredits)} credits absorbed on repairs so far, rounded down from what they actually cost.`}
              />
            </div>
          </section>
        </>
      )}

      {/* ── Included at no additional credit cost ───────────────────────── */}
      <section className="mt-6">
        <SectionHeader
          title="Included at no additional credit cost"
          description="These actions don't consume AI credits."
        />
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
          <WaivedTile
            icon={<Code2 className="size-4" aria-hidden />}
            label="Manual editing"
            detail="Brand, SEO, anything you change by hand in the editor — never touches your credit balance."
          />
          <WaivedTile
            icon={<Eye className="size-4" aria-hidden />}
            label="Previewing websites"
            detail="The live preview in the builder runs as often as you like, before you publish anything."
          />
          <WaivedTile
            icon={<UploadCloud className="size-4" aria-hidden />}
            label="Publishing"
            detail="Going live is a separate action from asking the AI to build — it never charges credits on its own."
          />
          <WaivedTile
            icon={<History className="size-4" aria-hidden />}
            label="Version history"
            detail="Viewing or restoring an earlier build costs nothing — undo is not a second build."
          />
          <WaivedTile
            icon={<XCircle className="size-4" aria-hidden />}
            label="Builds that fail"
            detail="Recorded at their true cost and charged zero credits, always."
          />
          <WaivedTile
            icon={<Wrench className="size-4" aria-hidden />}
            label="Compile repairs"
            detail="If a build doesn't compile, the fix that follows is on us — you're charged once."
          />
        </div>
      </section>

      {/* ── What uses credits? ──────────────────────────────────────────── */}
      <section className="mt-6">
        <SectionHeader title="What uses credits?" />
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <Card>
            <p className="k-label text-danger">Uses credits</p>
            <ul className="mt-3 flex flex-col gap-2 text-sm text-ink-2">
              <li>• Building a new website from a prompt</li>
              <li>• Asking Kodely to redesign or restructure a page</li>
              <li>• Any AI-generated change to your site&apos;s files</li>
            </ul>
          </Card>
          <Card>
            <p className="k-label text-ok">Usually free</p>
            <ul className="mt-3 flex flex-col gap-2 text-sm text-ink-2">
              <li>• Previewing your site</li>
              <li>• Manual edits — brand, SEO, code</li>
              <li>• Publishing and browsing your dashboard</li>
            </ul>
          </Card>
        </div>
      </section>

      {/* ── Say plainly what is not measured ────────────────────────────── */}
      <Card className="mt-6 flex items-start gap-3 py-3.5">
        <HelpCircle className="mt-0.5 size-4 shrink-0 text-ink-3" aria-hidden />
        <div>
          <p className="text-sm font-medium text-ink">Storage & bandwidth</p>
          <p className="mt-0.5 text-xs leading-relaxed text-ink-3">
            Kodely doesn&apos;t currently meter storage or bandwidth usage — there is no honest
            number to show here yet, and there is no plan or allowance behind credits either.
          </p>
        </div>
      </Card>

      {/* ── Buy credits — no "Upgrade plan": there is no plan ───────────── */}
      {canBuyCredits && (
        <Card className="relative mt-6 overflow-hidden">
          <div className="k-wash" aria-hidden />
          <div className="relative flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="k-h2 text-ink">Need more credits?</p>
              <p className="mt-1 text-sm text-ink-2">
                Buy a credit pack to keep building — a single payment, nothing subscribes.
              </p>
            </div>
            <ButtonLink href="/dashboard/billing" variant="primary" icon={<Zap className="size-4" aria-hidden />}>
              Buy credits
            </ButtonLink>
          </div>
        </Card>
      )}
    </>
  );
}

/** The gradient hero card. Three real states: normal, low (can't be sure of
    covering one more average build), and zero. Low/zero use warm/danger
    TINTS rather than the brand gradient — that gradient means "things are
    fine" everywhere else it appears (the sidebar, /support), and reusing it
    for a warning would blur that meaning right when clarity matters most. */
function HeroCreditsCard({
  balance,
  buildsLeft,
  measuredBuilds,
  avgBuildCredits,
  cap,
  spent,
  zero,
  low,
  canBuyCredits,
}: {
  balance: number;
  buildsLeft: number;
  measuredBuilds: number;
  avgBuildCredits: number;
  cap: number | null;
  spent: number;
  zero: boolean;
  low: boolean;
  canBuyCredits: boolean;
}) {
  const warn = zero || low;
  return (
    <div
      className={
        warn
          ? "relative overflow-hidden rounded-xl border p-5 shadow-e2 " +
            (zero ? "border-danger/30 bg-danger-tint" : "border-warn/30 bg-warn-tint")
          : "btn-cta-gradient relative overflow-hidden rounded-xl p-5 text-white shadow-e2"
      }
    >
      <div className="flex items-start justify-between gap-2">
        <p
          className={
            "text-[0.6875rem] leading-none font-semibold tracking-[0.07em] uppercase " +
            (warn ? (zero ? "text-danger" : "text-warn") : "opacity-80")
          }
        >
          {zero ? "Out of credits" : low ? "Running low" : "Credits left"}
        </p>
        <Zap className={`size-4 shrink-0 ${warn ? (zero ? "text-danger" : "text-warn") : "opacity-80"}`} aria-hidden />
      </div>
      <p className="mt-3 flex items-baseline gap-1.5">
        <span
          className={`k-num text-2xl leading-none font-semibold tracking-tight ${warn ? "text-ink" : ""}`}
        >
          {formatCredits(balance)}
        </span>
        <span className={`text-[0.8125rem] ${warn ? "text-ink-2" : "opacity-90"}`}>credits</span>
      </p>
      <p className={`mt-2 text-xs leading-relaxed ${warn ? "text-ink-2" : "opacity-95"}`}>
        {zero
          ? "The next build won't start until you add credits."
          : low
            ? "You may not have enough for another full build."
            : buildsLeft >= 1
              ? `About ${formatCredits(buildsLeft)} more ${buildsLeft === 1 ? "build" : "builds"}.`
              : "Not quite enough for a full build."}
      </p>
      <p className={`mt-1.5 text-[0.6875rem] leading-relaxed ${warn ? "text-ink-3" : "opacity-85"}`}>
        {measuredBuilds > 0
          ? `Measured from your own builds, averaging ${formatCredits(avgBuildCredits)} credits each.`
          : `Based on a typical build, about ${formatCredits(avgBuildCredits)} credits.`}{" "}
        Credits never expire and nothing renews.
      </p>

      {/* A bar in this slot ONLY when there is something real for it to
          measure — the customer's own spend cap, if they've set one. */}
      {cap !== null ? (
        <div className={`mt-3 border-t pt-3 ${warn ? "border-line-mid" : "border-white/20"}`}>
          <div className={`flex items-baseline justify-between text-[0.6875rem] ${warn ? "text-ink-2" : "opacity-90"}`}>
            <span>Your spend cap</span>
            <span className="k-num">
              {formatCredits(spent)} / {formatCredits(cap)}
            </span>
          </div>
          <div className={`mt-1.5 h-1.5 overflow-hidden rounded-full ${warn ? "bg-surface-3" : "bg-white/25"}`}>
            <div
              className={`h-full rounded-full transition-[width] duration-[var(--t-3)] ${warn ? "bg-ink-2" : "bg-white"}`}
              style={{ width: `${Math.min(100, (spent / cap) * 100)}%` }}
            />
          </div>
          <p className={`mt-1.5 text-[0.625rem] ${warn ? "text-ink-3" : "opacity-80"}`}>
            Rolling 30 days, not a monthly reset —{" "}
            <a href="/settings/credits" className="underline underline-offset-2">
              edit your cap
            </a>
            .
          </p>
        </div>
      ) : (
        <p className={`mt-3 border-t pt-3 text-[0.625rem] leading-relaxed ${warn ? "border-line-mid text-ink-3" : "border-white/20 opacity-80"}`}>
          No spend cap set —{" "}
          <a href="/settings/credits" className="underline underline-offset-2">
            add one
          </a>{" "}
          to put a ceiling on a long session.
        </p>
      )}

      {warn && canBuyCredits && (
        <div className="mt-3">
          <ButtonLink href="/dashboard/billing" variant={zero ? "danger" : "secondary"} size="xs">
            Buy credits
          </ButtonLink>
        </div>
      )}
    </div>
  );
}

/** "Learn how credits work" as a popover, not a link to a page. The written
    explainer (content/seo/how-kodely-credits-work.json) exists as a file but
    has not been seeded into the live blog — linking to it would be a dead
    link the moment this ships. A popover needs nothing to be true except the
    text itself. */
function CreditsExplainer() {
  return (
    <InfoPopover label="Learn how credits work" align="end">
      <p className="font-medium text-ink">How credits work</p>
      <p className="mt-1.5">
        A credit is spent only when a build succeeds and Kodely actually generated or changed
        files. A build that fails costs nothing. A compile repair after a failed build is on us —
        you&apos;re charged for your original attempt only.
      </p>
      <p className="mt-1.5">
        Previewing, manual edits (brand, SEO, code) and publishing never touch your balance.
        Credits are bought in packs and never expire — there is no monthly allowance to run out
        of, only the balance you&apos;ve bought or been given.
      </p>
    </InfoPopover>
  );
}

/** One of the plain stat cards in the top row. `info`, when given, is an
    InfoPopover — used only where the number needs a sentence of method
    explained, so it doesn't have to live in the card body permanently. */
function StatTile({
  icon,
  label,
  value,
  unit,
  detail,
  info,
}: {
  icon: ReactNode;
  label: string;
  value: string;
  unit?: string;
  detail: ReactNode;
  info?: ReactNode;
}) {
  return (
    <Card className="flex flex-col">
      <div className="mb-4 flex items-center justify-between">
        <span
          aria-hidden
          className="grid size-8 shrink-0 place-items-center rounded-md bg-brand-tint text-brand-ink dark:text-brand"
        >
          {icon}
        </span>
        {info}
      </div>
      <Stat label={label} value={value} unit={unit} detail={detail} />
    </Card>
  );
}

/** One tile in "Included at no additional credit cost" — a fact, not a
    number, since every one of these is simply free rather than "free so far". */
function WaivedTile({ icon, label, detail }: { icon: ReactNode; label: string; detail: ReactNode }) {
  return (
    <Card className="flex items-start gap-3">
      <span aria-hidden className="grid size-9 shrink-0 place-items-center rounded-md bg-ok-tint text-ok">
        {icon}
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium text-ink">{label}</p>
        <p className="mt-1 text-xs leading-relaxed text-ink-3">{detail}</p>
      </div>
    </Card>
  );
}

/** A build-reliability stat. `reassuring` swaps the icon chip to a calm green
    tone and, when the value is exactly zero, swaps the headline number for a
    short reassuring sentence instead of a bare "0" — a zero on a reliability
    metric is good news and should read like it. */
function ReliabilityTile({
  icon,
  label,
  value,
  reassuring,
  reassuringText,
  detail,
}: {
  icon: ReactNode;
  label: string;
  value: string;
  reassuring: boolean;
  reassuringText: string;
  detail: ReactNode;
}) {
  return (
    <Card className="flex flex-col">
      <span
        aria-hidden
        className={`mb-4 grid size-8 shrink-0 place-items-center rounded-md ${
          reassuring ? "bg-ok-tint text-ok" : "bg-surface-2 text-ink-2"
        }`}
      >
        {icon}
      </span>
      <span className="k-label">{label}</span>
      {reassuring ? (
        <span className="mt-2 flex items-center gap-1.5 text-lg leading-none font-semibold text-ok">
          <PartyPopper className="size-4 shrink-0" aria-hidden />
          {reassuringText}
        </span>
      ) : (
        <span className="k-num mt-2 text-2xl leading-none font-semibold tracking-tight text-ink">
          {value}
        </span>
      )}
      <p className="mt-2 text-xs leading-relaxed text-ink-3">{detail}</p>
    </Card>
  );
}

/** One website's share of spend: the figure, a bar against the largest single
    line, and the percentage of everything ever spent. Rows rather than a table
    because this column is a third of the page wide — a five-column table here
    would scroll sideways inside its own box on every screen. */
function SiteRow({
  name,
  credits,
  max,
  share,
  tone,
  barLabel,
  footnote,
}: {
  name: ReactNode;
  credits: number;
  max: number;
  share: string;
  tone: "brand" | "neutral";
  barLabel: string;
  footnote: ReactNode;
}) {
  return (
    <li>
      <div className="flex items-baseline justify-between gap-3">
        <span className="min-w-0 text-sm">{name}</span>
        <span className="k-num shrink-0 text-sm font-medium whitespace-nowrap text-ink">
          {formatCredits(credits)}
        </span>
      </div>
      <div className="mt-2 flex items-center gap-2">
        <Progress className="flex-1" size="sm" tone={tone} value={credits} max={max} label={barLabel} />
        <span className="k-num w-9 shrink-0 text-right text-xs text-ink-3">{share}</span>
      </div>
      <p className="mt-1.5 text-xs leading-relaxed text-ink-3">{footnote}</p>
    </li>
  );
}

