3	import Link from "next/link";
4	import { useState } from "react";
5	import { LayoutTemplate, Wand2, X } from "lucide-react";
6	import { Badge } from "@/components/ui/Badge";
7	import { Button } from "@/components/ui/Button";
8	import { getTemplate } from "@/lib/templates";
9	import {
10	  TemplatePickerModal,
11	  type TemplatePickerResult,
12	} from "@/components/templates/TemplatePickerModal";
13	import { InlineWizard, type InlineWizardResult } from "@/components/wizard/InlineWizard";
14	import { PromptBox } from "./PromptBox";
15	
16	/* One-tap starters. Short on purpose — these are a way in, not a brief; the
17	   fully-written briefs live behind "Use a template". Each one describes a
18	   site this product can genuinely produce: one page, no backend. */
19	const EXAMPLES = [
20	  "A one-page site for my barbershop with services, prices and hours",
21	  "A portfolio for a freelance product designer",
22	  "A landing page for a project-tracking tool for small agencies",
23	  "A neighbourhood coffee shop page with a drinks list and opening hours",
24	  "A launch page for a hardcover book I'm selling",
25	  "A wedding info page with the schedule, travel and dress code",
26	];
27	
28	export type CreditContext = {
29	  balance: number;
30	  estimate: { low: number; high: number };
31	  cap: { cap: number | null; spent: number; remaining: number | null; reached: boolean };
32	};
33	
34	/**
35	 * A logo handed over by the template picker or the wizard.
36	 *
37	 * `dataUrl` is already a `data:image/png;base64,…` produced by
38	 * components/templates/logo.ts / components/wizard/inline-logo.ts, which both
39	 * exist to satisfy the one gate in app/api/generate/route.ts. It travels to
40	 * that route as the `image` field and reaches the model on attempt 1 — see the
41	 * note in CreateFlow.tsx for why that, and not the brand-kit route, is where a
42	 * logo picked up here can honestly go.
43	 */
44	export type AttachedLogo = { dataUrl: string; bytes: number };
45	
46	/** What a completed helper flow hands back to the page. */
47	export type AssistResult = {
48	  /** Lands in the box, editable. Nothing is ever built without a look at it. */
49	  prompt: string;
50	  logo: AttachedLogo | null;
51	  templateName: string | null;
52	};
53	
54	/** Base64 payload size, minus the `data:image/png;base64,` prefix. */
55	function dataUrlBytes(dataUrl: string): number {
56	  const comma = dataUrl.indexOf(",");
57	  return comma === -1 ? 0 : Math.round((dataUrl.length - comma - 1) * 0.75);
58	}
59	
60	/**
61	 * Make sure the palette a helper flow returned is actually IN the text.
62	 *
63	 * Both flows already write their palette into the prompt they assemble (the
64	 * `- Palette: <id> (#a to #b)` line from lib/wizard.ts and
65	 * components/templates/intake.ts), so in the normal case this changes nothing.
66	 * It exists so that a palette which for any reason did NOT make it into the
67	 * prose is folded in rather than silently dropped — the customer picked those
68	 * colours, and `palette` arriving with nowhere to go would mean it never
69	 * reached the build.
70	 *
71	 * Appended to the composer's own text, not to the request behind the
72	 * customer's back: it is then visible and editable like everything else in the
73	 * box, which is the whole rule for these hand-offs.
74	 */
75	function withPalette(prompt: string, palette: string[] | undefined): string {
76	  if (!palette || palette.length === 0) return prompt;
77	  const lower = prompt.toLowerCase();
78	  if (palette.every((hex) => lower.includes(hex.toLowerCase()))) return prompt;
79	  return `${prompt}\n\nUse these exact colours as the palette: ${palette.join(
80	    ", ",
81	  )}. Make them the dominant colours and derive everything else from those hexes — do not substitute a different palette.`;
82	}
83	
84	export function Composer({
85	  value,
86	  onChange,
87	  logo,
88	  onLogoChange,
89	  onAssist,
90	  onSubmit,
91	  fromTemplate,
92	  credits,
93	  canTopUp,
94	}: {
95	  value: string;
96	  onChange: (v: string) => void;
97	  /** Lifted to the flow so a retry after a refused build keeps the logo the
98	      customer handed over, instead of quietly dropping it. */
99	  logo: AttachedLogo | null;
100	  onLogoChange: (logo: AttachedLogo | null) => void;
101	  onAssist: (result: AssistResult) => void;
102	  onSubmit: () => void;
103	  fromTemplate: string | null;
104	  credits: CreditContext;
105	  /** False when Stripe is not configured — the billing page is still the
106	      credit ledger, but calling the link "Top up" would be a dead end. */
107	  canTopUp: boolean;
108	}) {
109	  // Both helpers open OVER this page rather than navigating to
110	  // /dashboard/templates or /wizard. Leaving the page to fetch a sentence and
111	  // coming back is the thing this replaces; the box the customer was looking
112	  // at stays where it was and simply fills in.
113	  const [pickerOpen, setPickerOpen] = useState(false);
114	  const [wizardOpen, setWizardOpen] = useState(false);
115	
116	  const { balance, estimate, cap } = credits;
117	  const outOfCredits = balance <= 0;
118	  const capReached = cap.reached;
119	  const tight = !outOfCredits && balance < estimate.high;
120	  const capTight = !capReached && cap.remaining !== null && cap.remaining < estimate.high;
121	
122	  const blocked = outOfCredits || capReached;
123	  const ready = value.trim().length > 0 && !blocked;
124	
125	  function acceptTemplate(result: TemplatePickerResult) {
126	    setPickerOpen(false);
127	    onAssist({
128	      prompt: withPalette(result.prompt, result.palette),
129	      logo: result.logoDataUrl
130	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
131	        : null,
132	      templateName: getTemplate(result.templateId)?.name ?? null,
133	    });
134	  }
135	
136	  function acceptWizard(result: InlineWizardResult) {
137	    setWizardOpen(false);
138	    onAssist({
139	      prompt: withPalette(result.prompt, result.palette),
140	      logo: result.logoDataUrl
141	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
142	        : null,
143	      templateName: null,
144	    });
145	  }
146	
147	  return (
148	    <div className="mx-auto w-full max-w-2xl">
149	      <header className="pt-6 text-center sm:pt-14">
150	        <h1 className="k-display text-ink">What do you want to build?</h1>
151	        <p className="mx-auto mt-3 max-w-xl text-[0.9375rem] leading-relaxed text-ink-2">
152	          Describe it in your own words. Kodely writes a real one-page site —
153	          React, Tailwind, your copy — and you keep editing it by asking for
154	          changes.
155	        </p>
156	      </header>
157	
158	      <div className="mt-8">
159	        <PromptBox value={value} onChange={onChange} onSubmit={onSubmit} canSubmit={ready}>
160	          {(fromTemplate !== null || logo !== null) && (
161	            <div className="flex flex-col gap-2 px-6 pt-4">
162	              {fromTemplate !== null && (
163	                <div className="flex flex-wrap items-center gap-2">
164	                  <Badge tone="brand">Started from “{fromTemplate}”</Badge>
165	                  <span className="text-xs text-ink-3">
166	                    It is just text — change anything before you build.
167	                  </span>
168	                </div>
169	              )}
170	
