64	function bucketLabel(b: SpendBucket): string {
65	  if (b.days <= 1) return FULL_DATE.format(new Date(b.ts));
66	  return `${SPAN_DATE.format(new Date(b.ts))} – ${SPAN_DATE.format(new Date(endTs(b)))}`;
