94	  days,
95	  rangeLabel,
96	}: {
97	  buckets: SpendBucket[];
98	  /** Total UTC days the range covers, however they are grouped into bars. */
99	  days: number;
100	  /** How the range reads in a sentence: "the last 30 days", "all time". */
101	  rangeLabel: string;
102	}) {
