114	      />
115	    );
116	  }
117	
118	  const active = buckets.filter((b) => b.credits > 0);
119	  const activeCount = active.length;
120	  const peak = buckets.reduce((best, b) => (b.credits > best.credits ? b : best), buckets[0]);
121	  const max = niceCeiling(peak.credits);
122	
123	  const summary =
124	    `Credits spent per ${unit} over ${rangeLabel}. ` +
125	    `${formatCredits(total)} credits in total across ${activeCount} ` +
