150	        {rangeLabel}, across{" "}
151	        <span className="k-num font-medium text-ink">{activeCount}</span>{" "}
152	        {activeCount === 1 ? unit : `${unit}s`} with any spend. Heaviest {unit}:{" "}
153	        <span className="k-num font-medium text-ink">{formatCredits(peak.credits)}</span> credits,{" "}
154	        {bucketLabel(peak)}.
155	      </figcaption>
