254	              <span className="k-num">{buckets.length}</span>. Each week is seven UTC days except
255	              the earliest, which is trimmed to the start of the range.
256	            </>
257	          ) : (
258	            <>
259	              Days with no spend are left out —{" "}
260	              <span className="k-num">{days - activeCount}</span> of the last{" "}
261	              <span className="k-num">{days}</span>.
262	            </>
263	          )}
264	        </p>
265	      </details>
266	    </figure>
267	  );
