file.content:
  --border-soft: rgba(11, 10, 13, 0.06);
  --border-mid: rgba(11, 10, 13, 0.1);
  --border-strong: rgba(11, 10, 13, 0.18);

  --text-1: #16131c;
  --text-2: #605b6b;
  --text-3: #948da3;
  --text-inv: #ffffff;

  /* Brand, as flat UI colour. --accent is the marketing pink; these add the
     tints a product needs (a fill you can put text on, a focus ring). */
  --brand: #e01b6e;
  --brand-hover: #c4155e;
  --brand-tint: rgba(224, 27, 110, 0.08);
  --brand-tint-2: rgba(224, 27, 110, 0.14);
  --brand-ring: rgba(224, 27, 110, 0.38);
  --brand-ink: #a41050;

  /* Semantic status. Kept clearly OFF the brand ramp: a "success" that reads
     as brand pink is unreadable as status, and the peach in the gradient is
     close enough to amber that warning is pushed yellow-ward to separate. */
  --ok: #0d8f5b;
  --ok-tint: rgba(13, 143, 91, 0.1);
  --warn: #a86a08;
  --warn-tint: rgba(214, 145, 20, 0.14);
  --danger: #cf2b3c;
  --danger-tint: rgba(207, 43, 60, 0.1);
  --info: #5b4ee0;
  --info-tint: rgba(91, 78, 224, 0.1);

  /* Elevation. Two axes deliberately: a neutral drop for depth plus a faint
     violet cast, which is what stops white cards on a white-ish canvas from
     looking like flat rectangles with a border. */
  --e1: 0 1px 2px rgba(11, 10, 13, 0.04);
  --e2:
    0 1px 2px rgba(11, 10, 13, 0.04), 0 8px 20px -12px rgba(90, 40, 140, 0.18);
  --e3:
    0 2px 4px rgba(11, 10, 13, 0.05), 0 24px 48px -24px rgba(90, 40, 140, 0.26);

  /* Radii. "Rounded but not bubbly" — the step from control (10) to card (14)
     to sheet (20) is what reads as considered; one radius everywhere is what
     reads as a Tailwind default. */
  --r-xs: 6px;
  --r-sm: 8px;
  --r-md: 10px;
  --r-lg: 14px;
  --r-xl: 20px;
  --r-2xl: 28px;
  --r-full: 999px;

  /* Motion. One easing for everything that enters or resizes, one for state
     flips. Durations are short on purpose: "fast and expensive", not flashy. */
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-io: cubic-bezier(0.4, 0, 0.2, 1);
  --t-1: 120ms;
  --t-2: 200ms;
  --t-3: 380ms;

  --sidebar-w: 248px;
  --sidebar-w-collapsed: 68px;
  --topbar-h: 60px;
}

