import { UsageChart } from "../(portal)/dashboard/usage/UsageChart";
import { SpendKindDonut } from "../(portal)/dashboard/usage/SpendKindDonut";
import { ActivityTable } from "../(portal)/dashboard/usage/ActivityTable";
import { Card, CardHeader } from "@/components/ui/Card";
import type { SpendBucket } from "../(portal)/dashboard/usage/data";

const now = 1755993600000; // fixed timestamp, avoids Date.now() in a server component
const buckets: SpendBucket[] = Array.from({ length: 30 }, (_, i) => ({
  ts: now - (29 - i) * 86400000,
  days: 1,
  credits: Math.round(Math.max(0, 40 + 35 * Math.sin(i / 3) + (i % 7 === 0 ? 60 : 0))),
}));

export default function TmpUsagePreview() {
  return (
    <div className="mx-auto max-w-6xl space-y-6 p-8" data-theme="dark">
      <Card>
        <CardHeader title="Credits over time" description="preview" />
        <UsageChart buckets={buckets} days={30} rangeLabel="the last 30 days" />
      </Card>
      <Card>
        <CardHeader title="Usage this month" description="preview" />
        <div className="mt-5">
          <SpendKindDonut createCredits={180} editCredits={70} />
        </div>
      </Card>
      <Card>
        <CardHeader title="Recent credit activity" description="preview" />
        <div className="mt-4">
          <ActivityTable
            rows={[
              {
                id: "1",
                createdAt: new Date(now),
                delta: -12,
                reason: "build",
                projectId: "p1",
                projectName: "Soul Pilates Website",
              },
              {
                id: "2",
                createdAt: new Date(now - 3600000),
                delta: -28,
                reason: "build",
                projectId: "p2",
                projectName: "Project Habitat",
              },
              {
                id: "3",
                createdAt: new Date(now - 7200000),
                delta: 500,
                reason: "stripe:pi_test",
                projectId: null,
                projectName: null,
              },
            ]}
          />
        </div>
      </Card>
    </div>
  );
}

