const results = {};
const lineGrad = document.getElementById('usage-line');
results.lineGradientStops = lineGrad ? Array.from(lineGrad.querySelectorAll('stop')).map(s => getComputedStyle(s).stopColor || s.getAttribute('stop-color')) : 'NOT FOUND';
const path = document.querySelector('svg path[stroke]');
results.linePathStroke = path ? path.getAttribute('stroke') : 'NOT FOUND';
const donutCircles = document.querySelectorAll('svg circle[stroke^="url"]');
results.donutStrokes = Array.from(donutCircles).map(c => c.getAttribute('stroke'));
const totalText = document.querySelector('p.bg-clip-text');
results.donutTotalBg = totalText ? getComputedStyle(totalText).backgroundImage : 'NOT FOUND';
results.donutTotalColor = totalText ? getComputedStyle(totalText).color : 'NOT FOUND';
JSON.stringify(results, null, 2);

