30	
31	  return (
32	    <aside
33	      // Reads the shell's custom property rather than branching on the prop:
34	      // one declaration, and the width interpolates instead of swapping.
35	      style={{ width: "var(--shell-sidebar)" }}
36	      className="fixed inset-y-0 left-0 z-40 hidden shrink-0 flex-col border-r border-hair bg-surface transition-[width] duration-[var(--t-2)] ease-[var(--ease)] lg:flex"
37	    >
38	      <div className="flex h-[var(--topbar-h)] items-center gap-2 px-3">
39	        <Link
40	          href="/dashboard"
41	          aria-label="Kodely home"
42	          className="k-focus flex min-w-0 items-center rounded-md px-1.5 py-1"
43	        >
44	          {/* Collapsed, only the mark. Both branches render the SAME <Mark>
45	              component (Logo is Mark + wordmark), so there is one source of
46	              truth for the brand shape and no second asset to keep in sync. */}
47	          {collapsed ? (
48	            <Mark size={22} />
49	          ) : (
50	            <Logo markSize={22} className="text-[0.9375rem]" />
51	          )}
52	        </Link>
53	        {!collapsed && (
54	          <button
55	            type="button"
56	            onClick={onToggle}
57	            aria-label="Collapse sidebar"
58	            title="Collapse sidebar"
59	            // A bordered disc rather than a bare glyph: at the top corner of a
