                active ? "text-brand" : "text-ink-3",
              ].join(" ")}
            >
              <Icon className="size-5" strokeWidth={active ? 2.2 : 1.8} />
              {item.label}
            </Link>
          );
        })}
      </nav>
    </>
  );
}

