function extractConst(src, name) {
  const marker = `const ${name} =`;
  const start = src.indexOf(marker);
  if (start === -1) throw new Error(`could not find ${name}`);
  const quoteStart = src.indexOf('"', start);
  let i = quoteStart + 1;
  let out = "";
  while (src[i] !== '"') {
    if (src[i] === "\\") {
